  6→import { Feature } from "../types";
  7→import {
  8→  FeatureDetectionAlgorithm,
  9→  AlgorithmConfig,
 10→} from "../types/FeatureDetectionAlgorithm";
 11→import { FeatureDetectorConfig } from "../config/types";
 12→
 13→/**
 14→ * 特徴点検出サービス
 15→ * 複数のアルゴリズムによる特徴点検出を統合管理
 16→ */
 17→export class FeatureDetectionService {
 18→  private cv: typeof cv;
 19→  private config: FeatureDetectorConfig;
 20→  private nextFeatureId: number = 0;
 21→  private currentDescriptors: cv.Mat | null = null;
 22→
 23→  constructor(cvInstance: typeof cv, config: FeatureDetectorConfig) {
 24→    this.cv = cvInstance;
 25→    this.config = config;
 26→  }
 27→
 28→  /**
 29→   * 設定されたアルゴリズムで特徴点を検出
 30→   */
 31→  public detectFeatures(image: cv.Mat, mask: cv.Mat): Feature[] {
 32→    const allFeatures: Feature[][] = [];
 33→    const algorithmWeights: number[] = [];
 34→
 35→    // 各アルゴリズムで特徴点検出を実行
 36→    for (const algorithmConfig of this.config.algorithms) {
 37→      try {
 38→        const features = this.detectWithAlgorithm(image, mask, algorithmConfig);
 39→        allFeatures.push(features);
 40→
 41→        // 重みを取得
 42→        const weight =
 43→          this.config.algorithmWeights?.[algorithmConfig.algorithm] || 1.0;
 44→        algorithmWeights.push(weight);
 45→      } catch (error) {
 46→        console.warn(
 47→          `Failed to detect features with ${algorithmConfig.algorithm}:`,
 48→          error
 49→        );
 50→        allFeatures.push([]);
 51→        algorithmWeights.push(0);
 52→      }
 53→    }
 54→
 55→    // 複数アルゴリズムの結果を統合
 56→    return this.mergeFeatures(allFeatures, algorithmWeights);
 57→  }
 58→
 59→  /**
 60→   * 指定されたアルゴリズムで特徴点検出
 61→   */
 62→  private detectWithAlgorithm(
 63→    image: cv.Mat,
 64→    mask: cv.Mat,
 65→    algorithmConfig: AlgorithmConfig
 66→  ): Feature[] {
 67→    switch (algorithmConfig.algorithm) {
 68→      case FeatureDetectionAlgorithm.HARRIS:
 69→        return this.detectHarrisFeatures(image, mask);
 70→
 71→      case FeatureDetectionAlgorithm.SHI_TOMASI:
 72→        return this.detectShiTomasiFeatures(image, mask);
 73→
 74→      case FeatureDetectionAlgorithm.FAST:
 75→        return this.detectFastFeatures(image, mask);
 76→
 77→      case FeatureDetectionAlgorithm.ORB:
 78→        return this.detectOrbFeatures(image, mask);
 79→
 80→      case FeatureDetectionAlgorithm.SIFT:
 81→        return this.detectSiftFeatures(image, mask);
 82→
 83→      default:
 84→        throw new Error(`Unsupported algorithm: ${algorithmConfig.algorithm}`);
 85→    }
 86→  }
 87→
 88→  /**
 89→   * Harris Corner Detection
 90→   */
 91→  private detectHarrisFeatures(image: cv.Mat, _mask: cv.Mat): Feature[] {
 92→    const params = this.config.algorithmParams.harris!;
 93→    const corners = new this.cv.Mat();
 94→
 95→    this.cv.cornerHarris(image, corners, params.blockSize, 3, params.k);
 96→
 97→    // 非極大値抑制と閾値処理
 98→    const features: Feature[] = [];
 99→    const data = corners.data32F;
100→    const { rows, cols } = corners;
101→
102→    for (let y = 1; y < rows - 1; y++) {
103→      for (let x = 1; x < cols - 1; x++) {
104→        const idx = y * cols + x;
105→        const value = data[idx];
106→
107→        if (value > params.threshold) {
108→          // 近傍で最大値かチェック
109→          let isMaximum = true;
110→          for (let dy = -1; dy <= 1; dy++) {
111→            for (let dx = -1; dx <= 1; dx++) {
112→              if (dx === 0 && dy === 0) continue;
113→              const neighborIdx = (y + dy) * cols + (x + dx);
114→              if (data[neighborIdx] >= value) {
115→                isMaximum = false;
116→                break;
117→              }
118→            }
119→            if (!isMaximum) break;
120→          }
121→
122→          if (isMaximum) {
123→            features.push({
124→              x,
125→              y,
126→              trackingCount: 1,
127→              id: this.generateFeatureId(),
128→              score: value,
129→            });
130→          }
131→        }
132→      }
133→    }
134→
135→    corners.delete();
136→    return this.limitAndSortFeatures(features);
137→  }
138→
139→  /**
140→   * Shi-Tomasi Corner Detection (goodFeaturesToTrack)
141→   */
142→  private detectShiTomasiFeatures(image: cv.Mat, mask: cv.Mat): Feature[] {
143→    const params = this.config.algorithmParams.shiTomasi!;
144→    const points = new this.cv.Mat();
145→
146→    this.cv.goodFeaturesToTrack(
147→      image,
148→      points,
149→      this.config.maxCorners,
150→      params.qualityLevel,
151→      params.minDistance,
152→      mask,
153→      params.blockSize,
154→      params.useHarrisDetector,
155→      params.k
156→    );
157→
158→    const features: Feature[] = [];
159→    for (let i = 0; i < points.rows; i++) {
160→      features.push({
161→        x: points.data32F[i * 2],
162→        y: points.data32F[i * 2 + 1],
163→        trackingCount: 1,
164→        id: this.generateFeatureId(),
165→      });
166→    }
167→
168→    points.delete();
169→    return features;
170→  }
171→
172→  /**
173→   * FAST Feature Detection
174→   */
175→  private detectFastFeatures(image: cv.Mat, mask: cv.Mat): Feature[] {
176→    const params = this.config.algorithmParams.fast!;
177→    const keypoints = new this.cv.KeyPointVector();
178→    const detector = this.cv.FastFeatureDetector_create(
179→      params.threshold,
180→      params.nonmaxSuppression,
181→      params.type
182→    );
183→
184→    detector.detect(image, keypoints, mask);
185→
186→    const features: Feature[] = [];
187→    for (let i = 0; i < keypoints.size(); i++) {
188→      const kp = keypoints.get(i);
189→      features.push({
190→        x: kp.pt.x,
191→        y: kp.pt.y,
192→        trackingCount: 1,
193→        id: this.generateFeatureId(),
194→        score: kp.response,
195→      });
196→    }
197→
198→    detector.delete();
199→    keypoints.delete();
200→    return this.limitAndSortFeatures(features);
201→  }
202→
203→  /**
204→   * ORB Feature Detection
205→   */
206→  private detectOrbFeatures(image: cv.Mat, mask: cv.Mat): Feature[] {
207→    const params = this.config.algorithmParams.orb!;
208→    const keypoints = new this.cv.KeyPointVector();
209→    const descriptors = new this.cv.Mat();
210→
211→    const detector = this.cv.ORB_create(
212→      params.nfeatures,
213→      params.scaleFactor,
214→      params.nlevels,
215→      params.edgeThreshold,
216→      params.firstLevel,
217→      params.WTA_K,
218→      params.scoreType,
219→      params.patchSize,
220→      params.fastThreshold
221→    );
222→
223→    detector.detectAndCompute(image, mask, keypoints, descriptors);
224→
225→    const features: Feature[] = [];
226→    for (let i = 0; i < keypoints.size(); i++) {
227→      const kp = keypoints.get(i);
228→      features.push({
229→        x: kp.pt.x,
230→        y: kp.pt.y,
231→        trackingCount: 1,
232→        id: this.generateFeatureId(),
233→        score: kp.response,
234→        angle: kp.angle,
235→        octave: kp.octave,
236→      });
237→    }
238→
239→    detector.delete();
240→    keypoints.delete();
241→
242→    // Store descriptors for pose estimation (caller manages lifecycle)
243→    this.disposeDescriptors();
244→    this.currentDescriptors = descriptors;
245→
246→    return this.limitAndSortFeatures(features);
247→  }
248→
249→  /**
250→   * SIFT Feature Detection
251→   */
252→  private detectSiftFeatures(image: cv.Mat, mask: cv.Mat): Feature[] {
253→    const params = this.config.algorithmParams.sift!;
254→    const keypoints = new this.cv.KeyPointVector();
255→    const descriptors = new this.cv.Mat();
256→
257→    const detector = this.cv.SIFT_create(
258→      params.nfeatures,
259→      params.nOctaveLayers,
260→      params.contrastThreshold,
261→      params.edgeThreshold,
262→      params.sigma
263→    );
264→
265→    detector.detectAndCompute(image, mask, keypoints, descriptors);
266→
267→    const features: Feature[] = [];
268→    for (let i = 0; i < keypoints.size(); i++) {
269→      const kp = keypoints.get(i);
270→      features.push({
271→        x: kp.pt.x,
272→        y: kp.pt.y,
273→        trackingCount: 1,
274→        id: this.generateFeatureId(),
275→        score: kp.response,
276→        angle: kp.angle,
277→        octave: kp.octave,
278→        size: kp.size,
279→      });
280→    }
281→
282→    detector.delete();
283→    keypoints.delete();
284→
285→    // Store descriptors for pose estimation (caller manages lifecycle)
286→    this.disposeDescriptors();
287→    this.currentDescriptors = descriptors;
288→
289→    return this.limitAndSortFeatures(features);
290→  }
291→
292→  /**
293→   * 複数アルゴリズムの特徴点を統合
294→   */
295→  private mergeFeatures(
296→    featureSets: Feature[][],
297→    weights: number[]
298→  ): Feature[] {
299→    if (featureSets.length === 0) return [];
300→    if (featureSets.length === 1) return featureSets[0];
301→
302→    switch (this.config.mergeStrategy) {
303→      case "union":
304→        return this.mergeUnion(featureSets);
305→
306→      case "intersection":
307→        return this.mergeIntersection(featureSets);
308→
309→      case "weighted":
310→        return this.mergeWeighted(featureSets, weights);
311→
312→      default:
313→        return this.mergeUnion(featureSets);
314→    }
315→  }
316→
317→  /**
318→   * 和集合による統合
319→   */
320→  private mergeUnion(featureSets: Feature[][]): Feature[] {
321→    const allFeatures: Feature[] = [];
322→    const distanceThreshold = this.config.minDistance;
323→
324→    for (const features of featureSets) {
325→      for (const feature of features) {
326→        // 既存の特徴点と重複していないかチェック
327→        const isDuplicate = allFeatures.some((existing) => {
328→          const distance = Math.sqrt(
329→            Math.pow(existing.x - feature.x, 2) +
330→              Math.pow(existing.y - feature.y, 2)
331→          );
332→          return distance < distanceThreshold;
333→        });
334→
335→        if (!isDuplicate) {
336→          allFeatures.push(feature);
337→        }
338→      }
339→    }
340→
341→    return this.limitAndSortFeatures(allFeatures);
342→  }
343→
344→  /**
345→   * 積集合による統合（近接する特徴点のみ）
346→   */
347→  private mergeIntersection(featureSets: Feature[][]): Feature[] {
348→    if (featureSets.length === 0) return [];
349→
350→    const firstSet = featureSets[0];
351→    const commonFeatures: Feature[] = [];
352→    const distanceThreshold = this.config.minDistance * 2;
353→
354→    for (const feature of firstSet) {
355→      let isCommon = true;
356→
357→      for (let i = 1; i < featureSets.length; i++) {
358→        const hasNearby = featureSets[i].some((other) => {
359→          const distance = Math.sqrt(
360→            Math.pow(other.x - feature.x, 2) + Math.pow(other.y - feature.y, 2)
361→          );
362→          return distance < distanceThreshold;
363→        });
364→
365→        if (!hasNearby) {
366→          isCommon = false;
367→          break;
368→        }
369→      }
370→
371→      if (isCommon) {
372→        commonFeatures.push(feature);
373→      }
374→    }
375→
376→    return commonFeatures;
377→  }
378→
379→  /**
380→   * 重み付き統合
381→   */
382→  private mergeWeighted(
383→    featureSets: Feature[][],
384→    weights: number[]
385→  ): Feature[] {
386→    const mergedFeatures: Feature[] = [];
387→    const distanceThreshold = this.config.minDistance;
388→
389→    // 重み付きスコアで特徴点を評価
390→    for (let i = 0; i < featureSets.length; i++) {
391→      const features = featureSets[i];
392→      const weight = weights[i];
393→
394→      for (const feature of features) {
395→        const weightedScore = (feature.score || 1.0) * weight;
396→
397→        // 近接する既存特徴点を検索
398→        const nearbyIndex = mergedFeatures.findIndex((existing) => {
399→          const distance = Math.sqrt(
400→            Math.pow(existing.x - feature.x, 2) +
401→              Math.pow(existing.y - feature.y, 2)
402→          );
403→          return distance < distanceThreshold;
404→        });
405→
406→        if (nearbyIndex >= 0) {
407→          // 既存の特徴点とスコアを比較
408→          const existingScore = mergedFeatures[nearbyIndex].score || 1.0;
409→          if (weightedScore > existingScore) {
410→            mergedFeatures[nearbyIndex] = {
411→              ...feature,
412→              score: weightedScore,
413→            };
414→          }
415→        } else {
416→          // 新しい特徴点として追加
417→          mergedFeatures.push({
418→            ...feature,
419→            score: weightedScore,
420→          });
421→        }
422→      }
423→    }
424→
425→    return this.limitAndSortFeatures(mergedFeatures);
426→  }
427→
428→  /**
429→   * 特徴点を制限し、スコア順にソート
430→   */
431→  private limitAndSortFeatures(features: Feature[]): Feature[] {
432→    // スコア順にソート（高い順）
433→    features.sort((a, b) => (b.score || 0) - (a.score || 0));
434→
435→    // 最大数に制限
436→    return features.slice(0, this.config.maxCorners);
437→  }
438→
439→  /**
440→   * 特徴点IDを生成
441→   */
442→  private generateFeatureId(): string {
443→    return `feature_${this.nextFeatureId++}`;
444→  }
445→
446→  /**
447→   * 設定を更新
448→   */
449→  public updateConfig(config: FeatureDetectorConfig): void {
450→    this.config = config;
451→  }
452→
453→  /**
454→   * Get current descriptors for pose estimation
455→   * Caller should NOT delete the returned Mat
456→   */
457→  public getDescriptors(): cv.Mat | null {
458→    return this.currentDescriptors;
459→  }
460→
461→  /**
462→   * Dispose stored descriptors
463→   * Call when descriptors are no longer needed
464→   */
465→  public disposeDescriptors(): void {
466→    if (this.currentDescriptors) {
467→      this.currentDescriptors.delete();
468→      this.currentDescriptors = null;
469→    }
470→  }
471→}
