  6→import { AutoModel, AutoProcessor, RawImage } from "@huggingface/transformers";
  7→import {
  8→  DepthEstimationModel,
  9→  InferenceEngine,
 10→  DepthMapResult,
 11→} from "../types/DepthEstimationModel";
 12→import { DepthEstimationConfig } from "../config/types";
 13→import type {
 14→  DepthModel,
 15→  DepthProcessor,
 16→  DepthTensor,
 17→} from "../types/Transformers";
 18→
 19→/**
 20→ * 深度推定サービス
 21→ * 複数のモデルと推論エンジンをサポート
 22→ */
 23→export class DepthEstimationService {
 24→  private config: DepthEstimationConfig;
 25→  private models: Map<string, DepthModel> = new Map();
 26→  private processors: Map<string, DepthProcessor> = new Map();
 27→  private currentModelId: string;
 28→  private isProcessing: boolean = false;
 29→
 30→  // キャッシュ
 31→  private frameCache: Map<string, DepthMapResult> = new Map();
 32→  // private lastFrameHash: string = "";
 33→
 34→  // パフォーマンス計測
 35→  private frameCount: number = 0;
 36→  private totalInferenceTime: number = 0;
 37→
 38→  constructor(config: DepthEstimationConfig) {
 39→    this.config = config;
 40→    this.currentModelId = config.modelId;
 41→  }
 42→
 43→  /**
 44→   * モデルを読み込み
 45→   */
 46→  async loadModel(modelId?: string): Promise<void> {
 47→    const targetModelId = modelId || this.config.modelId;
 48→
 49→    // 既に読み込み済みの場合はスキップ
 50→    if (this.models.has(targetModelId)) {
 51→      this.currentModelId = targetModelId;
 52→      return;
 53→    }
 54→
 55→    try {
 56→      // エンジン設定を決定
 57→      const engineConfig = this.getEngineConfig();
 58→
 59→      // モデルとプロセッサを読み込み
 60→      const model = await AutoModel.from_pretrained(
 61→        targetModelId,
 62→        engineConfig
 63→      );
 64→      const processor = await AutoProcessor.from_pretrained(targetModelId, {});
 65→
 66→      // 入力サイズを設定
 67→      const inputSize = this.getInputSizeForModel(targetModelId);
 68→      // 入力サイズを設定（プロセッサの構造に依存）
 69→      try {
 70→        const typedProcessor = processor as unknown as DepthProcessor;
 71→        if (typedProcessor.feature_extractor) {
 72→          typedProcessor.feature_extractor.size = {
 73→            width: inputSize,
 74→            height: inputSize,
 75→          };
 76→        }
 77→      } catch (e) {
 78→        console.log("Could not set processor input size:", e);
 79→      }
 80→
 81→      // 保存
 82→      this.models.set(targetModelId, model as unknown as DepthModel);
 83→      this.processors.set(
 84→        targetModelId,
 85→        processor as unknown as DepthProcessor
 86→      );
 87→      this.currentModelId = targetModelId;
 88→
 89→      console.log(`Loaded depth estimation model: ${targetModelId}`);
 90→    } catch (error) {
 91→      console.error(`Failed to load model ${targetModelId}:`, error);
 92→      throw error;
 93→    }
 94→  }
 95→
 96→  /**
 97→   * エンジン設定を取得
 98→   */
 99→  private getEngineConfig(): Record<string, unknown> {
100→    const pipeline = this.config.pipeline;
101→
102→    if (!pipeline?.engine) {
103→      // デフォルト設定
104→      return {
105→        device: this.config.device || "webgpu",
106→        dtype: "fp32",
107→      };
108→    }
109→
110→    const engine = pipeline.engine.engine;
111→    const precision = pipeline.engine.precision || "fp32";
112→
113→    switch (engine) {
114→      case InferenceEngine.WEBGPU:
115→        return {
116→          device: "webgpu",
117→          dtype: precision === "fp16" ? "fp16" : "fp32",
118→          ...pipeline.engine.engineOptions,
119→        };
120→
121→      case InferenceEngine.WEBGL:
122→        return {
123→          device: "webgl",
124→          dtype: "fp32",
125→          ...pipeline.engine.engineOptions,
126→        };
127→
128→      case InferenceEngine.WASM:
129→        return {
130→          device: "wasm",
131→          dtype: "fp32",
132→          ...pipeline.engine.engineOptions,
133→        };
134→
135→      case InferenceEngine.ONNX:
136→        return {
137→          device: "onnx",
138→          dtype: precision,
139→          ...pipeline.engine.engineOptions,
140→        };
141→
142→      default:
143→        return {
144→          device: this.config.device || "webgpu",
145→          dtype: "fp32",
146→        };
147→    }
148→  }
149→
150→  /**
151→   * モデルに応じた入力サイズを取得
152→   */
153→  private getInputSizeForModel(modelId: string): number {
154→    const modelConfig = this.config.pipeline?.model;
155→    if (modelConfig?.inputSize) {
156→      return modelConfig.inputSize;
157→    }
158→
159→    // モデル別のデフォルトサイズ
160→    switch (modelId) {
161→      case DepthEstimationModel.DEPTH_ANYTHING_V2_SMALL:
162→      case DepthEstimationModel.DEPTH_ANYTHING_V2_BASE:
163→      case DepthEstimationModel.DEPTH_ANYTHING_V2_LARGE:
164→        return 504;
165→
166→      case DepthEstimationModel.MIDAS_SMALL:
167→        return 256;
168→
169→      case DepthEstimationModel.MIDAS_DPT_HYBRID:
170→      case DepthEstimationModel.MIDAS_DPT_LARGE:
171→        return 384;
172→
173→      case DepthEstimationModel.ZOE_DEPTH:
174→        return 512;
175→
176→      default:
177→        return this.config.inputSize || 504;
178→    }
179→  }
180→
181→  /**
182→   * 深度マップを推定
183→   */
184→  async estimateDepth(
185→    imageData: ImageData,
186→    useCache: boolean = true
187→  ): Promise<DepthMapResult | null> {
188→    if (this.isProcessing) {
189→      console.warn("Depth estimation already in progress");
190→      return null;
191→    }
192→
193→    // キャッシュチェック
194→    if (useCache && this.config.cache?.enableFrameCache) {
195→      const hash = this.computeImageHash(imageData);
196→      const cached = this.frameCache.get(hash);
197→
198→      if (cached && this.isCacheValid(cached)) {
199→        return cached;
200→      }
201→    }
202→
203→    // フレームスキップチェック
204→    if (this.shouldSkipFrame()) {
205→      return null;
206→    }
207→
208→    this.isProcessing = true;
209→    const startTime = performance.now();
210→
211→    try {
212→      const model = this.models.get(this.currentModelId);
213→      const processor = this.processors.get(this.currentModelId);
214→
215→      if (!model || !processor) {
216→        throw new Error("Model not loaded");
217→      }
218→
219→      // 画像を準備
220→      const image = new RawImage(
221→        imageData.data,
222→        imageData.width,
223→        imageData.height,
224→        4
225→      );
226→
227→      // 推論実行
228→      const inputs = await processor(image);
229→      const { predicted_depth } = await model(inputs);
230→
231→      // 結果を処理
232→      const result = this.processDepthOutput(
233→        predicted_depth,
234→        imageData.width,
235→        imageData.height,
236→        performance.now() - startTime
237→      );
238→
239→      // 後処理
240→      if (this.config.pipeline?.postProcessing) {
241→        this.applyPostProcessing(result);
242→      }
243→
244→      // キャッシュに保存
245→      if (useCache && this.config.cache?.enableFrameCache) {
246→        this.updateCache(imageData, result);
247→      }
248→
249→      // パフォーマンス統計を更新
250→      this.updatePerformanceStats(result.inferenceTime || 0);
251→
252→      return result;
253→    } catch (error) {
254→      console.error("Depth estimation failed:", error);
255→      return null;
256→    } finally {
257→      this.isProcessing = false;
258→    }
259→  }
260→
261→  /**
262→   * 深度出力を処理
263→   */
264→  private processDepthOutput(
265→    predicted_depth: DepthTensor,
266→    _originalWidth: number,
267→    _originalHeight: number,
268→    inferenceTime: number
269→  ): DepthMapResult {
270→    const depthData = predicted_depth.data as Float32Array;
271→    const [, height, width] = predicted_depth.dims;
272→
273→    // 最小値と最大値を計算
274→    let minDepth = Infinity;
275→    let maxDepth = -Infinity;
276→
277→    for (let i = 0; i < depthData.length; i++) {
278→      const value = depthData[i];
279→      if (value < minDepth) minDepth = value;
280→      if (value > maxDepth) maxDepth = value;
281→    }
282→
283→    return {
284→      data: depthData,
285→      width,
286→      height,
287→      minDepth,
288→      maxDepth,
289→      timestamp: Date.now(),
290→      inferenceTime,
291→    };
292→  }
293→
294→  /**
295→   * 後処理を適用
296→   */
297→  private applyPostProcessing(result: DepthMapResult): void {
298→    const postProcessing = this.config.pipeline?.postProcessing;
299→    if (!postProcessing) return;
300→
301→    if (postProcessing.gaussianBlur) {
302→      this.applyGaussianBlur(result);
303→    }
304→
305→    if (postProcessing.bilateralFilter) {
306→      this.applyBilateralFilter(result);
307→    }
308→
309→    if (postProcessing.temporalSmoothing) {
310→      this.applyTemporalSmoothing(result);
311→    }
312→  }
313→
314→  /**
315→   * ガウシアンブラーを適用
316→   */
317→  private applyGaussianBlur(result: DepthMapResult): void {
318→    // 簡易的な3x3ガウシアンフィルタ
319→    const kernel = [
320→      [1 / 16, 2 / 16, 1 / 16],
321→      [2 / 16, 4 / 16, 2 / 16],
322→      [1 / 16, 2 / 16, 1 / 16],
323→    ];
324→
325→    const { data, width, height } = result;
326→    const output = new Float32Array(data.length);
327→
328→    for (let y = 1; y < height - 1; y++) {
329→      for (let x = 1; x < width - 1; x++) {
330→        let sum = 0;
331→
332→        for (let ky = -1; ky <= 1; ky++) {
333→          for (let kx = -1; kx <= 1; kx++) {
334→            const idx = (y + ky) * width + (x + kx);
335→            sum += data[idx] * kernel[ky + 1][kx + 1];
336→          }
337→        }
338→
339→        output[y * width + x] = sum;
340→      }
341→    }
342→
343→    // エッジ部分はコピー
344→    for (let x = 0; x < width; x++) {
345→      output[x] = data[x];
346→      output[(height - 1) * width + x] = data[(height - 1) * width + x];
347→    }
348→    for (let y = 0; y < height; y++) {
349→      output[y * width] = data[y * width];
350→      output[y * width + width - 1] = data[y * width + width - 1];
351→    }
352→
353→    result.data = output;
354→  }
355→
356→  /**
357→   * バイラテラルフィルタを適用（簡易版）
358→   */
359→  private applyBilateralFilter(result: DepthMapResult): void {
360→    const { data, width, height } = result;
361→    const output = new Float32Array(data.length);
362→    const spatialSigma = 2.0;
363→    const depthSigma = 0.1;
364→
365→    for (let y = 0; y < height; y++) {
366→      for (let x = 0; x < width; x++) {
367→        const centerIdx = y * width + x;
368→        const centerDepth = data[centerIdx];
369→
370→        let weightSum = 0;
371→        let valueSum = 0;
372→
373→        // 5x5ウィンドウ
374→        for (let dy = -2; dy <= 2; dy++) {
375→          for (let dx = -2; dx <= 2; dx++) {
376→            const ny = y + dy;
377→            const nx = x + dx;
378→
379→            if (ny >= 0 && ny < height && nx >= 0 && nx < width) {
380→              const idx = ny * width + nx;
381→              const depth = data[idx];
382→
383→              // 空間的重み
384→              const spatialDist = Math.sqrt(dx * dx + dy * dy);
385→              const spatialWeight = Math.exp(
386→                -(spatialDist * spatialDist) / (2 * spatialSigma * spatialSigma)
387→              );
388→
389→              // 深度差による重み
390→              const depthDiff = Math.abs(depth - centerDepth);
391→              const depthWeight = Math.exp(
392→                -(depthDiff * depthDiff) / (2 * depthSigma * depthSigma)
393→              );
394→
395→              const weight = spatialWeight * depthWeight;
396→              weightSum += weight;
397→              valueSum += depth * weight;
398→            }
399→          }
400→        }
401→
402→        output[centerIdx] = valueSum / weightSum;
403→      }
404→    }
405→
406→    result.data = output;
407→  }
408→
409→  /**
410→   * 時間的平滑化を適用
411→   */
412→  private previousDepthMap: Float32Array | null = null;
413→  private applyTemporalSmoothing(result: DepthMapResult): void {
414→    if (!this.previousDepthMap) {
415→      this.previousDepthMap = new Float32Array(result.data);
416→      return;
417→    }
418→
419→    const alpha = 0.7; // 現在フレームの重み
420→    const { data } = result;
421→
422→    for (let i = 0; i < data.length; i++) {
423→      data[i] = alpha * data[i] + (1 - alpha) * this.previousDepthMap[i];
424→    }
425→
426→    this.previousDepthMap = new Float32Array(data);
427→  }
428→
429→  /**
430→   * 画像のハッシュを計算（簡易版）
431→   */
432→  private computeImageHash(imageData: ImageData): string {
433→    // 単純なサンプリングベースのハッシュ
434→    const step = Math.floor(imageData.data.length / 1000);
435→    let hash = "";
436→
437→    for (let i = 0; i < imageData.data.length; i += step) {
438→      hash += imageData.data[i].toString(16);
439→    }
440→
441→    return hash;
442→  }
443→
444→  /**
445→   * キャッシュが有効かチェック
446→   */
447→  private isCacheValid(cached: DepthMapResult): boolean {
448→    const ttl = this.config.cache?.cacheTTL || 1000;
449→    return Date.now() - cached.timestamp < ttl;
450→  }
451→
452→  /**
453→   * キャッシュを更新
454→   */
455→  private updateCache(imageData: ImageData, result: DepthMapResult): void {
456→    const hash = this.computeImageHash(imageData);
457→    this.frameCache.set(hash, result);
458→
459→    // Remove expired entries and enforce size limit
460→    this.pruneCache();
461→  }
462→
463→  /**
464→   * Remove expired cache entries and enforce size limit
465→   */
466→  private pruneCache(): void {
467→    const maxSize = this.config.cache?.cacheSize || 10;
468→    const ttl = this.config.cache?.cacheTTL || 1000;
469→    const now = Date.now();
470→
471→    // Remove expired entries
472→    for (const [key, value] of this.frameCache) {
473→      if (now - value.timestamp > ttl) {
474→        this.frameCache.delete(key);
475→      }
476→    }
477→
478→    // Enforce size limit (remove oldest entries)
479→    while (this.frameCache.size > maxSize) {
480→      const firstKey = this.frameCache.keys().next().value;
481→      if (firstKey) {
482→        this.frameCache.delete(firstKey);
483→      } else {
484→        break;
485→      }
486→    }
487→  }
488→
489→  /**
490→   * フレームをスキップすべきかチェック
491→   */
492→  private shouldSkipFrame(): boolean {
493→    const skipFrames = this.config.performance?.skipFrames || 0;
494→    if (skipFrames === 0) return false;
495→
496→    this.frameCount++;
497→    return this.frameCount % (skipFrames + 1) !== 0;
498→  }
499→
500→  /**
501→   * パフォーマンス統計を更新
502→   */
503→  private updatePerformanceStats(inferenceTime: number): void {
504→    this.totalInferenceTime += inferenceTime;
505→
506→    // 適応的品質調整
507→    if (this.config.performance?.adaptiveQuality) {
508→      const avgInferenceTime = this.totalInferenceTime / this.frameCount;
509→      const targetFPS = this.config.performance.maxFPS || 30;
510→      const targetFrameTime = 1000 / targetFPS;
511→
512→      if (avgInferenceTime > targetFrameTime) {
513→        // 品質を下げる必要がある
514→        console.log(
515→          `Performance warning: avg inference time ${avgInferenceTime}ms exceeds target ${targetFrameTime}ms`
516→        );
517→      }
518→    }
519→  }
520→
521→  /**
522→   * モデルを切り替え
523→   */
524→  async switchModel(modelId: string): Promise<void> {
525→    await this.loadModel(modelId);
526→    this.clearCache();
527→  }
528→
529→  /**
530→   * キャッシュをクリア
531→   */
532→  clearCache(): void {
533→    this.frameCache.clear();
534→    this.previousDepthMap = null;
535→  }
536→
537→  /**
538→   * 利用可能なモデルを取得
539→   */
540→  getAvailableModels(): string[] {
541→    const models =
542→      this.config.availableModels || Object.values(DepthEstimationModel);
543→    return models.map((m) => m.toString());
544→  }
545→
546→  /**
547→   * 現在のモデルIDを取得
548→   */
549→  getCurrentModelId(): string {
550→    return this.currentModelId;
551→  }
552→
553→  /**
554→   * パフォーマンス統計を取得
555→   */
556→  getPerformanceStats(): {
557→    averageInferenceTime: number;
558→    totalFrames: number;
559→  } {
560→    return {
561→      averageInferenceTime:
562→        this.frameCount > 0 ? this.totalInferenceTime / this.frameCount : 0,
563→      totalFrames: this.frameCount,
564→    };
565→  }
566→
567→  /**
568→   * 設定を更新
569→   */
570→  updateConfig(config: Partial<DepthEstimationConfig>): void {
571→    this.config = { ...this.config, ...config };
572→  }
573→}
