  6→/**
  7→ * SPALAM設定型定義
  8→ */
  9→
 10→import {
 11→  FeatureDetectionAlgorithm,
 12→  AlgorithmConfig,
 13→  HarrisParams,
 14→  ShiTomasiParams,
 15→  FastParams,
 16→  OrbParams,
 17→  SiftParams,
 18→} from "../types/FeatureDetectionAlgorithm";
 19→
 20→import {
 21→  DepthEstimationModel,
 22→  DepthPipelineConfig,
 23→} from "../types/DepthEstimationModel";
 24→
 25→import {
 26→  RenderingConfig,
 27→  LightConfig,
 28→  CameraConfig,
 29→  AnimationConfig,
 30→} from "../types/RenderingTypes";
 31→
 32→/**
 33→ * 特徴点検出の設定
 34→ */
 35→export interface FeatureDetectorConfig {
 36→  /** 最大特徴点数 */
 37→  maxCorners: number;
 38→  /** 特徴点の質（小さいほど高品質） */
 39→  qualityLevel: number;
 40→  /** 特徴点間の最小距離 */
 41→  minDistance: number;
 42→  /** 特徴点検出のための近傍領域のサイズ（奇数） */
 43→  blockSize: number;
 44→  /** Harrisコーナー検出器を使用するか */
 45→  useHarrisDetector: boolean;
 46→  /** Harrisコーナー検出器のパラメータ（通常0.04-0.06） */
 47→  k: number;
 48→  /** 特徴点表示を有効にするか */
 49→  showFeatures: boolean;
 50→  /** 安定した特徴点と判定するための最小追跡フレーム数 */
 51→  minTrackingCount: number;
 52→  /** ROI（関心領域）の設定 */
 53→  roi: {
 54→    /** X座標のオフセット（画像幅に対する比率） */
 55→    xOffset: number;
 56→    /** Y座標のオフセット（画像高さに対する比率） */
 57→    yOffset: number;
 58→    /** 幅（画像幅に対する比率） */
 59→    width: number;
 60→    /** 高さ（画像高さに対する比率） */
 61→    height: number;
 62→  };
 63→  /** 使用する特徴点検出アルゴリズム */
 64→  algorithms: AlgorithmConfig[];
 65→  /** アルゴリズム固有のパラメータ設定 */
 66→  algorithmParams: {
 67→    harris?: HarrisParams;
 68→    shiTomasi?: ShiTomasiParams;
 69→    fast?: FastParams;
 70→    orb?: OrbParams;
 71→    sift?: SiftParams;
 72→  };
 73→  /** Web Worker を使用するか */
 74→  useWebWorker: boolean;
 75→  /** 特徴点の統合戦略 */
 76→  mergeStrategy: "union" | "intersection" | "weighted";
 77→  /** 重み付きマージ時の重み設定 */
 78→  algorithmWeights?: Record<FeatureDetectionAlgorithm, number>;
 79→}
 80→
 81→/**
 82→ * 深度推定の設定
 83→ */
 84→export interface DepthEstimationConfig {
 85→  /** 使用するモデルID */
 86→  modelId: string;
 87→  /** 推論デバイス */
 88→  device: "cpu" | "webgpu";
 89→  /** 深度マップ表示を有効にするか */
 90→  showDepth: boolean;
 91→  /** モデル入力サイズ */
 92→  inputSize: number;
 93→  /** 利用可能なモデルリスト */
 94→  availableModels?: DepthEstimationModel[];
 95→  /** パイプライン設定 */
 96→  pipeline?: DepthPipelineConfig;
 97→  /** キャッシュ設定 */
 98→  cache?: {
 99→    /** フレームキャッシュを有効にするか */
100→    enableFrameCache: boolean;
101→    /** キャッシュサイズ */
102→    cacheSize: number;
103→    /** キャッシュ有効期限（ミリ秒） */
104→    cacheTTL: number;
105→  };
106→  /** パフォーマンス設定 */
107→  performance?: {
108→    /** スキップフレーム数 */
109→    skipFrames: number;
110→    /** 最大FPS */
111→    maxFPS: number;
112→    /** 適応的品質調整 */
113→    adaptiveQuality: boolean;
114→  };
115→}
