117→/**
118→ * カメラ内部パラメータの設定
119→ */
120→export interface CameraIntrinsicsConfig {
121→  /** 水平視野角（度） - 焦点距離の計算に使用 */
122→  horizontalFov: number;
123→  /** 焦点距離（ピクセル単位） - 直接指定する場合。nullの場合はFoVから計算 */
124→  focalLengthPixels: number | null;
