129→/**
130→ * 平面推定の設定
131→ */
132→export interface PlaneEstimationConfig {
133→  /** RANSACの反復回数 */
134→  ransacIterations: number;
135→  /** RANSACのインライア判定閾値 */
136→  ransacThreshold: number;
137→  /** 平滑化の反復回数 */
138→  smoothingIterations: number;
139→  /** 深度フィルタのデルタ値 */
140→  depthFilterDelta: number;
141→  /** 重み付き平面フィッティングの設定 */
142→  weights: {
143→    /** 再投影誤差の重みパラメータ */
144→    reprojectionSigma: number;
145→    /** 最小重み */
146→    minWeight: number;
147→    /** 追跡安定性の最大フレーム数 */
148→    maxTrackingFrames: number;
149→  };
150→  /** カメラ内部パラメータ */
151→  cameraIntrinsics: CameraIntrinsicsConfig;
