  6→import * as THREE from "three";
  7→
  8→export class ARRenderer {
  9→  private width: number;
 10→  private height: number;
 11→
 12→  private threeCanvas: HTMLCanvasElement;
 13→
 14→  // Three.js関連
 15→  private scene!: THREE.Scene;
 16→  private camera!: THREE.PerspectiveCamera;
 17→  private renderer!: THREE.WebGLRenderer;
 18→
 19→  constructor({ width, height }: { width: number; height: number }) {
 20→    this.width = width;
 21→    this.height = height;
 22→    // this.video = document.getElementById("camera") as HTMLVideoElement;
 23→    // this.canvas = document.getElementById("output") as HTMLCanvasElement;
 24→    // this.ctx = this.canvas.getContext("2d")!;
 25→
 26→    // Three.js用の新しいcanvasを作成
 27→    this.threeCanvas = document.createElement("canvas");
 28→    this.threeCanvas.id = "threeCanvas";
 29→    this.threeCanvas.style.position = "absolute";
 30→    this.threeCanvas.style.top = "0";
 31→    this.threeCanvas.style.left = "0";
 32→    this.threeCanvas.style.width = "100%";
 33→    this.threeCanvas.style.height = "100%";
 34→    this.threeCanvas.style.pointerEvents = "none";
 35→    document.body.appendChild(this.threeCanvas);
 36→
 37→    // Three.jsの初期化
 38→    this.initThreeJS();
 39→  }
 40→
 41→  private initThreeJS(): void {
 42→    this.scene = new THREE.Scene();
 43→    this.camera = new THREE.PerspectiveCamera(
 44→      75,
 45→      this.width / this.height,
 46→      0.1,
 47→      1000
 48→    );
 49→
 50→    // モバイル端末検出
 51→    const isMobile =
 52→      /Android|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
 53→        navigator.userAgent
 54→      );
 55→
 56→    this.renderer = new THREE.WebGLRenderer({
 57→      canvas: this.threeCanvas,
 58→      alpha: true,
 59→      antialias: !isMobile, // モバイルではアンチエイリアスを無効化してパフォーマンス向上
 60→      powerPreference: isMobile ? "low-power" : "high-performance",
 61→      precision: isMobile ? "mediump" : "highp", // モバイルでは精度を下げて安定性向上
 62→    });
 63→
 64→    // デバイスピクセル比の設定（モバイルで重要）
 65→    const pixelRatio = Math.min(window.devicePixelRatio, isMobile ? 2 : 3);
 66→    this.renderer.setPixelRatio(pixelRatio);
 67→
 68→    this.renderer.setSize(this.width, this.height);
 69→    this.renderer.setClearColor(0x000000, 0);
 70→
 71→    console.log(
 72→      `ARRenderer initialized for ${isMobile ? "mobile" : "desktop"} with pixel ratio: ${pixelRatio}`
 73→    );
 74→    // カメラを固定位置に配置
 75→    // TODO: カメラの位置を調整する
 76→    // this.camera.position.x = -0.5;
 77→    this.camera.position.z = 0;
 78→
 79→    // ウィンドウサイズ変更時のイベントリスナー
 80→    window.addEventListener("resize", this.resizeHandler);
 81→  }
 82→
 83→  getScene(): THREE.Scene {
 84→    return this.scene;
 85→  }
 86→
 87→  getCamera(): THREE.PerspectiveCamera {
 88→    return this.camera;
 89→  }
 90→
 91→  setCameraPosition(x: number, y: number, z: number): void {
 92→    this.camera.position.set(x, y, z);
 93→  }
 94→
 95→  render() {
 96→    this.renderer.render(this.scene, this.camera);
 97→  }
 98→
 99→  /**
100→   * リソースを解放
101→   */
102→  dispose(): void {
103→    // シーン内のメッシュやマテリアルを解放
104→    this.scene.traverse((child) => {
105→      if (child instanceof THREE.Mesh) {
106→        child.geometry.dispose();
107→        if (Array.isArray(child.material)) {
108→          child.material.forEach((material) => material.dispose());
109→        } else {
110→          child.material.dispose();
111→        }
112→      }
113→    });
114→
115→    // レンダラーを解放
116→    this.renderer.dispose();
117→
118→    // canvasをDOMから削除
119→    if (this.threeCanvas.parentNode) {
120→      this.threeCanvas.parentNode.removeChild(this.threeCanvas);
121→    }
122→
123→    // イベントリスナーを削除
124→    window.removeEventListener("resize", this.resizeHandler);
125→  }
126→
127→  private resizeHandler = () => {
128→    // 現在のウィンドウサイズを取得
129→    const newWidth = window.innerWidth;
130→    const newHeight = window.innerHeight;
131→
132→    // カメラのアスペクト比を更新
133→    this.camera.aspect = newWidth / newHeight;
134→    this.camera.updateProjectionMatrix();
135→
136→    // レンダラーのサイズを更新
137→    this.renderer.setSize(newWidth, newHeight);
138→
139→    // 内部の幅・高さを更新
140→    this.width = newWidth;
141→    this.height = newHeight;
142→
143→    console.log(`ARRenderer resized to: ${newWidth}x${newHeight}`);
144→  };
145→}
