  6→import { Feature } from "../types/Feature";
  7→import { DeviceMotionTracker } from "./DeviceMotionTracker";
  8→
  9→/**
 10→ * Feature pair for distance tracking
 11→ */
 12→interface FeaturePair {
 13→  id1: string;
 14→  id2: string;
 15→  initialDistance: number;
 16→  currentDistance: number;
 17→  trackedFrames: number;
 18→}
 19→
 20→/**
 21→ * Velocity state for outlier detection
 22→ */
 23→interface FeatureVelocityState {
 24→  lastX: number;
 25→  lastY: number;
 26→  excludedFromScale: boolean;
 27→  stableFrameCount: number;
 28→}
 29→
 30→/**
 31→ * Distance Tracker Options
 32→ */
 33→export interface DistanceTrackerOptions {
 34→  /** Minimum tracked frames for a pair to be considered stable. Default: 10 */
 35→  minTrackedFrames?: number;
 36→  /** Maximum number of feature pairs to track. Default: 20 */
 37→  maxPairs?: number;
 38→  /** Minimum pixel distance for a valid pair. Default: 50 */
 39→  minPairDistance?: number;
 40→  /** DeviceMotionTracker for stationary detection. Optional. */
 41→  deviceMotionTracker?: DeviceMotionTracker;
 42→  /** Linear acceleration threshold for stationary detection (m/s²). Default: 0.3 */
 43→  stationaryAccelerationThreshold?: number;
 44→  /** Angular velocity threshold for stationary detection (deg/s). Default: 5.0 */
 45→  stationaryAngularVelocityThreshold?: number;
 46→  /** Maximum scale change per frame (ratio). Default: 0.2 (20%) */
 47→  maxScaleChangePerFrame?: number;
 48→  /** Outlier threshold in IQR multiples. Default: 1.5 */
 49→  outlierThreshold?: number;
 50→  /** MAD multiplier for velocity outlier detection. Default: 3.0 */
 51→  velocityOutlierMadMultiplier?: number;
 52→  /** Frames required for outlier feature to recover. Default: 5 */
 53→  velocityOutlierRecoveryFrames?: number;
 54→}
 55→
 56→/**
 57→ * Distance Tracker
 58→ *
 59→ * Tracks the distance between feature point pairs to estimate
 60→ * relative camera movement (approaching or receding from the plane).
 61→ *
 62→ * When the camera moves closer:
 63→ * - Feature points appear to spread apart (larger distances)
 64→ * - Scale factor > 1.0
 65→ *
 66→ * When the camera moves farther:
 67→ * - Feature points appear to converge (smaller distances)
 68→ * - Scale factor < 1.0
 69→ */
 70→export class DistanceTracker {
 71→  private featurePairs: Map<string, FeaturePair> = new Map();
 72→  private currentScale: number = 1.0;
 73→  private initialDepth: number = 1.0;
 74→  private currentDepth: number = 1.0;
 75→
 76→  private minTrackedFrames: number;
 77→  private maxPairs: number;
 78→  private minPairDistance: number;
 79→
 80→  private deviceMotionTracker: DeviceMotionTracker | null;
 81→  private stationaryAccelerationThreshold: number;
 82→  private stationaryAngularVelocityThreshold: number;
 83→  private maxScaleChangePerFrame: number;
 84→  private outlierThreshold: number;
 85→
 86→  private velocityOutlierMadMultiplier: number;
 87→  private velocityOutlierRecoveryFrames: number;
 88→  private featureVelocityStates: Map<string, FeatureVelocityState> = new Map();
 89→
 90→  constructor(options?: DistanceTrackerOptions) {
 91→    this.minTrackedFrames = options?.minTrackedFrames ?? 10;
 92→    this.maxPairs = options?.maxPairs ?? 20;
 93→    this.minPairDistance = options?.minPairDistance ?? 50;
 94→    this.deviceMotionTracker = options?.deviceMotionTracker ?? null;
 95→    this.stationaryAccelerationThreshold =
 96→      options?.stationaryAccelerationThreshold ?? 0.3;
 97→    this.stationaryAngularVelocityThreshold =
 98→      options?.stationaryAngularVelocityThreshold ?? 5.0;
 99→    this.maxScaleChangePerFrame = options?.maxScaleChangePerFrame ?? 0.2;
100→    this.outlierThreshold = options?.outlierThreshold ?? 1.5;
101→    this.velocityOutlierMadMultiplier =
102→      options?.velocityOutlierMadMultiplier ?? 3.0;
103→    this.velocityOutlierRecoveryFrames =
104→      options?.velocityOutlierRecoveryFrames ?? 5;
105→  }
106→
107→  /**
108→   * Set the initial depth reference
109→   */
110→  public setInitialDepth(depth: number): void {
111→    this.initialDepth = depth;
112→    this.currentDepth = depth;
113→  }
114→
115→  /**
116→   * Update tracking with current frame features
117→   *
118→   * @param features Current frame features
119→   * @returns Updated scale factor
120→   */
121→  public update(features: Feature[]): number {
122→    if (features.length < 2) {
123→      return this.currentScale;
124→    }
125→
126→    // Build feature map for quick lookup
127→    const featureMap = new Map<string, Feature>();
128→    for (const feature of features) {
129→      featureMap.set(feature.id, feature);
130→    }
131→
132→    // Update velocity states and detect outliers
133→    this.updateVelocityOutliers(features);
134→
135→    // Update existing pairs
136→    const validPairs: FeaturePair[] = [];
137→    for (const [, pair] of this.featurePairs) {
138→      const feature1 = featureMap.get(pair.id1);
139→      const feature2 = featureMap.get(pair.id2);
140→
141→      if (feature1 && feature2) {
142→        // Both features still visible
143→        const currentDistance = this.calculateDistance(feature1, feature2);
144→
145→        if (currentDistance >= this.minPairDistance) {
146→          pair.currentDistance = currentDistance;
147→          pair.trackedFrames++;
148→          validPairs.push(pair);
149→        }
150→      }
151→    }
152→
153→    // Remove invalid pairs
154→    this.featurePairs.clear();
155→    for (const pair of validPairs) {
156→      const pairId = this.createPairId(pair.id1, pair.id2);
157→      this.featurePairs.set(pairId, pair);
158→    }
159→
160→    // Add new pairs if needed
161→    this.addNewPairs(features);
162→
163→    // Calculate scale from stable pairs with outlier rejection
164→    const rawScale = this.calculateScaleWithOutlierRejection();
165→    if (rawScale !== null) {
166→      // Check if scale update should be skipped (stationary or rotating)
167→      if (this.shouldSkipScaleUpdate()) {
168→        // Keep current scale, ignore feature-based changes
169→        return this.currentScale;
170→      }
171→
172→      // Apply rate limiting to prevent sudden jumps
173→      const scaleDiff = rawScale - this.currentScale;
174→      const maxChange = this.currentScale * this.maxScaleChangePerFrame;
175→      const clampedDiff = Math.max(-maxChange, Math.min(maxChange, scaleDiff));
176→      this.currentScale = this.currentScale + clampedDiff;
177→
178→      // Update depth estimate
179→      this.currentDepth = this.initialDepth / this.currentScale;
180→    }
181→
182→    return this.currentScale;
183→  }
184→
185→  /**
186→   * Calculate distance between two features
187→   */
188→  private calculateDistance(feature1: Feature, feature2: Feature): number {
189→    const dx = feature1.x - feature2.x;
190→    const dy = feature1.y - feature2.y;
191→    return Math.sqrt(dx * dx + dy * dy);
192→  }
193→
194→  /**
195→   * Check if scale update should be skipped using IMU data.
196→   *
197→   * Scale updates should be skipped when:
198→   * - Device is stationary (no movement, no rotation) - changes are noise
199→   * - Device is rotating (even without translation) - perspective changes cause false scale detection
200→   *
201→   * Scale updates should only occur when device is translating forward/backward without significant rotation.
202→   */
203→  private shouldSkipScaleUpdate(): boolean {
204→    if (!this.deviceMotionTracker || !this.deviceMotionTracker.isTracking()) {
205→      return false;
206→    }
207→
208→    const linearAcceleration = this.deviceMotionTracker.getLinearAcceleration();
209→    const angularVelocity = this.deviceMotionTracker.getAngularVelocity();
210→
211→    if (!linearAcceleration || !angularVelocity) {
212→      return false;
213→    }
214→
215→    const accelerationMagnitude = linearAcceleration.length();
216→    const angularMagnitude = angularVelocity.length();
217→
218→    // Skip if stationary (both acceleration and rotation are small)
219→    const isStationary =
220→      accelerationMagnitude < this.stationaryAccelerationThreshold &&
221→      angularMagnitude < this.stationaryAngularVelocityThreshold;
222→
223→    // Skip if rotating (rotation causes perspective changes, not real scale changes)
224→    const isRotating =
225→      angularMagnitude >= this.stationaryAngularVelocityThreshold;
226→
227→    return isStationary || isRotating;
228→  }
229→
230→  /**
231→   * Update velocity states and detect outliers based on relative movement
232→   * Uses MAD (Median Absolute Deviation) for robust outlier detection
233→   */
234→  private updateVelocityOutliers(features: Feature[]): void {
235→    // Calculate velocities for features that have previous positions
236→    const velocities: { id: string; velocity: number }[] = [];
237→
238→    for (const feature of features) {
239→      const prevState = this.featureVelocityStates.get(feature.id);
240→      if (prevState) {
241→        const dx = feature.x - prevState.lastX;
242→        const dy = feature.y - prevState.lastY;
243→        const velocity = Math.sqrt(dx * dx + dy * dy);
244→        velocities.push({ id: feature.id, velocity });
245→      }
246→    }
247→
248→    // Need at least 3 features to compute meaningful statistics
249→    if (velocities.length < 3) {
250→      // Just update positions without outlier detection
251→      this.updateFeaturePositions(features);
252→      return;
253→    }
254→
255→    // Calculate median velocity
256→    const sortedVelocities = [...velocities].sort(
257→      (a, b) => a.velocity - b.velocity
258→    );
259→    const medianIndex = Math.floor(sortedVelocities.length / 2);
260→    const medianVelocity =
261→      sortedVelocities.length % 2 === 0
262→        ? (sortedVelocities[medianIndex - 1].velocity +
263→            sortedVelocities[medianIndex].velocity) /
264→          2
265→        : sortedVelocities[medianIndex].velocity;
266→
267→    // Calculate MAD (Median Absolute Deviation)
268→    const absoluteDeviations = velocities.map((v) =>
269→      Math.abs(v.velocity - medianVelocity)
270→    );
271→    absoluteDeviations.sort((a, b) => a - b);
272→    const madIndex = Math.floor(absoluteDeviations.length / 2);
273→    const mad =
274→      absoluteDeviations.length % 2 === 0
275→        ? (absoluteDeviations[madIndex - 1] + absoluteDeviations[madIndex]) / 2
276→        : absoluteDeviations[madIndex];
277→
278→    // Calculate outlier threshold (median + multiplier * MAD)
279→    // Use a minimum MAD to avoid too strict threshold when all features move similarly
280→    const effectiveMad = Math.max(mad, 2.0);
281→    const outlierThreshold =
282→      medianVelocity + this.velocityOutlierMadMultiplier * effectiveMad;
283→
284→    // Update states based on outlier detection
285→    const currentFeatureIds = new Set(features.map((f) => f.id));
286→
287→    for (const { id, velocity } of velocities) {
288→      const state = this.featureVelocityStates.get(id);
289→      if (!state) continue;
290→
291→      const isOutlier = velocity > outlierThreshold;
292→
293→      if (isOutlier) {
294→        // Mark as excluded and reset stable count
295→        state.excludedFromScale = true;
296→        state.stableFrameCount = 0;
297→      } else if (state.excludedFromScale) {
298→        // Feature was excluded but is now stable, increment counter
299→        state.stableFrameCount++;
300→        if (state.stableFrameCount >= this.velocityOutlierRecoveryFrames) {
301→          // Recovered: allow back into scale calculation
302→          state.excludedFromScale = false;
303→        }
304→      }
305→    }
306→
307→    // Update positions for all features
308→    this.updateFeaturePositions(features);
309→
310→    // Remove states for features no longer present
311→    for (const id of this.featureVelocityStates.keys()) {
312→      if (!currentFeatureIds.has(id)) {
313→        this.featureVelocityStates.delete(id);
314→      }
315→    }
316→  }
317→
318→  /**
319→   * Update feature positions in velocity states
320→   */
321→  private updateFeaturePositions(features: Feature[]): void {
322→    for (const feature of features) {
323→      const existing = this.featureVelocityStates.get(feature.id);
324→      if (existing) {
325→        existing.lastX = feature.x;
326→        existing.lastY = feature.y;
327→      } else {
328→        this.featureVelocityStates.set(feature.id, {
329→          lastX: feature.x,
330→          lastY: feature.y,
331→          excludedFromScale: false,
332→          stableFrameCount: 0,
333→        });
334→      }
335→    }
336→  }
337→
338→  /**
339→   * Check if a feature is currently excluded from scale calculation
340→   */
341→  private isFeatureExcludedFromScale(featureId: string): boolean {
342→    const state = this.featureVelocityStates.get(featureId);
343→    return state?.excludedFromScale ?? false;
344→  }
345→
346→  /**
347→   * Create a unique pair ID
348→   */
349→  private createPairId(id1: string, id2: string): string {
350→    return id1 < id2 ? `${id1}:${id2}` : `${id2}:${id1}`;
351→  }
352→
353→  /**
354→   * Add new feature pairs
355→   * Only adds pairs when tracking is stable (enough existing stable pairs)
356→   */
357→  private addNewPairs(features: Feature[]): void {
358→    if (this.featurePairs.size >= this.maxPairs) {
359→      return;
360→    }
361→
362→    // Check if we should add new pairs
363→    // Only add when we have at least some stable pairs or we have none at all
364→    const stablePairCount = this.getStablePairCount();
365→    const hasNoPairs = this.featurePairs.size === 0;
366→    const hasStableTracking = stablePairCount >= 3;
367→
368→    // Don't add new pairs during unstable tracking (except when starting fresh)
369→    if (!hasNoPairs && !hasStableTracking) {
370→      return;
371→    }
372→
373→    // Filter stable features (high tracking count - stricter threshold)
374→    const stableFeatures = features
375→      .filter((f) => f.trackingCount >= 15)
376→      .sort((a, b) => b.trackingCount - a.trackingCount)
377→      .slice(0, 10);
378→
379→    // Create pairs from stable features
380→    for (
381→      let i = 0;
382→      i < stableFeatures.length && this.featurePairs.size < this.maxPairs;
383→      i++
384→    ) {
385→      for (
386→        let j = i + 1;
387→        j < stableFeatures.length && this.featurePairs.size < this.maxPairs;
388→        j++
389→      ) {
390→        const feature1 = stableFeatures[i];
391→        const feature2 = stableFeatures[j];
392→        const pairId = this.createPairId(feature1.id, feature2.id);
393→
394→        if (!this.featurePairs.has(pairId)) {
395→          const distance = this.calculateDistance(feature1, feature2);
396→
397→          if (distance >= this.minPairDistance) {
398→            // Normalize initialDistance by current scale to prevent drift
399→            // This ensures all pairs use scale=1.0 as their reference
400→            const normalizedInitialDistance = distance / this.currentScale;
401→
402→            this.featurePairs.set(pairId, {
403→              id1: feature1.id,
404→              id2: feature2.id,
405→              initialDistance: normalizedInitialDistance,
406→              currentDistance: distance,
407→              trackedFrames: 1,
408→            });
409→          }
410→        }
411→      }
412→    }
413→  }
414→
415→  /**
416→   * Calculate scale factor from tracked pairs with outlier rejection
417→   * Uses IQR-based outlier detection for robustness
418→   */
419→  private calculateScaleWithOutlierRejection(): number | null {
420→    const stablePairs = Array.from(this.featurePairs.values()).filter(
421→      (pair) =>
422→        pair.trackedFrames >= this.minTrackedFrames &&
423→        !this.isFeatureExcludedFromScale(pair.id1) &&
424→        !this.isFeatureExcludedFromScale(pair.id2)
425→    );
426→
427→    if (stablePairs.length === 0) {
428→      return null;
429→    }
430→
431→    // Calculate scale for each pair
432→    const scaleValues = stablePairs.map((pair) => ({
433→      scale: pair.currentDistance / pair.initialDistance,
434→      weight: pair.trackedFrames,
435→    }));
436→
437→    // If only one pair, use it directly
438→    if (scaleValues.length === 1) {
439→      return scaleValues[0].scale;
440→    }
441→
442→    // Sort by scale value for percentile calculation
443→    const sortedScales = [...scaleValues].sort((a, b) => a.scale - b.scale);
444→
445→    // Calculate median
446→    const medianIndex = Math.floor(sortedScales.length / 2);
447→    const median =
448→      sortedScales.length % 2 === 0
449→        ? (sortedScales[medianIndex - 1].scale +
450→            sortedScales[medianIndex].scale) /
451→          2
452→        : sortedScales[medianIndex].scale;
453→
454→    // If few pairs, use median directly without outlier rejection
455→    if (sortedScales.length < 4) {
456→      return median;
457→    }
458→
459→    // Calculate IQR (Interquartile Range)
460→    const q1Index = Math.floor(sortedScales.length * 0.25);
461→    const q3Index = Math.floor(sortedScales.length * 0.75);
462→    const q1 = sortedScales[q1Index].scale;
463→    const q3 = sortedScales[q3Index].scale;
464→    const iqr = q3 - q1;
465→
466→    // Define outlier bounds
467→    const lowerBound = q1 - this.outlierThreshold * iqr;
468→    const upperBound = q3 + this.outlierThreshold * iqr;
469→
470→    // Filter out outliers and calculate weighted average
471→    let totalWeight = 0;
472→    let weightedScaleSum = 0;
473→
474→    for (const item of scaleValues) {
475→      if (item.scale >= lowerBound && item.scale <= upperBound) {
476→        weightedScaleSum += item.scale * item.weight;
477→        totalWeight += item.weight;
478→      }
479→    }
480→
481→    // If all values were filtered out (shouldn't happen), return median
482→    if (totalWeight === 0) {
483→      return median;
484→    }
485→
486→    return weightedScaleSum / totalWeight;
487→  }
488→
489→  /**
490→   * Get the current scale factor
491→   *
492→   * - > 1.0: Camera is closer to the plane
493→   * - < 1.0: Camera is farther from the plane
494→   * - = 1.0: Same distance as initial detection
495→   */
496→  public getScale(): number {
497→    return this.currentScale;
498→  }
499→
500→  /**
501→   * Get the estimated current depth
502→   */
503→  public getDepth(): number {
504→    return this.currentDepth;
505→  }
506→
507→  /**
508→   * Get the depth change ratio (current / initial)
509→   */
510→  public getDepthRatio(): number {
511→    return this.initialDepth > 0 ? this.currentDepth / this.initialDepth : 1.0;
512→  }
513→
514→  /**
515→   * Get the number of tracked pairs
516→   */
517→  public getTrackedPairCount(): number {
518→    return this.featurePairs.size;
519→  }
520→
521→  /**
522→   * Get the number of stable pairs
523→   */
524→  public getStablePairCount(): number {
525→    return Array.from(this.featurePairs.values()).filter(
526→      (pair) => pair.trackedFrames >= this.minTrackedFrames
527→    ).length;
528→  }
529→
530→  /**
531→   * Get the number of features currently excluded from scale calculation
532→   */
533→  public getExcludedFeatureCount(): number {
534→    let count = 0;
535→    for (const state of this.featureVelocityStates.values()) {
536→      if (state.excludedFromScale) {
537→        count++;
538→      }
539→    }
540→    return count;
541→  }
542→
543→  /**
544→   * Get statistics
545→   */
546→  public getStatistics(): {
547→    scale: number;
548→    depth: number;
549→    depthRatio: number;
550→    trackedPairs: number;
551→    stablePairs: number;
552→    excludedFeatures: number;
553→  } {
554→    return {
555→      scale: this.currentScale,
556→      depth: this.currentDepth,
557→      depthRatio: this.getDepthRatio(),
558→      trackedPairs: this.getTrackedPairCount(),
559→      stablePairs: this.getStablePairCount(),
560→      excludedFeatures: this.getExcludedFeatureCount(),
561→    };
562→  }
563→
564→  /**
565→   * Reset the tracker
566→   */
567→  public reset(): void {
568→    this.featurePairs.clear();
569→    this.featureVelocityStates.clear();
570→    this.currentScale = 1.0;
571→    this.currentDepth = this.initialDepth;
572→  }
573→
574→  /**
575→   * Dispose resources
576→   */
577→  public dispose(): void {
578→    this.featurePairs.clear();
579→    this.featureVelocityStates.clear();
580→  }
581→}
