  7→import { Point3D, PlaneModel } from "../types";
  8→
  9→/**
 10→ * @param {Array<Point3D>} points
 11→ *   - 3D 点群
 12→ * @param {number} iterations
 13→ *   - 試行回数（例: 1000）
 14→ * @param {number} threshold
 15→ *   - inlier 判定の距離閾値（同じ単位、例: 0.05 m）
 16→ * @returns {{
 17→ *   plane: { a: number, b: number, c: number, d: number },
 18→ *   inliers: Array<Point3D>
 19→ * }}
 20→ *   - 最良の平面モデルと、その inlier 点群
 21→ */
 22→function fitPlaneRANSAC({
 23→  points,
 24→  iterations = 100,
 25→  threshold = 0.1,
 26→}: {
 27→  points: Point3D[];
 28→  iterations?: number;
 29→  threshold?: number;
 30→}): RANSACResult {
 31→  if (points.length < 3) {
 32→    throw new Error("最低3点が必要です");
 33→  }
 34→  if (iterations <= 0) {
 35→    throw new Error("iterationsは正の値である必要があります");
 36→  }
 37→  if (threshold <= 0) {
 38→    throw new Error("thresholdは正の値である必要があります");
 39→  }
 40→
 41→  let best: { model: PlaneModel | null; inliers: Point3D[] } = {
 42→    model: null,
 43→    inliers: [],
 44→  };
 45→
 46→  for (let i = 0; i < iterations; i++) {
 47→    // 1) ランダムに3点を選んで平面モデルを計算
 48→    const sample = randomSample(points, 3);
 49→    const model = computePlaneFrom3Points(sample[0], sample[1], sample[2]);
 50→    // 2) 全点に対して距離を計算し、閾値以下なら inlier
 51→    const inliers = points.filter(
 52→      (p) => distancePointToPlane(p, model) < threshold
 53→    );
 54→    // 3) inlier が最も多いモデルを保持
 55→    if (inliers.length > best.inliers.length) {
 56→      best = { model, inliers };
 57→    }
 58→  }
 59→
 60→  return best;
 61→}
 62→
 63→/**
 64→ * 点群からランダムに指定数の点を選択
 65→ */
 66→function randomSample(points: Array<Point3D>, n: number): Array<Point3D> {
 67→  const result = [];
 68→  const indices = new Set<number>();
 69→  while (indices.size < n) {
 70→    const idx = Math.floor(Math.random() * points.length);
 71→    if (!indices.has(idx)) {
 72→      indices.add(idx);
 73→      result.push(points[idx]);
 74→    }
 75→  }
 76→
 77→  return result;
 78→}
 79→
 80→/**
 81→ * 3点から平面パラメータ(ax + by + cz + d = 0)を計算
 82→ */
 83→function computePlaneFrom3Points(p1: Point3D, p2: Point3D, p3: Point3D) {
 84→  // 2つのベクトルを計算
 85→  const v1 = {
 86→    x: p2.x - p1.x,
 87→    y: p2.y - p1.y,
 88→    z: p2.z - p1.z,
 89→  };
 90→  const v2 = {
 91→    x: p3.x - p1.x,
 92→    y: p3.y - p1.y,
 93→    z: p3.z - p1.z,
 94→  };
 95→  // 外積で法線ベクトルを計算
 96→  const normal = {
 97→    x: v1.y * v2.z - v1.z * v2.y,
 98→    y: v1.z * v2.x - v1.x * v2.z,
 99→    z: v1.x * v2.y - v1.y * v2.x,
100→  };
101→  // 正規化
102→  const length = Math.sqrt(
103→    normal.x * normal.x + normal.y * normal.y + normal.z * normal.z
104→  );
105→  const a = normal.x / length;
106→  const b = normal.y / length;
107→  const c = normal.z / length;
108→  // d = -(ax + by + cz) を計算
109→  const d = -(a * p1.x + b * p1.y + c * p1.z);
110→
111→  return { a, b, c, d };
112→}
113→
114→/**
115→ * 点と平面の距離を計算
116→ */
117→export function distancePointToPlane(
118→  point: Point3D,
119→  plane: { a: number; b: number; c: number; d: number }
120→): number {
121→  const numerator = Math.abs(
122→    plane.a * point.x + plane.b * point.y + plane.c * point.z + plane.d
123→  );
124→  const denominator = Math.sqrt(
125→    plane.a * plane.a + plane.b * plane.b + plane.c * plane.c
126→  );
127→  return numerator / denominator;
128→}
129→
130→/**
131→ * 深度情報を元に点群をフィルタリング
132→ * 深度の中央値からの偏差が delta 以下の点を残す
133→ */
134→export function filterByDepth(points3D: Point3D[], delta = 0.025) {
135→  const zs = points3D.map((p) => p.z).sort((a, b) => a - b);
136→  const medZ = zs[Math.floor(zs.length / 2)];
137→  return points3D.filter((p) => Math.abs(p.z - medZ) < delta);
138→}
139→
140→interface RANSACResult {
141→  model: PlaneModel | null;
142→  inliers: Point3D[];
143→}
144→
145→export default fitPlaneRANSAC;
