 20→/**
 21→ * 相補フィルタ
 22→ *
 23→ * IMU（高周波・ドリフトあり）と視覚（低周波・安定）を組み合わせて
 24→ * 安定した姿勢推定を実現する
 25→ *
 26→ * 融合式: output = alpha * imu + (1 - alpha) * visual
 27→ * - alpha が高い（0.98）: IMUの高速応答を維持しつつ、視覚でドリフト補正
 28→ * - alpha が低い（0.5）: 視覚をより信頼（ただし遅延が増える）
 29→ */
 30→export class ComplementaryFilter {
 31→  private alpha: number;
 32→  private baseAlpha: number;
 33→  private minVisualConfidence: number;
 34→  private smoothingFactor: number;
 35→
 36→  private previousOutput: THREE.Quaternion | null = null;
 37→  private lastVisualTimestamp: number = 0;
 38→
 39→  // Reusable objects to prevent GC pressure
 40→  private readonly reusableFusedQuaternion: THREE.Quaternion =
 41→    new THREE.Quaternion();
 42→  private readonly reusableSmoothedQuaternion: THREE.Quaternion =
 43→    new THREE.Quaternion();
 44→
 45→  constructor(options?: ComplementaryFilterOptions) {
 46→    this.alpha = options?.alpha ?? 0.98;
 47→    this.baseAlpha = this.alpha;
 48→    this.minVisualConfidence = options?.minVisualConfidence ?? 0.3;
 49→    this.smoothingFactor = options?.smoothingFactor ?? 0.1;
 50→  }
 51→
 52→  /**
 53→   * IMU姿勢と視覚姿勢を融合
 54→   *
 55→   * @param imuOrientation IMUからの姿勢（クォータニオン）
 56→   * @param visualOrientation 視覚からの姿勢（null可）
 57→   * @param visualConfidence 視覚の信頼度（0-1）
 58→   * @returns 融合された姿勢
 59→   * Note: Returns reusable quaternion - caller should copy if needed
 60→   */
 61→  public fuse(
 62→    imuOrientation: THREE.Quaternion,
 63→    visualOrientation: THREE.Quaternion | null,
 64→    visualConfidence: number
 65→  ): THREE.Quaternion {
 66→    // 視覚情報がない、または信頼度が低い場合はIMUのみ使用
 67→    if (!visualOrientation || visualConfidence < this.minVisualConfidence) {
 68→      return this.applySmoothing(imuOrientation);
 69→    }
 70→
 71→    // 視覚情報のタイムスタンプを記録
 72→    this.lastVisualTimestamp = Date.now();
 73→
 74→    // 信頼度に基づいてalphaを動的調整
 75→    this.updateAlpha(visualConfidence);
