 6→import { Point3D } from "../types";
 7→import { CameraIntrinsicsConfig } from "../config/types";
 8→
 9→/**
10→ * カメラ内部パラメータを計算
11→ */
12→export interface CameraIntrinsics {
13→  fx: number;
14→  fy: number;
15→  cx: number;
16→  cy: number;
17→}
18→
19→/**
20→ * FoVと画像サイズから焦点距離を計算
21→ * f = (width / 2) / tan(hfov / 2)
22→ */
23→function calculateFocalLengthFromFov(
24→  horizontalFovDegrees: number,
25→  imageWidth: number
26→): number {
27→  const halfFovRadians = ((horizontalFovDegrees / 2) * Math.PI) / 180;
28→  return imageWidth / 2 / Math.tan(halfFovRadians);
29→}
30→
31→/**
32→ * カメラ内部パラメータを取得
33→ */
34→export function getCameraIntrinsics(
35→  config: CameraIntrinsicsConfig,
36→  imageWidth: number,
37→  imageHeight: number
38→): CameraIntrinsics {
39→  const fx =
40→    config.focalLengthPixels !== null
41→      ? config.focalLengthPixels
42→      : calculateFocalLengthFromFov(config.horizontalFov, imageWidth);
43→
44→  const fy = fx;
45→
46→  const cx = imageWidth / 2 + config.principalPointOffset.x * imageWidth;
47→  const cy = imageHeight / 2 + config.principalPointOffset.y * imageHeight;
48→
49→  return { fx, fy, cx, cy };
50→}
51→
52→export interface BackProjectParams {
53→  points: Point3D[];
54→  intrinsics: CameraIntrinsics;
55→}
56→
57→/**
58→ * 2D特徴点と深度から3Dカメラ座標系に逆投影
59→ *
60→ * @param params.points - { x, y }: 画像上のピクセル座標, z: 深度値
61→ * @param params.intrinsics - カメラ内部パラメータ
62→ * @returns カメラ座標系での3D点群
63→ */
64→function backProjectPoints(params: BackProjectParams): Point3D[] {
65→  const { points, intrinsics } = params;
66→  const { fx, fy, cx, cy } = intrinsics;
67→
68→  const points3D: Point3D[] = [];
69→
70→  for (const point of points) {
71→    const z = point.z;
72→    const x = ((point.x - cx) * z) / fx;
73→    // 画像座標系(Y下向き)からThree.js座標系(Y上向き)への変換
74→    const y = -((point.y - cy) * z) / fy;
75→
76→    points3D.push({ x, y, z, id: point.id });
77→  }
78→
79→  return points3D;
80→}
81→
82→export default backProjectPoints;
