  8→/**
  9→ * 平面フィッティング結果
 10→ */
 11→interface PlaneFitResult {
 12→  a: number;
 13→  b: number;
 14→  c: number;
 15→}
 16→
 17→/**
 18→ * 3x3行列の型
 19→ */
 20→type Matrix3x3 = [[number, number, number], [number, number, number], [number, number, number]];
 21→
 22→/**
 23→ * 3次元ベクトルの型
 24→ */
 25→type Vector3 = [number, number, number];
 26→
 27→/**
 28→ * weightedPlaneFit2D
 29→ *   inliers:          平面とみなした 3D inlier 点群 [{ x, y, z },…]
 30→ *   weights:          点ごとの重み配列 same length as inliers
 31→ * @return { a, b, c }  で z ≈ a*x + b*y + c
 32→ */
 33→export function weightedPlaneFit2D(inliers: Point3D[], weights: number[]): PlaneFitResult {
 34→  let Sxx = 0,
 35→    Syy = 0,
 36→    Sxy = 0;
 37→  let Sxz = 0,
 38→    Syz = 0,
 39→    Sw = 0;
 40→  let Sx = 0,
 41→    Sy = 0,
 42→    Sz = 0;
 43→
 44→  for (let i = 0; i < inliers.length; i++) {
 45→    const { x, y, z } = inliers[i];
 46→    const w = weights[i];
 47→    Sxx += w * x * x;
 48→    Syy += w * y * y;
 49→    Sxy += w * x * y;
 50→    Sxz += w * x * z;
 51→    Syz += w * y * z;
 52→    Sx += w * x;
 53→    Sy += w * y;
 54→    Sz += w * z;
 55→    Sw += w;
 56→  }
 57→
 58→  // 数値の正規化（スケール調整）
 59→  const scale = Math.max(Math.abs(Sxx), Math.abs(Syy), Math.abs(Sw));
 60→  if (scale > 1e-6) {
 61→    Sxx /= scale;
 62→    Syy /= scale;
 63→    Sxy /= scale;
 64→    Sxz /= scale;
 65→    Syz /= scale;
 66→    Sx /= scale;
 67→    Sy /= scale;
 68→    Sz /= scale;
 69→    Sw /= scale;
 70→  }
 71→
 72→  // [[Sxx, Sxy, Sx ],   [ a ]   [ Sxz ]
 73→  //  [Sxy, Syy, Sy ], * [ b ] = [ Syz ]
 74→  //  [ Sx,  Sy, Sw ]]   [ c ]   [ Sz  ]]
 75→  const A: Matrix3x3 = [
 76→    [Sxx, Sxy, Sx],
 77→    [Sxy, Syy, Sy],
 78→    [Sx, Sy, Sw],
 79→  ];
 80→  const B: Vector3 = [Sxz, Syz, Sz];
 81→
 82→  // 3x3 を解く（逆行列 or Cramer's rule）
 83→  const invA = invert3x3(A);
 84→  const [a, b, c] = multiplyMatVec(invA, B);
 85→  return { a, b, c };
 86→}
 87→
 88→// --- ヘルパー行列演算 ---
 89→// 3×3 行列を逆行列にする
 90→function invert3x3(m: Matrix3x3): Matrix3x3 {
 91→  const [[a, b, c], [d, e, f], [g, h, i]] = m;
 92→  const A = e * i - f * h;
 93→  const B = -(d * i - f * g);
 94→  const C = d * h - e * g;
 95→  const D = -(b * i - c * h);
 96→  const E = a * i - c * g;
 97→  const F = -(a * h - b * g);
 98→  const G = b * f - c * e;
 99→  const H = -(a * f - c * d);
100→  const I = a * e - b * d;
101→  const det = a * A + b * B + c * C;
102→  if (Math.abs(det) < 1e-6) throw new Error("平面フィット: 行列が特異");
103→  const invDet = 1 / det;
104→  return [
105→    [A * invDet, D * invDet, G * invDet],
106→    [B * invDet, E * invDet, H * invDet],
107→    [C * invDet, F * invDet, I * invDet],
108→  ];
109→}
110→
111→// 行列×ベクトル
112→function multiplyMatVec(m: Matrix3x3, v: Vector3): Vector3 {
113→  return [
114→    m[0][0] * v[0] + m[0][1] * v[1] + m[0][2] * v[2],
115→    m[1][0] * v[0] + m[1][1] * v[1] + m[1][2] * v[2],
116→    m[2][0] * v[0] + m[2][1] * v[1] + m[2][2] * v[2],
117→  ];
118→}
