 9→/**
10→ * @param {Array<{ u: number, v: number }>} points
11→ *   - 平面上の 2D 座標点群
12→ * @returns {Array<{ u: number, v: number }>}
13→ *   - 凸包を構成する頂点を反時計回り (CCW) または順序付きで返却
14→ */
15→
16→function computeConvexHull2D(points: Point2D[]): Point2D[] {
17→  if (!Array.isArray(points)) {
18→    throw new Error("入力は配列である必要があります");
19→  }
20→  if (points.some((p) => typeof p.u !== "number" || typeof p.v !== "number")) {
21→    throw new Error("すべての点は有効な座標値を持つ必要があります");
22→  }
23→  if (points.length < 3) return points;
24→
25→  // 点をx座標でソート（x座標が同じ場合はy座標で）
26→  const sortedPoints = [...points].sort((a, b) => {
27→    if (a.u !== b.u) return a.u - b.u;
28→    return a.v - b.v;
29→  });
30→
31→  // 下側の凸包を構築
32→  const lowerHull: Point2D[] = [];
33→  for (const point of sortedPoints) {
34→    while (
35→      lowerHull.length >= 2 &&
36→      !isCounterClockwise(
37→        lowerHull[lowerHull.length - 2],
38→        lowerHull[lowerHull.length - 1],
39→        point
40→      )
41→    ) {
42→      lowerHull.pop();
43→    }
44→    lowerHull.push(point);
45→  }
46→
47→  // 上側の凸包を構築
48→  const upperHull: Point2D[] = [];
49→  for (let i = sortedPoints.length - 1; i >= 0; i--) {
50→    const point = sortedPoints[i];
51→    while (
52→      upperHull.length >= 2 &&
53→      !isCounterClockwise(
54→        upperHull[upperHull.length - 2],
55→        upperHull[upperHull.length - 1],
56→        point
57→      )
58→    ) {
59→      upperHull.pop();
60→    }
61→    upperHull.push(point);
62→  }
63→
64→  // 重複を避けるため、最初と最後の点を除いて結合
65→  return [...lowerHull.slice(0, -1), ...upperHull.slice(0, -1)];
66→}
67→
68→/**
69→ * 3点が反時計回り(CCW)かどうかを判定
70→ * 外積の符号で判定（正なら反時計回り）
71→ */
72→function isCounterClockwise(p1: Point2D, p2: Point2D, p3: Point2D): boolean {
73→  return (p2.u - p1.u) * (p3.v - p1.v) - (p2.v - p1.v) * (p3.u - p1.u) > 0;
74→}
75→
76→export default computeConvexHull2D;
