  6→import * as THREE from "three";
  7→import type {
  8→  CameraPose,
  9→  PreintegrationResult,
 10→  ScaleState,
 11→} from "../types/Pose";
 12→
 13→/**
 14→ * Scale Estimator Options
 15→ */
 16→export interface ScaleEstimatorOptions {
 17→  /** Gravity magnitude (m/s²). Default: 9.80665 */
 18→  gravityMagnitude?: number;
 19→  /** Minimum static samples for gravity initialization. Default: 30 */
 20→  minStaticSamples?: number;
 21→  /** Maximum angular velocity to consider static (rad/s). Default: 0.05 */
 22→  staticAngularVelocityThreshold?: number;
 23→  /** Maximum linear acceleration deviation from gravity (m/s²). Default: 0.5 */
 24→  staticAccelerationThreshold?: number;
 25→  /** Scale convergence threshold (relative change). Default: 0.01 */
 26→  convergenceThreshold?: number;
 27→  /** Minimum observations for scale convergence. Default: 10 */
 28→  minConvergenceObservations?: number;
 29→  /** Maximum scale value (sanity check). Default: 100 */
 30→  maxScale?: number;
 31→  /** Minimum scale value (sanity check). Default: 0.0001 */
 32→  minScale?: number;
 33→}
 34→
 35→/**
 36→ * Scale observation for tracking history
 37→ */
 38→interface ScaleObservation {
 39→  scale: number;
 40→  confidence: number;
 41→  timestamp: number;
 42→}
 43→
 44→/**
 45→ * Scale Estimator
 46→ *
 47→ * Estimates the absolute scale factor to convert visual odometry
 48→ * (unit scale) to metric scale using IMU data.
 49→ *
 50→ * Approach:
 51→ * 1. Gravity-based initialization: Use known gravity magnitude (9.8 m/s²)
 52→ *    as reference scale during static initialization
 53→ * 2. Visual-Inertial scale refinement: Compare visual translation with
 54→ *    IMU-integrated displacement to estimate scale
 55→ * 3. Scale monitoring: Track scale stability and detect drift
 56→ */
 57→export class ScaleEstimator {
 58→  private gravityMagnitude: number;
 59→  private minStaticSamples: number;
 60→  private staticAngularVelocityThreshold: number;
 61→  private staticAccelerationThreshold: number;
 62→  private convergenceThreshold: number;
 63→  private minConvergenceObservations: number;
 64→  private maxScale: number;
 65→  private minScale: number;
 66→
 67→  private state: ScaleState = "uninitialized";
 68→  private currentScale: number = 1.0;
 69→  private gravityDirection: THREE.Vector3 = new THREE.Vector3(0, -1, 0);
 70→
 71→  // Initialization samples
 72→  private staticAccelerationSamples: THREE.Vector3[] = [];
 73→  private staticSampleTimestamps: number[] = [];
 74→
 75→  // Scale observations for convergence tracking
 76→  private scaleObservations: ScaleObservation[] = [];
 77→  private readonly maxObservations: number = 50;
 78→
 79→  // Scale statistics
 80→  private scaleVariance: number = 1.0;
 81→  private lastScaleUpdateTime: number = 0;
 82→
 83→  constructor(options?: ScaleEstimatorOptions) {
 84→    this.gravityMagnitude = options?.gravityMagnitude ?? 9.80665;
 85→    this.minStaticSamples = options?.minStaticSamples ?? 30;
 86→    this.staticAngularVelocityThreshold =
 87→      options?.staticAngularVelocityThreshold ?? 0.05;
 88→    this.staticAccelerationThreshold =
 89→      options?.staticAccelerationThreshold ?? 0.5;
 90→    this.convergenceThreshold = options?.convergenceThreshold ?? 0.01;
 91→    this.minConvergenceObservations = options?.minConvergenceObservations ?? 10;
 92→    this.maxScale = options?.maxScale ?? 100;
 93→    this.minScale = options?.minScale ?? 0.0001;
 94→  }
 95→
 96→  /**
 97→   * Get current state
 98→   */
 99→  public getState(): ScaleState {
100→    return this.state;
101→  }
102→
103→  /**
104→   * Get current scale factor
105→   */
106→  public getScale(): number {
107→    return this.currentScale;
108→  }
109→
110→  /**
111→   * Get gravity direction in world frame
112→   */
113→  public getGravityDirection(): THREE.Vector3 {
114→    return this.gravityDirection.clone();
115→  }
116→
117→  /**
118→   * Check if scale is converged
119→   */
120→  public isConverged(): boolean {
121→    return this.state === "converged";
122→  }
123→
124→  /**
125→   * Add static IMU sample for gravity initialization
126→   *
127→   * @param acceleration Acceleration including gravity (m/s²)
128→   * @param angularVelocity Angular velocity (rad/s)
129→   * @param timestamp Sample timestamp (ms)
130→   * @returns Whether initialization is complete
131→   */
132→  public addStaticSample(
133→    acceleration: THREE.Vector3,
134→    angularVelocity: THREE.Vector3,
135→    timestamp: number
136→  ): boolean {
137→    // Check if device is approximately static
138→    const angularVelocityMagnitude = angularVelocity.length();
139→    if (angularVelocityMagnitude > this.staticAngularVelocityThreshold) {
140→      // Device is rotating, reset samples
141→      this.staticAccelerationSamples = [];
142→      this.staticSampleTimestamps = [];
143→      return false;
144→    }
145→
146→    // Check acceleration is close to gravity magnitude
147→    const accelerationMagnitude = acceleration.length();
148→    const deviationFromGravity = Math.abs(
149→      accelerationMagnitude - this.gravityMagnitude
150→    );
151→    if (deviationFromGravity > this.staticAccelerationThreshold) {
152→      // Device is accelerating, reset samples
153→      this.staticAccelerationSamples = [];
154→      this.staticSampleTimestamps = [];
155→      return false;
156→    }
157→
158→    // Add sample
159→    this.staticAccelerationSamples.push(acceleration.clone());
160→    this.staticSampleTimestamps.push(timestamp);
161→
162→    // Keep only recent samples (within 2 seconds)
163→    while (
164→      this.staticSampleTimestamps.length > 0 &&
165→      timestamp - this.staticSampleTimestamps[0] > 2000
166→    ) {
167→      this.staticAccelerationSamples.shift();
168→      this.staticSampleTimestamps.shift();
169→    }
170→
171→    if (this.state === "uninitialized") {
172→      this.state = "initializing";
173→    }
174→
175→    // Check if we have enough samples
176→    if (this.staticAccelerationSamples.length >= this.minStaticSamples) {
177→      return this.initializeFromGravity();
178→    }
179→
180→    return false;
181→  }
182→
183→  /**
184→   * Initialize scale and gravity direction from static samples
185→   */
186→  private initializeFromGravity(): boolean {
187→    if (this.staticAccelerationSamples.length < this.minStaticSamples) {
188→      return false;
189→    }
190→
191→    // Compute average acceleration (should be gravity)
192→    const averageAcceleration = new THREE.Vector3();
193→    for (const sample of this.staticAccelerationSamples) {
194→      averageAcceleration.add(sample);
195→    }
196→    averageAcceleration.divideScalar(this.staticAccelerationSamples.length);
197→
198→    // Gravity direction is opposite to acceleration (gravity pulls down,
199→    // but accelerometer measures reaction force)
200→    this.gravityDirection = averageAcceleration.clone().normalize().negate();
201→
202→    // Initial scale is 1.0 (will be refined by VIO)
203→    this.currentScale = 1.0;
204→
205→    // Compute variance to assess quality
206→    let variance = 0;
207→    for (const sample of this.staticAccelerationSamples) {
208→      const diff = sample.clone().sub(averageAcceleration);
209→      variance += diff.lengthSq();
210→    }
211→    variance /= this.staticAccelerationSamples.length;
212→
213→    // If variance is too high, don't initialize
214→    if (Math.sqrt(variance) > this.staticAccelerationThreshold) {
215→      return false;
216→    }
217→
218→    this.state = "converging";
219→    this.lastScaleUpdateTime = Date.now();
220→
221→    // Clear samples
222→    this.staticAccelerationSamples = [];
223→    this.staticSampleTimestamps = [];
224→
225→    return true;
226→  }
227→
228→  /**
229→   * Update scale from Visual-Inertial comparison
230→   *
231→   * Compares the translation from visual odometry with the displacement
232→   * computed from IMU preintegration to estimate scale.
233→   *
234→   * @param visualTranslation Translation from visual odometry (unit scale)
235→   * @param imuPreintegration IMU preintegration result
236→   * @param initialVelocity Velocity at start of interval
237→   * @param deltaTime Time interval in seconds
238→   * @param confidence Confidence of visual measurement (0-1)
239→   */
240→  public updateScale(
241→    visualTranslation: THREE.Vector3,
242→    imuPreintegration: PreintegrationResult,
243→    initialVelocity: THREE.Vector3,
244→    deltaTime: number,
245→    confidence: number = 1.0
246→  ): void {
247→    if (this.state === "uninitialized" || this.state === "initializing") {
248→      return;
249→    }
250→
251→    // Visual translation magnitude (unit scale)
252→    const visualMagnitude = visualTranslation.length();
253→    if (visualMagnitude < 0.001) {
254→      // Too small to estimate scale
255→      return;
256→    }
257→
258→    // IMU-predicted displacement
259→    // p = p0 + v0 * dt + 0.5 * g * dt² + R * Δp
260→    const gravityContribution = this.gravityDirection
261→      .clone()
262→      .multiplyScalar(0.5 * this.gravityMagnitude * deltaTime * deltaTime);
263→
264→    const velocityContribution = initialVelocity
265→      .clone()
266→      .multiplyScalar(deltaTime);
267→
268→    const imuDisplacement = velocityContribution
269→      .clone()
270→      .add(gravityContribution)
271→      .add(imuPreintegration.deltaPosition);
272→
273→    const imuMagnitude = imuDisplacement.length();
274→    if (imuMagnitude < 0.001) {
275→      // Too small to estimate scale
276→      return;
277→    }
278→
279→    // Scale = IMU magnitude / Visual magnitude
280→    const observedScale = imuMagnitude / visualMagnitude;
281→
282→    // Sanity check
283→    if (observedScale < this.minScale || observedScale > this.maxScale) {
284→      return;
285→    }
286→
287→    // Add observation with confidence weighting
288→    this.addScaleObservation(observedScale, confidence);
289→
290→    // Update current scale (exponential moving average)
291→    const alpha = 0.1 * confidence;
292→    this.currentScale = (1 - alpha) * this.currentScale + alpha * observedScale;
293→
294→    // Clamp scale
295→    this.currentScale = Math.max(
296→      this.minScale,
297→      Math.min(this.maxScale, this.currentScale)
298→    );
299→
300→    this.lastScaleUpdateTime = Date.now();
301→
302→    // Check for convergence
303→    this.checkConvergence();
304→  }
305→
306→  /**
307→   * Add scale observation to history
308→   */
309→  private addScaleObservation(scale: number, confidence: number): void {
310→    this.scaleObservations.push({
311→      scale,
312→      confidence,
313→      timestamp: Date.now(),
314→    });
315→
316→    // Limit history size
317→    while (this.scaleObservations.length > this.maxObservations) {
318→      this.scaleObservations.shift();
319→    }
320→
321→    // Update variance
322→    if (this.scaleObservations.length >= 3) {
323→      const scales = this.scaleObservations.map((o) => o.scale);
324→      const mean = scales.reduce((a, b) => a + b, 0) / scales.length;
325→      this.scaleVariance =
326→        scales.reduce((sum, s) => sum + (s - mean) ** 2, 0) / scales.length;
327→    }
328→  }
329→
330→  /**
331→   * Check if scale has converged
332→   */
333→  private checkConvergence(): void {
334→    if (this.scaleObservations.length < this.minConvergenceObservations) {
335→      return;
336→    }
337→
338→    // Check relative variance
339→    const relativeVariance = Math.sqrt(this.scaleVariance) / this.currentScale;
340→    if (relativeVariance < this.convergenceThreshold) {
341→      this.state = "converged";
342→    }
343→  }
344→
345→  /**
346→   * Refine scale using optimized poses and IMU data
347→   *
348→   * This is called after Visual-Inertial optimization to update
349→   * the scale with the optimized value.
350→   *
351→   * @param optimizedScale Scale from optimization
352→   * @param gravityDirection Refined gravity direction
353→   */
354→  public refineScale(
355→    optimizedScale: number,
356→    gravityDirection: THREE.Vector3
357→  ): void {
358→    if (optimizedScale < this.minScale || optimizedScale > this.maxScale) {
359→      return;
360→    }
361→
362→    // Update with high confidence
363→    this.addScaleObservation(optimizedScale, 1.0);
364→
365→    // Blend with current scale (trust optimization more)
366→    const alpha = 0.5;
367→    this.currentScale =
368→      (1 - alpha) * this.currentScale + alpha * optimizedScale;
369→
370→    // Update gravity direction
371→    this.gravityDirection = gravityDirection.clone().normalize();
372→
373→    this.lastScaleUpdateTime = Date.now();
374→    this.checkConvergence();
375→  }
376→
377→  /**
378→   * Compute scale from two poses and their preintegration
379→   *
380→   * Solves for scale that best aligns visual and inertial displacements.
381→   *
382→   * @param pose1 First camera pose
383→   * @param pose2 Second camera pose
384→   * @param preintegration IMU preintegration between poses
385→   * @param velocity1 Velocity at first pose
386→   * @returns Estimated scale or null if cannot compute
387→   */
388→  public computeScaleFromPoses(
389→    pose1: CameraPose,
390→    pose2: CameraPose,
391→    preintegration: PreintegrationResult,
392→    velocity1: THREE.Vector3
393→  ): number | null {
394→    // Visual displacement
395→    const visualDisplacement = pose2.translation.clone().sub(pose1.translation);
396→    const visualMagnitude = visualDisplacement.length();
397→
398→    if (visualMagnitude < 0.001) {
399→      return null;
400→    }
401→
402→    // Time interval
403→    const deltaTime = preintegration.integrationTime;
404→    if (deltaTime < 0.01) {
405→      return null;
406→    }
407→
408→    // IMU predicted displacement (with current scale)
409→    const gravityContribution = this.gravityDirection
410→      .clone()
411→      .multiplyScalar(0.5 * this.gravityMagnitude * deltaTime * deltaTime);
412→
413→    const velocityContribution = velocity1.clone().multiplyScalar(deltaTime);
414→
415→    // Transform preintegration to world frame
416→    const rotation1 = new THREE.Matrix4().makeRotationFromQuaternion(
417→      pose1.quaternion
418→    );
419→    const rotation3 = new THREE.Matrix3().setFromMatrix4(rotation1);
420→    const deltaPositionWorld = preintegration.deltaPosition
421→      .clone()
422→      .applyMatrix3(rotation3);
423→
424→    const imuDisplacement = velocityContribution
425→      .add(gravityContribution)
426→      .add(deltaPositionWorld);
427→
428→    const imuMagnitude = imuDisplacement.length();
429→
430→    if (imuMagnitude < 0.001) {
431→      return null;
432→    }
433→
434→    // Scale estimate
435→    const scale = imuMagnitude / visualMagnitude;
436→
437→    if (scale < this.minScale || scale > this.maxScale) {
438→      return null;
439→    }
440→
441→    return scale;
442→  }
443→
444→  /**
445→   * Get scale variance (uncertainty)
446→   */
447→  public getScaleVariance(): number {
448→    return this.scaleVariance;
449→  }
450→
451→  /**
452→   * Get scale confidence (inverse of relative variance)
453→   */
454→  public getScaleConfidence(): number {
455→    if (this.currentScale < 1e-6) {
456→      return 0;
457→    }
458→    const relativeStdDev = Math.sqrt(this.scaleVariance) / this.currentScale;
459→    return Math.max(0, 1 - relativeStdDev);
460→  }
461→
462→  /**
463→   * Get number of scale observations
464→   */
465→  public getObservationCount(): number {
466→    return this.scaleObservations.length;
467→  }
468→
469→  /**
470→   * Apply scale to a translation vector
471→   */
472→  public applyScale(translation: THREE.Vector3): THREE.Vector3 {
473→    return translation.clone().multiplyScalar(this.currentScale);
474→  }
475→
476→  /**
477→   * Apply scale to a pose (modifies translation only)
478→   */
479→  public applyScaleToPose(pose: CameraPose): CameraPose {
480→    return {
481→      ...pose,
482→      translation: pose.translation.clone().multiplyScalar(this.currentScale),
483→      quaternion: pose.quaternion.clone(),
484→      rotation: pose.rotation.clone(),
485→    };
486→  }
487→
488→  /**
489→   * Mark scale as lost (needs re-initialization)
490→   */
491→  public markAsLost(): void {
492→    this.state = "lost";
493→  }
494→
495→  /**
496→   * Check if scale needs recalibration
497→   */
498→  public needsRecalibration(): boolean {
499→    // Check if no updates for a long time
500→    const timeSinceUpdate = Date.now() - this.lastScaleUpdateTime;
501→    if (timeSinceUpdate > 5000 && this.state !== "converged") {
502→      return true;
503→    }
504→
505→    // Check if variance is too high
506→    if (this.scaleVariance > this.currentScale * 0.5) {
507→      return true;
508→    }
509→
510→    return false;
511→  }
512→
513→  /**
514→   * Update options
515→   */
516→  public updateOptions(options: Partial<ScaleEstimatorOptions>): void {
517→    if (options.gravityMagnitude !== undefined) {
518→      this.gravityMagnitude = options.gravityMagnitude;
519→    }
520→    if (options.minStaticSamples !== undefined) {
521→      this.minStaticSamples = options.minStaticSamples;
522→    }
523→    if (options.staticAngularVelocityThreshold !== undefined) {
524→      this.staticAngularVelocityThreshold =
525→        options.staticAngularVelocityThreshold;
526→    }
527→    if (options.staticAccelerationThreshold !== undefined) {
528→      this.staticAccelerationThreshold = options.staticAccelerationThreshold;
529→    }
530→    if (options.convergenceThreshold !== undefined) {
531→      this.convergenceThreshold = options.convergenceThreshold;
532→    }
533→    if (options.minConvergenceObservations !== undefined) {
534→      this.minConvergenceObservations = options.minConvergenceObservations;
535→    }
536→    if (options.maxScale !== undefined) {
537→      this.maxScale = options.maxScale;
538→    }
539→    if (options.minScale !== undefined) {
540→      this.minScale = options.minScale;
541→    }
542→  }
543→
544→  /**
545→   * Reset to uninitialized state
546→   */
547→  public reset(): void {
548→    this.state = "uninitialized";
549→    this.currentScale = 1.0;
550→    this.gravityDirection.set(0, -1, 0);
551→    this.staticAccelerationSamples = [];
552→    this.staticSampleTimestamps = [];
553→    this.scaleObservations = [];
554→    this.scaleVariance = 1.0;
555→    this.lastScaleUpdateTime = 0;
556→  }
557→
558→  /**
559→   * Dispose resources
560→   */
561→  public dispose(): void {
562→    this.reset();
563→  }
564→}
