  6→import * as THREE from "three";
  7→import { Feature } from "../types/Feature";
  8→
  9→/**
 10→ * Anchor feature with locked 3D position
 11→ */
 12→export interface AnchorFeature {
 13→  /** Feature ID */
 14→  id: string;
 15→  /** Initial 2D position (image coordinates) */
 16→  initial2D: { x: number; y: number };
 17→  /** Current 2D position (tracked by optical flow) */
 18→  current2D: { x: number; y: number };
 19→  /** Locked 3D position (world coordinates) */
 20→  position3D: THREE.Vector3;
 21→  /** Tracking count at anchor creation */
 22→  anchorTrackingCount: number;
 23→  /** Current tracking count */
 24→  currentTrackingCount: number;
 25→  /** Stability score (0-1) */
 26→  stability: number;
 27→  /** Reprojection error (pixels) */
 28→  reprojectionError: number;
 29→  /** Is this anchor valid */
 30→  isValid: boolean;
 31→  /** Last update timestamp */
 32→  lastUpdated: number;
 33→  /** Frames since last descriptor match */
 34→  framesSinceMatch: number;
 35→}
 36→
 37→/**
 38→ * Feature Anchor Options
 39→ */
 40→export interface FeatureAnchorOptions {
 41→  /** Maximum reprojection error threshold (pixels). Default: 10 */
 42→  maxReprojectionError?: number;
 43→  /** Moderate reprojection error threshold (pixels). Default: 5 */
 44→  moderateReprojectionError?: number;
 45→  /** Minimum tracking count to create anchor. Default: 10 */
 46→  minTrackingCountForAnchor?: number;
 47→  /** Maximum number of anchors. Default: 50 */
 48→  maxAnchors?: number;
 49→  /** Frames between descriptor re-matching. Default: 30 */
 50→  descriptorMatchInterval?: number;
 51→  /** Anchor expiry time (ms). Default: 10000 */
 52→  anchorExpiryMs?: number;
 53→}
 54→
 55→/**
 56→ * Reprojection result
 57→ */
 58→export interface ReprojectionResult {
 59→  /** Anchor ID */
 60→  id: string;
 61→  /** Projected 2D position */
 62→  projected2D: { x: number; y: number };
 63→  /** Observed 2D position */
 64→  observed2D: { x: number; y: number };
 65→  /** Reprojection error (pixels) */
 66→  error: number;
 67→  /** Weight based on error (0-1) */
 68→  weight: number;
 69→  /** Is valid (error below threshold) */
 70→  isValid: boolean;
 71→}
 72→
 73→/**
 74→ * Feature Anchor Manager
 75→ *
 76→ * Manages anchor features with locked 3D positions.
 77→ * Implements reprojection error filtering and descriptor re-matching.
 78→ */
 79→export class FeatureAnchor {
 80→  private anchors: Map<string, AnchorFeature> = new Map();
 81→  private maxReprojectionError: number;
 82→  private moderateReprojectionError: number;
 83→  private minTrackingCountForAnchor: number;
 84→  private maxAnchors: number;
 85→  private descriptorMatchInterval: number;
 86→  private anchorExpiryMs: number;
 87→  private frameCount: number = 0;
 88→
 89→  constructor(options?: FeatureAnchorOptions) {
 90→    this.maxReprojectionError = options?.maxReprojectionError ?? 10;
 91→    this.moderateReprojectionError = options?.moderateReprojectionError ?? 5;
 92→    this.minTrackingCountForAnchor = options?.minTrackingCountForAnchor ?? 10;
 93→    this.maxAnchors = options?.maxAnchors ?? 50;
 94→    this.descriptorMatchInterval = options?.descriptorMatchInterval ?? 30;
 95→    this.anchorExpiryMs = options?.anchorExpiryMs ?? 10000;
 96→  }
 97→
 98→  /**
 99→   * Update anchors with current frame features
100→   *
101→   * @param features Current frame features
102→   * @param get3DPosition Function to get 3D position for a feature
103→   */
104→  public updateAnchors(
105→    features: Feature[],
106→    get3DPosition?: (feature: Feature) => THREE.Vector3 | null
107→  ): void {
108→    const now = Date.now();
109→    this.frameCount++;
110→
111→    const currentIds = new Set<string>();
112→
113→    for (const feature of features) {
114→      currentIds.add(feature.id);
115→
116→      const existing = this.anchors.get(feature.id);
117→
118→      if (existing) {
119→        // Update existing anchor
120→        existing.current2D = { x: feature.x, y: feature.y };
121→        existing.currentTrackingCount = feature.trackingCount;
122→        existing.lastUpdated = now;
123→        existing.framesSinceMatch++;
124→
125→        // Update stability based on tracking consistency
126→        const trackingRatio =
127→          feature.trackingCount / existing.anchorTrackingCount;
128→        existing.stability = Math.min(1.0, trackingRatio * 0.5 + 0.5);
129→      } else if (feature.trackingCount >= this.minTrackingCountForAnchor) {
130→        // Create new anchor for stable features
131→        const position3D = get3DPosition?.(feature) ?? new THREE.Vector3();
132→
133→        if (this.anchors.size < this.maxAnchors) {
134→          this.anchors.set(feature.id, {
135→            id: feature.id,
136→            initial2D: { x: feature.x, y: feature.y },
137→            current2D: { x: feature.x, y: feature.y },
138→            position3D: position3D.clone(),
139→            anchorTrackingCount: feature.trackingCount,
140→            currentTrackingCount: feature.trackingCount,
141→            stability: 1.0,
142→            reprojectionError: 0,
143→            isValid: true,
144→            lastUpdated: now,
145→            framesSinceMatch: 0,
146→          });
147→        }
148→      }
149→    }
150→
151→    // Remove anchors that are no longer visible or expired
152→    for (const [id, anchor] of this.anchors) {
153→      if (
154→        !currentIds.has(id) ||
155→        now - anchor.lastUpdated > this.anchorExpiryMs
156→      ) {
157→        this.anchors.delete(id);
158→      }
159→    }
160→
161→    // Limit anchor count by removing lowest stability anchors
162→    if (this.anchors.size > this.maxAnchors) {
163→      const sorted = Array.from(this.anchors.values()).sort(
164→        (a, b) => b.stability - a.stability
165→      );
166→      const toKeep = new Set(sorted.slice(0, this.maxAnchors).map((a) => a.id));
167→      for (const id of this.anchors.keys()) {
168→        if (!toKeep.has(id)) {
169→          this.anchors.delete(id);
170→        }
171→      }
172→    }
173→  }
174→
175→  /**
176→   * Calculate reprojection errors for all anchors
177→   *
178→   * @param cameraMatrix Camera intrinsic matrix (3x3)
179→   * @param rotationMatrix Camera rotation matrix (3x3)
180→   * @param translation Camera translation vector
181→   * @returns Reprojection results for all anchors
182→   */
183→  public calculateReprojectionErrors(
184→    cameraMatrix: THREE.Matrix3,
185→    rotationMatrix: THREE.Matrix3,
186→    translation: THREE.Vector3
187→  ): ReprojectionResult[] {
188→    const results: ReprojectionResult[] = [];
189→
190→    for (const anchor of this.anchors.values()) {
191→      // Project 3D point to 2D
192→      const projected = this.projectPoint(
193→        anchor.position3D,
194→        cameraMatrix,
195→        rotationMatrix,
196→        translation
197→      );
198→
199→      // Calculate error
200→      const dx = projected.x - anchor.current2D.x;
201→      const dy = projected.y - anchor.current2D.y;
202→      const error = Math.sqrt(dx * dx + dy * dy);
203→
204→      // Update anchor reprojection error
205→      anchor.reprojectionError = error;
206→
207→      // Calculate weight based on error
208→      let weight: number;
209→      let isValid: boolean;
210→
211→      if (error < this.moderateReprojectionError) {
212→        weight = 1.0;
213→        isValid = true;
214→      } else if (error < this.maxReprojectionError) {
215→        weight = 0.5;
216→        isValid = true;
217→      } else {
218→        weight = 0;
219→        isValid = false;
220→      }
221→
222→      anchor.isValid = isValid;
223→
224→      results.push({
225→        id: anchor.id,
226→        projected2D: projected,
227→        observed2D: anchor.current2D,
228→        error,
229→        weight,
230→        isValid,
231→      });
232→    }
233→
234→    return results;
235→  }
236→
237→  /**
238→   * Project a 3D point to 2D image coordinates
239→   */
240→  private projectPoint(
241→    point3D: THREE.Vector3,
242→    cameraMatrix: THREE.Matrix3,
243→    rotationMatrix: THREE.Matrix3,
244→    translation: THREE.Vector3
245→  ): { x: number; y: number } {
246→    // Transform point to camera coordinates: P_cam = R * P_world + t
247→    const camPoint = point3D.clone();
248→    camPoint.applyMatrix3(rotationMatrix);
249→    camPoint.add(translation);
250→
251→    // Avoid division by zero
252→    if (Math.abs(camPoint.z) < 0.001) {
253→      return { x: 0, y: 0 };
254→    }
255→
256→    // Project to normalized image coordinates
257→    const normalizedX = camPoint.x / camPoint.z;
258→    const normalizedY = camPoint.y / camPoint.z;
259→
260→    // Apply camera matrix
261→    const fx = cameraMatrix.elements[0];
262→    const fy = cameraMatrix.elements[4];
263→    const cx = cameraMatrix.elements[6];
264→    const cy = cameraMatrix.elements[7];
265→
266→    return {
267→      x: fx * normalizedX + cx,
268→      y: fy * normalizedY + cy,
269→    };
270→  }
271→
272→  /**
273→   * Get valid anchors (with low reprojection error)
274→   */
275→  public getValidAnchors(): AnchorFeature[] {
276→    return Array.from(this.anchors.values()).filter((a) => a.isValid);
277→  }
278→
279→  /**
280→   * Get all anchors
281→   */
282→  public getAllAnchors(): AnchorFeature[] {
283→    return Array.from(this.anchors.values());
284→  }
285→
286→  /**
287→   * Get anchor by ID
288→   */
289→  public getAnchor(id: string): AnchorFeature | undefined {
290→    return this.anchors.get(id);
291→  }
292→
293→  /**
294→   * Check if descriptor re-matching should be performed
295→   */
296→  public shouldPerformDescriptorMatch(): boolean {
297→    return this.frameCount % this.descriptorMatchInterval === 0;
298→  }
299→
300→  /**
301→   * Update anchor position after descriptor re-matching
302→   *
303→   * @param id Anchor ID
304→   * @param correctedPosition Corrected 2D position from descriptor matching
305→   */
306→  public correctAnchorPosition(
307→    id: string,
308→    correctedPosition: { x: number; y: number }
309→  ): void {
310→    const anchor = this.anchors.get(id);
311→    if (anchor) {
312→      anchor.current2D = correctedPosition;
313→      anchor.framesSinceMatch = 0;
314→    }
315→  }
316→
317→  /**
318→   * Get anchors that need descriptor re-matching
319→   */
320→  public getAnchorsNeedingMatch(): AnchorFeature[] {
321→    return Array.from(this.anchors.values()).filter(
322→      (a) => a.framesSinceMatch >= this.descriptorMatchInterval
323→    );
324→  }
325→
326→  /**
327→   * Get weighted average position from valid anchors
328→   */
329→  public getWeightedCentroid(): THREE.Vector3 | null {
330→    const validAnchors = this.getValidAnchors();
331→    if (validAnchors.length === 0) {
332→      return null;
333→    }
334→
335→    const centroid = new THREE.Vector3();
336→    let totalWeight = 0;
337→
338→    for (const anchor of validAnchors) {
339→      const weight = anchor.stability * (anchor.isValid ? 1 : 0.5);
340→      centroid.add(anchor.position3D.clone().multiplyScalar(weight));
341→      totalWeight += weight;
342→    }
343→
344→    if (totalWeight > 0) {
345→      centroid.divideScalar(totalWeight);
346→    }
347→
348→    return centroid;
349→  }
350→
351→  /**
352→   * Get statistics
353→   */
354→  public getStatistics(): {
355→    totalAnchors: number;
356→    validAnchors: number;
357→    averageError: number;
358→    averageStability: number;
359→  } {
360→    const anchors = Array.from(this.anchors.values());
361→    const validAnchors = anchors.filter((a) => a.isValid);
362→
363→    let totalError = 0;
364→    let totalStability = 0;
365→
366→    for (const anchor of anchors) {
367→      totalError += anchor.reprojectionError;
368→      totalStability += anchor.stability;
369→    }
370→
371→    return {
372→      totalAnchors: anchors.length,
373→      validAnchors: validAnchors.length,
374→      averageError: anchors.length > 0 ? totalError / anchors.length : 0,
375→      averageStability:
376→        anchors.length > 0 ? totalStability / anchors.length : 0,
377→    };
378→  }
379→
380→  /**
381→   * Clear invalid anchors (high error or low stability)
382→   * Used for periodic memory cleanup
383→   */
384→  public clearInvalidAnchors(): void {
385→    const now = Date.now();
386→    for (const [id, anchor] of this.anchors) {
387→      // Remove if invalid, low stability, or expired
388→      if (
389→        !anchor.isValid ||
390→        anchor.stability < 0.3 ||
391→        now - anchor.lastUpdated > this.anchorExpiryMs * 0.5
392→      ) {
393→        this.anchors.delete(id);
394→      }
395→    }
396→  }
397→
398→  /**
399→   * Reset all anchors
400→   */
401→  public reset(): void {
402→    this.anchors.clear();
403→    this.frameCount = 0;
404→  }
405→
406→  /**
407→   * Dispose resources
408→   */
409→  public dispose(): void {
410→    this.anchors.clear();
411→  }
412→}
