  6→import { FeatureDetector } from "../FeatureDetector";
  7→import { DepthEstimation } from "../DepthEstimation";
  8→import { Feature } from "../types";
  9→
 10→/**
 11→ * フレーム処理結果
 12→ */
 13→export interface FrameProcessingResult {
 14→  features: Feature[];
 15→  centerFeature: Feature | null;
 16→  depthMap: Float32Array | null;
 17→  timestamp: number;
 18→}
 19→
 20→/**
 21→ * フレームプロセッサー
 22→ * ビデオフレームから特徴点検出と深度推定を実行
 23→ */
 24→export class FrameProcessor {
 25→  private featureDetector: FeatureDetector | null = null;
 26→  private depthEstimation: DepthEstimation | null = null;
 27→  private isInitialized: boolean = false;
 28→  private depthEstimationEnabled: boolean = true;
 29→
 30→  constructor() {}
 31→
 32→  /**
 33→   * 初期化
 34→   */
 35→  public async initialize(
 36→    cvInstance: typeof cv,
 37→    video: HTMLVideoElement,
 38→    showFeatures: boolean = true,
 39→    showDepth: boolean = true
 40→  ): Promise<void> {
 41→    // 特徴点検出器の初期化
 42→    this.featureDetector = new FeatureDetector({
 43→      cv: cvInstance,
 44→      video,
 45→      showFeatures,
 46→    });
 47→
 48→    // 深度推定の初期化
 49→    try {
 50→      this.depthEstimation = new DepthEstimation({
 51→        canvas: this.featureDetector.canvas,
 52→        context: this.featureDetector.ctx,
 53→        showDepth,
 54→      });
 55→
 56→      console.log("Loading depth estimation model...");
 57→      await this.depthEstimation.loadModel();
 58→      console.log("Depth estimation model loaded successfully");
 59→    } catch (error) {
 60→      // 深度推定が失敗してもSPALAMは継続（特徴点検出は利用可能）
 61→      this.depthEstimation = null;
 62→
 63→      // エラータイプ別の処理
 64→      const errorMessage =
 65→        error instanceof Error ? error.message : String(error);
 66→      if (
 67→        errorMessage.includes("not supported on mobile devices") ||
 68→        errorMessage.includes("WASM depth estimation failed") ||
 69→        errorMessage.includes("Model download failed") ||
 70→        errorMessage.includes("CDN returned HTML")
 71→      ) {
 72→        // モバイルやネットワーク問題の場合は警告レベルで出力
 73→        console.warn(
 74→          "Depth estimation disabled, using fallback depth calculation:",
 75→          errorMessage
 76→        );
 77→        // エラーを再スローしない
 78→      } else if (errorMessage.includes("timeout")) {
 79→        console.warn(
 80→          "Model loading timeout - using fallback depth calculation:",
 81→          errorMessage
 82→        );
 83→        // タイムアウトの場合も継続
 84→      } else {
 85→        // その他の予期しないエラーの場合のみエラーレベルで出力
 86→        console.error("Depth estimation failed to initialize:", error);
 87→        console.warn(
 88→          "SPALAM will continue without AI depth estimation, using fallback depth calculation"
 89→        );
 90→        // その他の予期しないエラーの場合は再スロー
 91→        throw new Error(`Depth estimation unavailable: ${errorMessage}`);
 92→      }
 93→    }
 94→
 95→    this.isInitialized = true;
 96→  }
 97→
 98→  /**
 99→   * 初期化済みかチェック
100→   */
101→  public isReady(): boolean {
102→    return this.isInitialized;
103→  }
104→
105→  /**
106→   * フレームを処理
107→   */
108→  public async processFrame(): Promise<FrameProcessingResult | null> {
109→    if (!this.isInitialized || !this.featureDetector) {
110→      console.error("FrameProcessor is not initialized");
111→      return null;
112→    }
113→
114→    // 特徴点検出を実行
115→    this.featureDetector.render();
116→
117→    // 追跡された特徴点を取得
118→    const features = this.featureDetector.getTrackedFeaturePoints();
119→    const centerFeature = this.featureDetector.centerFeature;
120→
121→    // 深度マップを取得（深度推定が有効かつ利用可能な場合のみ）
122→    let depthMap = null;
123→    if (this.depthEstimation && this.depthEstimationEnabled) {
124→      try {
125→        depthMap = await this.depthEstimation.getDepthMap();
126→      } catch (error) {
127→        console.warn("Depth map generation failed:", error);
128→        // 深度推定エラーでもフレーム処理は継続
129→      }
130→    }
131→
132→    return {
133→      features,
134→      centerFeature,
135→      depthMap: depthMap || null,
136→      timestamp: Date.now(),
137→    };
138→  }
139→
140→  /**
141→   * 特徴点検出のみを実行（深度推定なし）
142→   */
143→  public renderFeatures(): void {
144→    if (this.featureDetector) {
145→      this.featureDetector.render();
146→    }
147→  }
148→
149→  /**
150→   * キャンバスの幅を取得（スケール後）
151→   */
152→  public getCanvasWidth(): number {
153→    return this.featureDetector?.canvas.width || 0;
154→  }
155→
156→  /**
157→   * キャンバスの高さを取得（スケール後）
158→   */
159→  public getCanvasHeight(): number {
160→    return this.featureDetector?.canvas.height || 0;
161→  }
162→
163→  /**
164→   * オリジナルビデオの幅を取得（スケール前）
165→   */
166→  public getOriginalWidth(): number {
167→    return this.featureDetector?.getOriginalWidth() || 0;
168→  }
169→
170→  /**
171→   * オリジナルビデオの高さを取得（スケール前）
172→   */
173→  public getOriginalHeight(): number {
174→    return this.featureDetector?.getOriginalHeight() || 0;
175→  }
176→
177→  /**
178→   * 追跡中の特徴点を取得（座標はオリジナルビデオサイズにスケール済み）
179→   */
180→  public getTrackedFeatures(): Feature[] {
181→    return this.featureDetector?.getTrackedFeaturePoints() || [];
182→  }
183→
184→  /**
185→   * 特徴点を取得（getTrackedFeaturesのエイリアス）
186→   */
187→  public getFeatures(): Feature[] {
188→    return this.getTrackedFeatures();
189→  }
190→
191→  /**
192→   * 中心特徴点を取得（座標はオリジナルビデオサイズにスケール済み）
193→   */
194→  public getCenterFeature(): Feature | null {
195→    return this.featureDetector?.getCenterFeatureScaled() || null;
196→  }
197→
198→  /**
199→   * 現在の深度マップを取得
200→   */
201→  public async getDepthMap(): Promise<Float32Array | null> {
202→    if (!this.depthEstimation) {
203→      return null;
204→    }
205→    const depthMap = await this.depthEstimation.getDepthMap();
206→    return depthMap || null;
207→  }
208→
209→  /**
210→   * 特徴点が失われているかどうかを返す
211→   */
212→  public hasLostFeatures(): boolean {
213→    return this.featureDetector?.hasLostFeatures() ?? false;
214→  }
215→
216→  /**
217→   * 再検出を許可する（外部から呼び出し）
218→   */
219→  public allowRedetection(): void {
220→    this.featureDetector?.allowRedetection();
221→  }
222→
223→  /**
224→   * 再配置時のターゲット座標を設定
225→   * 設定された座標に最も近い特徴点がcenterFeatureとして選択される
226→   * @param x スクリーンX座標（ピクセル）
227→   * @param y スクリーンY座標（ピクセル）
228→   */
229→  public setTargetPosition(x: number, y: number): void {
230→    this.featureDetector?.setTargetPosition(x, y);
231→  }
232→
233→  /**
234→   * 特徴点描画の有効/無効を設定
235→   */
236→  public setDrawFeaturesEnabled(enabled: boolean): void {
237→    this.featureDetector?.setDrawFeaturesEnabled(enabled);
238→  }
239→
240→  /**
241→   * 特徴点描画が有効かどうかを取得
242→   */
243→  public isDrawFeaturesEnabled(): boolean {
244→    return this.featureDetector?.isDrawFeaturesEnabled() ?? false;
245→  }
246→
247→  /**
248→   * 特徴点描画のスケールを設定
249→   */
250→  public setFeatureScale(scale: number): void {
251→    this.featureDetector?.setScale(scale);
252→  }
253→
254→  /**
255→   * 深度推定の有効/無効を設定
256→   * 平面検出完了後は無効にすることでCPU/メモリ使用量を削減できる
257→   */
258→  public setDepthEstimationEnabled(enabled: boolean): void {
259→    this.depthEstimationEnabled = enabled;
260→    if (!enabled) {
261→      console.log("Depth estimation disabled to save resources");
262→    }
263→  }
264→
265→  /**
266→   * 深度推定が有効かどうかを取得
267→   */
268→  public isDepthEstimationEnabled(): boolean {
269→    return this.depthEstimationEnabled;
270→  }
271→
272→  /**
273→   * リセット
274→   */
275→  public reset(): void {
276→    this.featureDetector?.reset();
277→  }
278→
279→  /**
280→   * 処理を停止
281→   */
282→  public stop(): void {
283→    this.reset();
284→  }
285→
286→  /**
287→   * クリーンアップ
288→   */
289→  public dispose(): void {
290→    this.reset();
291→    this.isInitialized = false;
292→    this.featureDetector = null;
293→    this.depthEstimation = null;
294→  }
295→}
