  6→import * as THREE from "three";
  7→import { Feature } from "../types/Feature";
  8→
  9→/**
 10→ * 安定特徴点の情報
 11→ */
 12→export interface StableFeature {
 13→  /** 特徴点ID */
 14→  id: string;
 15→  /** 2D位置（画像座標） */
 16→  position2D: { x: number; y: number };
 17→  /** 3D位置（ワールド座標） */
 18→  position3D: THREE.Vector3;
 19→  /** 連続追跡フレーム数 */
 20→  trackedFrames: number;
 21→  /** 信頼度（0-1） */
 22→  confidence: number;
 23→  /** 最終更新タイムスタンプ */
 24→  lastUpdated: number;
 25→}
 26→
 27→/**
 28→ * ドリフト補正の設定オプション
 29→ */
 30→export interface DriftCorrectorOptions {
 31→  /** リセット間隔（ミリ秒）デフォルト: 1000 */
 32→  resetIntervalMs?: number;
 33→  /** 安定とみなす最小追跡フレーム数 デフォルト: 10 */
 34→  minTrackedFrames?: number;
 35→  /** 安定特徴点の最大保持数 デフォルト: 50 */
 36→  maxStableFeatures?: number;
 37→  /** 特徴点の有効期限（ミリ秒）デフォルト: 5000 */
 38→  featureExpiryMs?: number;
 39→}
 40→
 41→/**
 42→ * ドリフト補正器
 43→ *
 44→ * 安定した特徴点を追跡し、それを基準にIMUのドリフトを補正する
 45→ */
 46→export class DriftCorrector {
 47→  private stableFeatures: Map<string, StableFeature> = new Map();
 48→  private lastResetTimestamp: number = 0;
 49→  private resetIntervalMs: number;
 50→  private minTrackedFrames: number;
 51→  private maxStableFeatures: number;
 52→  private featureExpiryMs: number;
 53→
 54→  private referencePosition: THREE.Vector3 | null = null;
 55→
 56→  // Reusable objects to prevent GC pressure
 57→  private readonly reusableCentroid: THREE.Vector3 = new THREE.Vector3();
 58→  private readonly reusableTempVector: THREE.Vector3 = new THREE.Vector3();
 59→  private readonly reusablePositionDrift: THREE.Vector3 = new THREE.Vector3();
 60→
 61→  constructor(options?: DriftCorrectorOptions) {
 62→    this.resetIntervalMs = options?.resetIntervalMs ?? 1000;
 63→    this.minTrackedFrames = options?.minTrackedFrames ?? 10;
 64→    this.maxStableFeatures = options?.maxStableFeatures ?? 50;
 65→    this.featureExpiryMs = options?.featureExpiryMs ?? 5000;
 66→  }
 67→
 68→  /**
 69→   * 特徴点情報を更新
 70→   *
 71→   * @param features 現在フレームの特徴点リスト
 72→   * @param depth3DPoints 3D位置情報（オプション）
 73→   */
 74→  public updateFeatures(
 75→    features: Feature[],
 76→    depth3DPoints?: Map<string, THREE.Vector3>
 77→  ): void {
 78→    const now = Date.now();
 79→    const currentIds = new Set<string>();
 80→
 81→    for (const feature of features) {
 82→      currentIds.add(feature.id);
 83→
 84→      const existing = this.stableFeatures.get(feature.id);
 85→
 86→      if (existing) {
 87→        // 既存の特徴点を更新 - avoid creating new objects
 88→        existing.position2D.x = feature.x;
 89→        existing.position2D.y = feature.y;
 90→        existing.trackedFrames++;
 91→        existing.lastUpdated = now;
 92→
 93→        // 3D位置があれば更新 - use copy() instead of clone()
 94→        if (depth3DPoints?.has(feature.id)) {
 95→          existing.position3D.copy(depth3DPoints.get(feature.id)!);
 96→        }
 97→
 98→        // 信頼度を計算（追跡フレーム数に基づく）
 99→        existing.confidence = Math.min(
100→          1.0,
101→          existing.trackedFrames / (this.minTrackedFrames * 2)
102→        );
103→      } else {
104→        // 新しい特徴点を追加
105→        const position3D =
106→          depth3DPoints?.get(feature.id) ?? new THREE.Vector3();
107→
108→        this.stableFeatures.set(feature.id, {
109→          id: feature.id,
110→          position2D: { x: feature.x, y: feature.y },
111→          position3D: position3D.clone(),
112→          trackedFrames: 1,
113→          confidence: 0,
114→          lastUpdated: now,
115→        });
116→      }
117→    }
118→
119→    // 見えなくなった特徴点と古い特徴点を削除
120→    for (const [id, feature] of this.stableFeatures) {
121→      if (
122→        !currentIds.has(id) ||
123→        now - feature.lastUpdated > this.featureExpiryMs
124→      ) {
125→        this.stableFeatures.delete(id);
126→      }
127→    }
128→
129→    // 最大数を超えたら、信頼度の低いものから削除
130→    if (this.stableFeatures.size > this.maxStableFeatures) {
131→      const sorted = Array.from(this.stableFeatures.values()).sort(
132→        (a, b) => b.confidence - a.confidence
133→      );
134→      const toKeep = new Set(
135→        sorted.slice(0, this.maxStableFeatures).map((f) => f.id)
136→      );
137→      for (const id of this.stableFeatures.keys()) {
138→        if (!toKeep.has(id)) {
139→          this.stableFeatures.delete(id);
140→        }
141→      }
142→    }
143→  }
144→
145→  /**
146→   * ドリフト補正が必要か判定
147→   */
148→  public shouldCorrect(): boolean {
149→    const now = Date.now();
150→    const timeSinceLastReset = now - this.lastResetTimestamp;
151→
152→    // リセット間隔を超え、かつ安定特徴点が十分にある
153→    return (
154→      timeSinceLastReset >= this.resetIntervalMs &&
155→      this.getStableFeatureCount() >= 3
156→    );
157→  }
158→
159→  /**
160→   * 安定特徴点の数を取得
161→   */
162→  public getStableFeatureCount(): number {
163→    let count = 0;
164→    for (const feature of this.stableFeatures.values()) {
165→      if (feature.trackedFrames >= this.minTrackedFrames) {
166→        count++;
167→      }
168→    }
169→    return count;
170→  }
171→
172→  /**
173→   * 安定特徴点のリストを取得
174→   */
175→  public getStableFeatures(): StableFeature[] {
176→    return Array.from(this.stableFeatures.values()).filter(
177→      (f) => f.trackedFrames >= this.minTrackedFrames
178→    );
179→  }
180→
181→  /**
182→   * 視覚情報から基準姿勢を計算
183→   *
184→   * 安定特徴点の重心位置から、平面の向きを推定する
185→   * Note: Uses reusable centroid vector - caller should not store the returned position
186→   */
187→  public computeVisualReference(): {
188→    position: THREE.Vector3;
189→    confidence: number;
190→  } | null {
191→    const stableFeatures = this.getStableFeatures();
192→
193→    if (stableFeatures.length < 3) {
194→      return null;
195→    }
196→
197→    // 安定特徴点の3D位置の重心を計算 - reuse centroid vector
198→    this.reusableCentroid.set(0, 0, 0);
199→    let totalConfidence = 0;
200→
201→    for (const feature of stableFeatures) {
202→      // Avoid clone() - use temp vector for weighted position
203→      this.reusableTempVector
204→        .copy(feature.position3D)
205→        .multiplyScalar(feature.confidence);
206→      this.reusableCentroid.add(this.reusableTempVector);
207→      totalConfidence += feature.confidence;
208→    }
209→
210→    if (totalConfidence > 0) {
211→      this.reusableCentroid.divideScalar(totalConfidence);
212→    }
213→
214→    const averageConfidence = totalConfidence / stableFeatures.length;
215→
216→    return {
217→      position: this.reusableCentroid,
218→      confidence: averageConfidence,
219→    };
220→  }
221→
222→  /**
223→   * ドリフト補正を実行
224→   *
225→   * @param currentIMUOrientation 現在のIMU姿勢
226→   * @param visualReference 視覚から計算した基準位置
227→   * @returns 補正後の姿勢（補正不要ならnull）
228→   * Note: Returns the same quaternion reference - caller should clone if needed
229→   */
230→  public correctDrift(
231→    currentIMUOrientation: THREE.Quaternion,
232→    visualReference: { position: THREE.Vector3; confidence: number } | null
233→  ): THREE.Quaternion | null {
234→    if (!visualReference || visualReference.confidence < 0.3) {
235→      return null;
236→    }
237→
238→    // 基準位置を更新
239→    if (!this.referencePosition) {
240→      this.referencePosition = new THREE.Vector3().copy(visualReference.position);
241→      this.lastResetTimestamp = Date.now();
242→      return null;
243→    }
244→
245→    // 位置のドリフト量を計算 - reuse vector
246→    this.reusablePositionDrift
247→      .copy(visualReference.position)
248→      .sub(this.referencePosition);
249→
250→    // ドリフトが大きい場合は基準をリセット
251→    if (this.reusablePositionDrift.length() > 0.5) {
252→      this.referencePosition.copy(visualReference.position);
253→      this.lastResetTimestamp = Date.now();
254→
255→      // 補正は行わず、新しい基準で次回から補正
256→      return null;
257→    }
258→
259→    this.lastResetTimestamp = Date.now();
260→
261→    // 現在の姿勢を返す（大きな補正は行わない）
262→    // 相補フィルタと組み合わせて使用することを想定
263→    // Note: Return same reference instead of clone - caller should clone if needed
264→    return currentIMUOrientation;
265→  }
266→
267→  /**
268→   * 平面の中心位置を取得
269→   *
270→   * 安定特徴点から平面の中心を計算
271→   */
272→  public getPlaneCenterPosition(): THREE.Vector3 | null {
273→    const reference = this.computeVisualReference();
274→    return reference?.position ?? null;
275→  }
276→
277→  /**
278→   * 視覚信頼度を取得
279→   */
280→  public getVisualConfidence(): number {
281→    const stableFeatures = this.getStableFeatures();
282→    if (stableFeatures.length === 0) {
283→      return 0;
284→    }
285→
286→    let totalConfidence = 0;
287→    for (const feature of stableFeatures) {
288→      totalConfidence += feature.confidence;
289→    }
290→
291→    return totalConfidence / stableFeatures.length;
292→  }
293→
294→  /**
295→   * 強制リセット
296→   */
297→  public forceReset(): void {
298→    this.referencePosition = null;
299→    this.lastResetTimestamp = Date.now();
300→  }
301→
302→  /**
303→   * 統計情報を取得
304→   */
305→  public getStatistics(): {
306→    totalFeatures: number;
307→    stableFeatures: number;
308→    averageConfidence: number;
309→    timeSinceLastReset: number;
310→  } {
311→    const stableFeatures = this.getStableFeatures();
312→
313→    return {
314→      totalFeatures: this.stableFeatures.size,
315→      stableFeatures: stableFeatures.length,
316→      averageConfidence: this.getVisualConfidence(),
317→      timeSinceLastReset: Date.now() - this.lastResetTimestamp,
318→    };
319→  }
320→
321→  /**
322→   * リソース解放
323→   */
324→  public dispose(): void {
325→    this.stableFeatures.clear();
326→    this.referencePosition = null;
327→  }
328→}
