  6→import * as THREE from "three";
  7→import { Vector3ExponentialSmoother } from "./ExponentialSmoother";
  8→
  9→/**
 10→ * Plane type based on gravity alignment
 11→ */
 12→export enum PlaneType {
 13→  /** Unknown orientation */
 14→  UNKNOWN = "unknown",
 15→  /** Horizontal plane (floor, table) */
 16→  HORIZONTAL = "horizontal",
 17→  /** Vertical plane (wall) */
 18→  VERTICAL = "vertical",
 19→  /** Sloped plane */
 20→  SLOPED = "sloped",
 21→}
 22→
 23→/**
 24→ * Gravity Aligner Options
 25→ */
 26→export interface GravityAlignerOptions {
 27→  /** Angle threshold for horizontal plane detection (degrees). Default: 15 */
 28→  horizontalThreshold?: number;
 29→  /** Angle threshold for vertical plane detection (degrees). Default: 15 */
 30→  verticalThreshold?: number;
 31→  /** Smoothing alpha for gravity vector. Default: 0.1 */
 32→  gravitySmoothingAlpha?: number;
 33→  /** Smoothing alpha for plane normal. Default: 0.2 */
 34→  normalSmoothingAlpha?: number;
 35→  /** Whether to force horizontal alignment for detected horizontal planes. Default: true */
 36→  forceHorizontalAlignment?: boolean;
 37→  /** Maximum correction angle per frame (degrees). Default: 5 */
 38→  maxCorrectionAnglePerFrame?: number;
 39→}
 40→
 41→/**
 42→ * Alignment result
 43→ */
 44→export interface AlignmentResult {
 45→  /** Corrected plane normal */
 46→  correctedNormal: THREE.Vector3;
 47→  /** Plane type */
 48→  planeType: PlaneType;
 49→  /** Angle between plane normal and gravity (degrees) */
 50→  angleToGravity: number;
 51→  /** Applied correction angle (degrees) */
 52→  correctionApplied: number;
 53→  /** Confidence of alignment (0-1) */
 54→  confidence: number;
 55→}
 56→
 57→/**
 58→ * Gravity Aligner
 59→ *
 60→ * Aligns detected plane normals with IMU gravity vector to improve accuracy.
 61→ * For horizontal planes (like tables), forces the normal to be perpendicular to gravity.
 62→ */
 63→export class GravityAligner {
 64→  private horizontalThreshold: number;
 65→  private verticalThreshold: number;
 66→  private forceHorizontalAlignment: boolean;
 67→  private maxCorrectionAnglePerFrame: number;
 68→
 69→  private gravitySmoother: Vector3ExponentialSmoother;
 70→  private normalSmoother: Vector3ExponentialSmoother;
 71→
 72→  private smoothedGravity: THREE.Vector3 = new THREE.Vector3(0, -1, 0);
 73→  private lastPlaneNormal: THREE.Vector3 | null = null;
 74→  private planeType: PlaneType = PlaneType.UNKNOWN;
 75→
 76→  // Reusable objects to prevent GC pressure
 77→  private readonly reusableNormalized: THREE.Vector3 = new THREE.Vector3();
 78→  private readonly reusableNormal: THREE.Vector3 = new THREE.Vector3();
 79→  private readonly reusableCorrectedNormal: THREE.Vector3 = new THREE.Vector3();
 80→  private readonly reusableTargetNormal: THREE.Vector3 = new THREE.Vector3();
 81→  private readonly reusableGravityComponent: THREE.Vector3 = new THREE.Vector3();
 82→  private readonly reusableQuaternion: THREE.Quaternion = new THREE.Quaternion();
 83→
 84→  constructor(options?: GravityAlignerOptions) {
 85→    this.horizontalThreshold = options?.horizontalThreshold ?? 15;
 86→    this.verticalThreshold = options?.verticalThreshold ?? 15;
 87→    this.forceHorizontalAlignment = options?.forceHorizontalAlignment ?? true;
 88→    this.maxCorrectionAnglePerFrame = options?.maxCorrectionAnglePerFrame ?? 5;
 89→
 90→    this.gravitySmoother = new Vector3ExponentialSmoother(
 91→      options?.gravitySmoothingAlpha ?? 0.1
 92→    );
 93→    this.normalSmoother = new Vector3ExponentialSmoother(
 94→      options?.normalSmoothingAlpha ?? 0.2
 95→    );
 96→  }
 97→
 98→  /**
 99→   * Update gravity vector from IMU
100→   *
101→   * @param gravityVector Gravity vector from IMU (typically pointing down)
102→   */
103→  public updateGravity(gravityVector: THREE.Vector3): void {
104→    // Normalize and smooth - reuse vector instead of clone
105→    this.reusableNormalized.copy(gravityVector).normalize();
106→    const smoothed = this.gravitySmoother.update(
107→      this.reusableNormalized.x,
108→      this.reusableNormalized.y,
109→      this.reusableNormalized.z
110→    );
111→    this.smoothedGravity.set(smoothed.x, smoothed.y, smoothed.z).normalize();
112→  }
113→
114→  /**
115→   * Align plane normal with gravity
116→   *
117→   * @param planeNormal Original plane normal from RANSAC
118→   * @returns Alignment result with corrected normal
119→   * Note: correctedNormal in result uses reusable vector - caller should copy if storing
120→   */
121→  public alignPlaneNormal(planeNormal: THREE.Vector3): AlignmentResult {
122→    // Reuse normal vector instead of clone
123→    this.reusableNormal.copy(planeNormal).normalize();
124→
125→    // Calculate angle between plane normal and gravity
126→    // For horizontal planes: normal should be parallel to gravity (0 or 180 degrees)
127→    // For vertical planes: normal should be perpendicular to gravity (90 degrees)
128→    const dotProduct = this.reusableNormal.dot(this.smoothedGravity);
129→    const angleToGravity = Math.acos(Math.abs(dotProduct)) * (180 / Math.PI);
130→
131→    // Determine plane type
132→    this.planeType = this.determinePlaneType(angleToGravity);
133→
134→    // Reuse corrected normal vector
135→    this.reusableCorrectedNormal.copy(this.reusableNormal);
136→    let correctionApplied = 0;
137→    let confidence = 1.0;
138→
139→    if (
140→      this.planeType === PlaneType.HORIZONTAL &&
141→      this.forceHorizontalAlignment
142→    ) {
143→      // Force horizontal alignment: normal should be parallel to gravity
144→      const sign = dotProduct >= 0 ? 1 : -1;
145→      // Reuse target normal vector
146→      this.reusableTargetNormal.copy(this.smoothedGravity).multiplyScalar(sign);
147→
148→      // Calculate correction
149→      const correctionAngle =
150→        this.reusableNormal.angleTo(this.reusableTargetNormal) *
151→        (180 / Math.PI);
152→
153→      // Limit correction per frame
154→      const actualCorrection = Math.min(
155→        correctionAngle,
156→        this.maxCorrectionAnglePerFrame
157→      );
158→
159→      if (actualCorrection > 0.1) {
160→        // Interpolate towards target
161→        const t = actualCorrection / correctionAngle;
162→        this.reusableCorrectedNormal
163→          .lerp(this.reusableTargetNormal, t)
164→          .normalize();
165→        correctionApplied = actualCorrection;
166→      } else {
167→        this.reusableCorrectedNormal.copy(this.reusableTargetNormal);
168→        correctionApplied = correctionAngle;
169→      }
170→
171→      confidence = 1.0 - angleToGravity / this.horizontalThreshold;
172→    } else if (this.planeType === PlaneType.VERTICAL) {
173→      // For vertical planes, ensure normal is perpendicular to gravity
174→      // Reuse gravity component vector
175→      this.reusableGravityComponent
176→        .copy(this.smoothedGravity)
177→        .multiplyScalar(dotProduct);
178→      this.reusableCorrectedNormal
179→        .copy(this.reusableNormal)
180→        .sub(this.reusableGravityComponent)
181→        .normalize();
182→
183→      const correctionAngle =
184→        Math.abs(90 - angleToGravity) > this.maxCorrectionAnglePerFrame
185→          ? this.maxCorrectionAnglePerFrame
186→          : Math.abs(90 - angleToGravity);
187→      correctionApplied = correctionAngle;
188→      confidence = 1.0 - Math.abs(90 - angleToGravity) / this.verticalThreshold;
189→    }
190→
191→    // Smooth the corrected normal
192→    const smoothed = this.normalSmoother.update(
193→      this.reusableCorrectedNormal.x,
194→      this.reusableCorrectedNormal.y,
195→      this.reusableCorrectedNormal.z
196→    );
197→    this.reusableCorrectedNormal
198→      .set(smoothed.x, smoothed.y, smoothed.z)
199→      .normalize();
200→
201→    // Update lastPlaneNormal - allocate once if null, then copy
202→    if (!this.lastPlaneNormal) {
203→      this.lastPlaneNormal = new THREE.Vector3();
204→    }
205→    this.lastPlaneNormal.copy(this.reusableCorrectedNormal);
206→
207→    return {
208→      correctedNormal: this.reusableCorrectedNormal,
209→      planeType: this.planeType,
210→      angleToGravity,
211→      correctionApplied,
212→      confidence: Math.max(0, Math.min(1, confidence)),
213→    };
214→  }
215→
216→  /**
217→   * Determine plane type based on angle to gravity
218→   */
219→  private determinePlaneType(angleToGravity: number): PlaneType {
220→    // Angle between normal and gravity:
221→    // - 0° or 180°: Normal is parallel to gravity = HORIZONTAL plane
222→    // - 90°: Normal is perpendicular to gravity = VERTICAL plane
223→
224→    if (angleToGravity < this.horizontalThreshold) {
225→      return PlaneType.HORIZONTAL;
226→    } else if (Math.abs(90 - angleToGravity) < this.verticalThreshold) {
227→      return PlaneType.VERTICAL;
228→    } else {
229→      return PlaneType.SLOPED;
230→    }
231→  }
232→
233→  /**
234→   * Get the current smoothed gravity vector
235→   */
236→  public getGravityVector(): THREE.Vector3 {
237→    return this.smoothedGravity.clone();
238→  }
239→
240→  /**
241→   * Get the current plane type
242→   */
243→  public getPlaneType(): PlaneType {
244→    return this.planeType;
245→  }
246→
247→  /**
248→   * Get the last corrected plane normal
249→   */
250→  public getLastPlaneNormal(): THREE.Vector3 | null {
251→    return this.lastPlaneNormal?.clone() ?? null;
252→  }
253→
254→  /**
255→   * Check if gravity data is available
256→   */
257→  public hasGravityData(): boolean {
258→    return (
259→      this.gravitySmoother.getValue().x !== 0 ||
260→      this.gravitySmoother.getValue().y !== 0 ||
261→      this.gravitySmoother.getValue().z !== 0
262→    );
263→  }
264→
265→  /**
266→   * Create a rotation quaternion to align the plane with gravity
267→   *
268→   * @param currentNormal Current plane normal
269→   * @returns Quaternion to rotate the plane to align with gravity
270→   * Note: Returns reusable quaternion - caller should copy if storing
271→   */
272→  public getAlignmentQuaternion(
273→    currentNormal: THREE.Vector3
274→  ): THREE.Quaternion {
275→    const result = this.alignPlaneNormal(currentNormal);
276→
277→    // Reuse quaternion
278→    this.reusableQuaternion.setFromUnitVectors(
279→      this.reusableNormal, // Already normalized in alignPlaneNormal
280→      result.correctedNormal
281→    );
282→
283→    return this.reusableQuaternion;
284→  }
285→
286→  /**
287→   * Get statistics
288→   */
289→  public getStatistics(): {
290→    gravityVector: { x: number; y: number; z: number };
291→    planeType: PlaneType;
292→    hasGravityData: boolean;
293→  } {
294→    const gravity = this.smoothedGravity;
295→    return {
296→      gravityVector: { x: gravity.x, y: gravity.y, z: gravity.z },
297→      planeType: this.planeType,
298→      hasGravityData: this.hasGravityData(),
299→    };
300→  }
301→
302→  /**
303→   * Reset the aligner
304→   */
305→  public reset(): void {
306→    this.gravitySmoother.reset();
307→    this.normalSmoother.reset();
308→    this.smoothedGravity.set(0, -1, 0);
309→    this.lastPlaneNormal = null;
310→    this.planeType = PlaneType.UNKNOWN;
311→  }
312→
313→  /**
314→   * Dispose resources
315→   */
316→  public dispose(): void {
317→    this.reset();
318→  }
319→}
