  6→import * as THREE from "three";
  7→import {
  8→  DeviceOrientationData,
  9→  DeviceMotionData,
 10→  RotationRate,
 11→  DeviceMotionTrackerState,
 12→  DeviceMotionTrackerEvent,
 13→  DeviceMotionTrackerListener,
 14→  DriftMeasurement,
 15→  DriftStatistics,
 16→} from "../types/DeviceMotion";
 17→import { PoseRepresentation } from "./PoseRepresentation";
 18→import { IMUInitializer } from "./IMUInitializer";
 19→
 20→/**
 21→ * iOS Safari向けの型拡張
 22→ */
 23→interface DeviceOrientationEventStatic {
 24→  new (
 25→    type: string,
 26→    eventInitDict?: DeviceOrientationEventInit
 27→  ): DeviceOrientationEvent;
 28→  prototype: DeviceOrientationEvent;
 29→  requestPermission?: () => Promise<"granted" | "denied">;
 30→}
 31→
 32→interface DeviceMotionEventStatic {
 33→  new (type: string, eventInitDict?: DeviceMotionEventInit): DeviceMotionEvent;
 34→  prototype: DeviceMotionEvent;
 35→  requestPermission?: () => Promise<"granted" | "denied">;
 36→}
 37→
 38→declare const DeviceOrientationEvent: DeviceOrientationEventStatic;
 39→declare const DeviceMotionEvent: DeviceMotionEventStatic;
 40→
 41→/**
 42→ * デバイスモーショントラッカー
 43→ * IMU（加速度計・ジャイロスコープ）を利用した姿勢推定を行う
 44→ */
 45→export class DeviceMotionTracker {
 46→  private state: DeviceMotionTrackerState =
 47→    DeviceMotionTrackerState.UNINITIALIZED;
 48→  private listeners: Set<DeviceMotionTrackerListener> = new Set();
 49→
 50→  private orientation: DeviceOrientationData | null = null;
 51→  private motion: DeviceMotionData | null = null;
 52→  private currentQuaternion: THREE.Quaternion = new THREE.Quaternion();
 53→
 54→  private poseRepresentation: PoseRepresentation;
 55→  private imuInitializer: IMUInitializer;
 56→
 57→  private driftMeasurements: DriftMeasurement[] = [];
 58→  private referenceQuaternion: THREE.Quaternion | null = null;
 59→  private referenceTimestamp: number = 0;
 60→  private readonly maxDriftMeasurements: number = 100;
 61→
 62→  private boundHandleOrientation: (event: DeviceOrientationEvent) => void;
 63→  private boundHandleMotion: (event: DeviceMotionEvent) => void;
 64→
 65→  // IMU throttling - limit event processing to reduce CPU and memory usage
 66→  private imuThrottleInterval: number = 33; // ~30Hz (1000ms / 30)
 67→  private lastOrientationTime: number = 0;
 68→  private lastMotionTime: number = 0;
 69→
 70→  // Reusable objects to prevent GC pressure from high-frequency IMU events
 71→  private reusableAccelerationVector: THREE.Vector3 = new THREE.Vector3();
 72→  private reusableLinearAccelerationVector: THREE.Vector3 = new THREE.Vector3();
 73→  private reusableRotationRate: RotationRate = { alpha: 0, beta: 0, gamma: 0 };
 74→  private reusableMotionData: DeviceMotionData = {
 75→    accelerationIncludingGravity: new THREE.Vector3(),
 76→    acceleration: null,
 77→    rotationRate: { alpha: 0, beta: 0, gamma: 0 },
 78→    interval: 16,
 79→    timestamp: 0,
 80→  };
 81→
 82→  constructor() {
 83→    this.poseRepresentation = new PoseRepresentation();
 84→    this.imuInitializer = new IMUInitializer();
 85→
 86→    this.boundHandleOrientation = this.handleDeviceOrientation.bind(this);
 87→    this.boundHandleMotion = this.handleDeviceMotion.bind(this);
 88→  }
 89→
 90→  /**
 91→   * 現在の状態を取得
 92→   */
 93→  public getState(): DeviceMotionTrackerState {
 94→    return this.state;
 95→  }
 96→
 97→  /**
 98→   * イベントリスナーを追加
 99→   */
100→  public addListener(listener: DeviceMotionTrackerListener): void {
101→    this.listeners.add(listener);
102→  }
103→
104→  /**
105→   * イベントリスナーを削除
106→   */
107→  public removeListener(listener: DeviceMotionTrackerListener): void {
108→    this.listeners.delete(listener);
109→  }
110→
111→  /**
112→   * 初期化（権限要求含む）
113→   */
114→  public async initialize(): Promise<boolean> {
115→    if (!this.isSecureContext()) {
116→      this.setState(DeviceMotionTrackerState.ERROR);
117→      this.emitError(new Error("Sensor APIs require a secure context (HTTPS)"));
118→      return false;
119→    }
120→
121→    if (!this.isSensorApiAvailable()) {
122→      this.setState(DeviceMotionTrackerState.ERROR);
123→      this.emitError(
124→        new Error("DeviceOrientation/DeviceMotion API not available")
125→      );
126→      return false;
127→    }
128→
129→    this.setState(DeviceMotionTrackerState.REQUESTING_PERMISSION);
130→
131→    const permissionGranted = await this.requestPermission();
132→    if (!permissionGranted) {
133→      this.setState(DeviceMotionTrackerState.PERMISSION_DENIED);
134→      return false;
135→    }
136→
137→    this.setState(DeviceMotionTrackerState.INITIALIZING);
138→    this.startListening();
139→
140→    return true;
141→  }
142→
143→  /**
144→   * セキュアコンテキストかチェック
145→   */
146→  private isSecureContext(): boolean {
147→    if (typeof window === "undefined") return false;
148→    return window.isSecureContext || window.location.hostname === "localhost";
149→  }
150→
151→  /**
152→   * センサーAPIが利用可能かチェック
153→   */
154→  private isSensorApiAvailable(): boolean {
155→    return (
156→      typeof window !== "undefined" &&
157→      "DeviceOrientationEvent" in window &&
158→      "DeviceMotionEvent" in window
159→    );
160→  }
161→
162→  /**
163→   * 権限を要求（iOS Safari対応）
164→   */
165→  private async requestPermission(): Promise<boolean> {
166→    try {
167→      if (
168→        typeof DeviceOrientationEvent !== "undefined" &&
169→        typeof DeviceOrientationEvent.requestPermission === "function"
170→      ) {
171→        const orientationPermission =
172→          await DeviceOrientationEvent.requestPermission();
173→        if (orientationPermission !== "granted") {
174→          return false;
175→        }
176→      }
177→
178→      if (
179→        typeof DeviceMotionEvent !== "undefined" &&
180→        typeof DeviceMotionEvent.requestPermission === "function"
181→      ) {
182→        const motionPermission = await DeviceMotionEvent.requestPermission();
183→        if (motionPermission !== "granted") {
184→          return false;
185→        }
186→      }
187→
188→      return true;
189→    } catch (error) {
190→      console.error("Permission request failed:", error);
191→      return false;
192→    }
193→  }
194→
195→  /**
196→   * センサーイベントのリッスンを開始
197→   */
198→  private startListening(): void {
199→    window.addEventListener(
200→      "deviceorientation",
201→      this.boundHandleOrientation,
202→      true
203→    );
204→    window.addEventListener("devicemotion", this.boundHandleMotion, true);
205→  }
206→
207→  /**
208→   * センサーイベントのリッスンを停止
209→   */
210→  private stopListening(): void {
211→    window.removeEventListener(
212→      "deviceorientation",
213→      this.boundHandleOrientation,
214→      true
215→    );
216→    window.removeEventListener("devicemotion", this.boundHandleMotion, true);
217→  }
218→
219→  /**
220→   * DeviceOrientationイベントハンドラー
221→   * Throttled to ~30Hz to reduce CPU and memory usage
222→   */
223→  private handleDeviceOrientation(event: DeviceOrientationEvent): void {
224→    if (event.alpha === null || event.beta === null || event.gamma === null) {
225→      return;
226→    }
227→
228→    // Throttle orientation events to reduce CPU usage
229→    const now = performance.now();
230→    if (now - this.lastOrientationTime < this.imuThrottleInterval) {
231→      return;
232→    }
233→    this.lastOrientationTime = now;
234→
235→    this.orientation = {
236→      alpha: event.alpha,
237→      beta: event.beta,
238→      gamma: event.gamma,
239→      timestamp: Date.now(),
240→      absolute: event.absolute || false,
241→    };
242→
243→    this.currentQuaternion = this.poseRepresentation.orientationToQuaternion(
244→      this.orientation
245→    );
246→
247→    if (this.state === DeviceMotionTrackerState.INITIALIZING) {
248→      if (this.imuInitializer.isReady()) {
249→        this.setState(DeviceMotionTrackerState.TRACKING);
250→        this.startDriftMeasurement();
251→      }
252→    }
253→
254→    this.emitOrientationUpdate();
255→  }
256→
257→  /**
258→   * DeviceMotionイベントハンドラー
259→   * Throttled to ~30Hz to reduce CPU and memory usage
260→   * Note: Uses reusable objects to prevent GC pressure from 60-120Hz events
261→   */
262→  private handleDeviceMotion(event: DeviceMotionEvent): void {
263→    const acceleration = event.accelerationIncludingGravity;
264→    const linearAcceleration = event.acceleration;
265→    const rotationRate = event.rotationRate;
266→
267→    if (!acceleration) return;
268→
269→    // Throttle motion events to reduce CPU usage
270→    const now = performance.now();
271→    if (now - this.lastMotionTime < this.imuThrottleInterval) {
272→      return;
273→    }
274→    this.lastMotionTime = now;
275→
276→    // Reuse vector objects instead of creating new ones
277→    this.reusableAccelerationVector.set(
278→      acceleration.x ?? 0,
279→      acceleration.y ?? 0,
280→      acceleration.z ?? 0
281→    );
282→
283→    if (linearAcceleration) {
284→      this.reusableLinearAccelerationVector.set(
285→        linearAcceleration.x ?? 0,
286→        linearAcceleration.y ?? 0,
287→        linearAcceleration.z ?? 0
288→      );
289→    }
290→
291→    // Reuse rotation rate object
292→    this.reusableRotationRate.alpha = rotationRate?.alpha ?? 0;
293→    this.reusableRotationRate.beta = rotationRate?.beta ?? 0;
294→    this.reusableRotationRate.gamma = rotationRate?.gamma ?? 0;
295→
296→    // Update motion data in place instead of creating new object
297→    this.reusableMotionData.accelerationIncludingGravity.copy(
298→      this.reusableAccelerationVector
299→    );
300→    this.reusableMotionData.acceleration = linearAcceleration
301→      ? this.reusableLinearAccelerationVector
302→      : null;
303→    this.reusableMotionData.rotationRate.alpha = this.reusableRotationRate.alpha;
304→    this.reusableMotionData.rotationRate.beta = this.reusableRotationRate.beta;
305→    this.reusableMotionData.rotationRate.gamma = this.reusableRotationRate.gamma;
306→    this.reusableMotionData.interval = event.interval ?? 16;
307→    this.reusableMotionData.timestamp = Date.now();
308→
309→    this.motion = this.reusableMotionData;
310→
311→    if (this.state === DeviceMotionTrackerState.INITIALIZING) {
312→      // Reuse acceleration vector for initializer
313→      this.imuInitializer.addSample(
314→        this.reusableAccelerationVector,
315→        this.reusableLinearAccelerationVector.set(
316→          this.reusableRotationRate.alpha,
317→          this.reusableRotationRate.beta,
318→          this.reusableRotationRate.gamma
319→        )
320→      );
321→    }
322→
323→    this.emitMotionUpdate();
324→  }
325→
326→  /**
327→   * 現在の姿勢を取得（クォータニオン）
328→   * INITIALIZING状態以降であれば姿勢データを返す
329→   */
330→  public getOrientation(): THREE.Quaternion | null {
331→    // UNINITIALIZED, REQUESTING_PERMISSION, PERMISSION_DENIED, ERROR の場合はnull
332→    if (
333→      this.state === DeviceMotionTrackerState.UNINITIALIZED ||
334→      this.state === DeviceMotionTrackerState.REQUESTING_PERMISSION ||
335→      this.state === DeviceMotionTrackerState.PERMISSION_DENIED ||
336→      this.state === DeviceMotionTrackerState.ERROR
337→    ) {
338→      return null;
339→    }
340→    return this.currentQuaternion.clone();
341→  }
342→
343→  /**
344→   * 現在の回転行列を取得
345→   */
346→  public getRotationMatrix(): THREE.Matrix4 | null {
347→    const orientation = this.getOrientation();
348→    if (!orientation) return null;
349→    return this.poseRepresentation.quaternionToMatrix4(orientation);
350→  }
351→
352→  /**
353→   * 重力除去済み加速度を取得
354→   */
355→  public getLinearAcceleration(): THREE.Vector3 | null {
356→    if (!this.motion?.acceleration) return null;
357→    return this.motion.acceleration.clone();
358→  }
359→
360→  /**
361→   * 角速度を取得
362→   */
363→  public getAngularVelocity(): THREE.Vector3 | null {
364→    if (!this.motion) return null;
365→    return new THREE.Vector3(
366→      this.motion.rotationRate.alpha,
367→      this.motion.rotationRate.beta,
368→      this.motion.rotationRate.gamma
369→    );
370→  }
371→
372→  /**
373→   * 重力ベクトルを取得
374→   *
375→   * デバイスの加速度センサーから重力方向を推定する。
376→   * 静止時または等速運動時に最も正確な値を返す。
377→   */
378→  public getGravityVector(): THREE.Vector3 | null {
379→    if (!this.motion) return null;
380→
381→    const acceleration = this.motion.accelerationIncludingGravity;
382→    const linearAcceleration = this.motion.acceleration;
383→
384→    if (linearAcceleration) {
385→      // 線形加速度がある場合、重力 = 総加速度 - 線形加速度
386→      return new THREE.Vector3(
387→        acceleration.x - linearAcceleration.x,
388→        acceleration.y - linearAcceleration.y,
389→        acceleration.z - linearAcceleration.z
390→      ).normalize();
391→    }
392→
393→    // 線形加速度がない場合、総加速度を正規化して返す
394→    // （静止時は総加速度 ≈ 重力）
395→    return acceleration.clone().normalize();
396→  }
397→
398→  /**
399→   * デバイス座標系のベクトルをワールド座標系に変換
400→   */
401→  public deviceToWorld(deviceVector: THREE.Vector3): THREE.Vector3 {
402→    const orientation = this.getOrientation();
403→    if (!orientation) return deviceVector.clone();
404→    return this.poseRepresentation.deviceToWorld(deviceVector, orientation);
405→  }
406→
407→  /**
408→   * IMU初期化器を取得
409→   */
410→  public getIMUInitializer(): IMUInitializer {
411→    return this.imuInitializer;
412→  }
413→
414→  /**
415→   * ドリフト計測を開始
416→   */
417→  private startDriftMeasurement(): void {
418→    this.referenceQuaternion = this.currentQuaternion.clone();
419→    this.referenceTimestamp = Date.now();
420→    this.driftMeasurements = [];
421→  }
422→
423→  // Reusable objects for drift measurement
424→  private reusableDriftQuaternion: THREE.Quaternion = new THREE.Quaternion();
425→  private reusableInverseQuaternion: THREE.Quaternion = new THREE.Quaternion();
426→
427→  /**
428→   * 現在のドリフトを記録
429→   * Note: Uses ring buffer pattern to avoid shift() which is O(n)
430→   */
431→  public recordDrift(): void {
432→    if (
433→      !this.referenceQuaternion ||
434→      this.state !== DeviceMotionTrackerState.TRACKING
435→    ) {
436→      return;
437→    }
438→
439→    const now = Date.now();
440→    const elapsedTime = (now - this.referenceTimestamp) / 1000;
441→
442→    // Reuse quaternions instead of clone()
443→    this.reusableInverseQuaternion.copy(this.referenceQuaternion).invert();
444→    this.reusableDriftQuaternion
445→      .copy(this.currentQuaternion)
446→      .multiply(this.reusableInverseQuaternion);
447→
448→    // Use ring buffer pattern instead of shift() which is O(n)
449→    if (this.driftMeasurements.length >= this.maxDriftMeasurements) {
450→      // Reuse oldest measurement object
451→      const oldest = this.driftMeasurements.shift()!;
452→      oldest.elapsedTime = elapsedTime;
453→      oldest.orientationDrift.copy(this.reusableDriftQuaternion);
454→      oldest.timestamp = now;
455→      this.driftMeasurements.push(oldest);
456→    } else {
457→      // Create new measurement only when buffer isn't full
458→      this.driftMeasurements.push({
459→        elapsedTime,
460→        positionDrift: new THREE.Vector3(),
461→        orientationDrift: this.reusableDriftQuaternion.clone(),
462→        timestamp: now,
463→      });
464→    }
465→  }
466→
467→  /**
468→   * ドリフト統計を取得
469→   */
470→  public getDriftStatistics(): DriftStatistics {
471→    if (this.driftMeasurements.length === 0) {
472→      return {
473→        measurements: [],
474→        averagePositionDriftRate: 0,
475→        averageOrientationDriftRate: 0,
476→        maxPositionDrift: 0,
477→        maxOrientationDrift: 0,
478→      };
479→    }
480→
481→    let maxOrientationDrift = 0;
482→    let totalOrientationDrift = 0;
483→
484→    for (const measurement of this.driftMeasurements) {
485→      const angle =
486→        2 * Math.acos(Math.min(1, Math.abs(measurement.orientationDrift.w)));
487→      totalOrientationDrift += angle;
488→      maxOrientationDrift = Math.max(maxOrientationDrift, angle);
489→    }
490→
491→    const lastMeasurement =
492→      this.driftMeasurements[this.driftMeasurements.length - 1];
493→    const averageOrientationDriftRate =
494→      lastMeasurement.elapsedTime > 0
495→        ? totalOrientationDrift / lastMeasurement.elapsedTime
496→        : 0;
497→
498→    return {
499→      measurements: [...this.driftMeasurements],
500→      averagePositionDriftRate: 0,
501→      averageOrientationDriftRate,
502→      maxPositionDrift: 0,
503→      maxOrientationDrift,
504→    };
505→  }
506→
507→  /**
508→   * ドリフト計測をリセット
509→   */
510→  public resetDriftMeasurement(): void {
511→    this.startDriftMeasurement();
512→  }
513→
514→  /**
515→   * 状態を変更
516→   */
517→  private setState(newState: DeviceMotionTrackerState): void {
518→    if (this.state === newState) return;
519→
520→    this.state = newState;
521→    this.emit({
522→      type: "stateChange",
523→      state: newState,
524→      timestamp: Date.now(),
525→    });
526→  }
527→
528→  /**
529→   * 姿勢更新イベントを発行
530→   * Note: Listeners should NOT modify the orientation object (it's reused)
531→   */
532→  private emitOrientationUpdate(): void {
533→    if (!this.orientation) return;
534→    // Avoid spread - listeners must not modify this object
535→    this.emit({
536→      type: "orientationUpdate",
537→      orientation: this.orientation,
538→      timestamp: this.orientation.timestamp,
539→    });
540→  }
541→
542→  /**
543→   * モーション更新イベントを発行
544→   * Note: Listeners should NOT modify the motion object (it's reused)
545→   */
546→  private emitMotionUpdate(): void {
547→    if (!this.motion) return;
548→    // Avoid clone() - listeners must not modify this object
549→    this.emit({
550→      type: "motionUpdate",
551→      motion: this.motion,
552→      timestamp: this.motion.timestamp,
553→    });
554→  }
555→
556→  /**
557→   * エラーイベントを発行
558→   */
559→  private emitError(error: Error): void {
560→    this.emit({
561→      type: "error",
562→      error,
563→      timestamp: Date.now(),
564→    });
565→  }
566→
567→  /**
568→   * イベントを発行
569→   */
570→  private emit(event: DeviceMotionTrackerEvent): void {
571→    for (const listener of this.listeners) {
572→      try {
573→        listener(event);
574→      } catch (error) {
575→        console.error("Error in DeviceMotionTracker listener:", error);
576→      }
577→    }
578→  }
579→
580→  /**
581→   * トラッキングが有効かどうか
582→   * INITIALIZING または TRACKING 状態であればtrue
583→   */
584→  public isTracking(): boolean {
585→    return (
586→      this.state === DeviceMotionTrackerState.INITIALIZING ||
587→      this.state === DeviceMotionTrackerState.TRACKING
588→    );
589→  }
590→
591→  /**
592→   * 初期化完了を待機
593→   */
594→  public waitForInitialization(
595→    timeoutMilliseconds: number = 5000
596→  ): Promise<boolean> {
597→    return new Promise((resolve) => {
598→      if (this.state === DeviceMotionTrackerState.TRACKING) {
599→        resolve(true);
600→        return;
601→      }
602→
603→      if (
604→        this.state === DeviceMotionTrackerState.PERMISSION_DENIED ||
605→        this.state === DeviceMotionTrackerState.ERROR
606→      ) {
607→        resolve(false);
608→        return;
609→      }
610→
611→      const timeout = setTimeout(() => {
612→        this.removeListener(listener);
613→        resolve(false);
614→      }, timeoutMilliseconds);
615→
616→      const listener: DeviceMotionTrackerListener = (event) => {
617→        if (event.type === "stateChange") {
618→          if (event.state === DeviceMotionTrackerState.TRACKING) {
619→            clearTimeout(timeout);
620→            this.removeListener(listener);
621→            resolve(true);
622→          } else if (
623→            event.state === DeviceMotionTrackerState.PERMISSION_DENIED ||
624→            event.state === DeviceMotionTrackerState.ERROR
625→          ) {
626→            clearTimeout(timeout);
627→            this.removeListener(listener);
628→            resolve(false);
629→          }
630→        }
631→      };
632→
633→      this.addListener(listener);
634→    });
635→  }
636→
637→  /**
638→   * リソース解放
639→   */
640→  public dispose(): void {
641→    this.stopListening();
642→    this.poseRepresentation.dispose();
643→    this.listeners.clear();
644→    this.orientation = null;
645→    this.motion = null;
646→    this.state = DeviceMotionTrackerState.UNINITIALIZED;
647→  }
648→}
