  6→import type {
  7→  PlaneModel,
  8→  Feature,
  9→  PlaneFittingResult,
 10→  Point3D,
 11→} from "../types";
 12→import type { PlaneEstimationConfig } from "../config/types";
 13→import { defaultConfig } from "../config/defaults";
 14→import fitPlaneRANSAC, {
 15→  filterByDepth,
 16→  distancePointToPlane,
 17→} from "../helpers/fitPlaneRANSAC";
 18→import projectInliersToPlane2D from "../helpers/projectInliersToPlane2D";
 19→import computeConvexHull2D from "../helpers/computeConvexHull2D";
 20→import liftHull2DTo3D from "../helpers/liftHull2DTo3D";
 21→import { weightedPlaneFit2D } from "../helpers/weightedPlaneFit2D";
 22→import sampleDepthAtFeaturePoints from "../helpers/sampleDepthAtFeaturePoints";
 23→import backProjectPoints, {
 24→  getCameraIntrinsics,
 25→  type CameraIntrinsics,
 26→} from "../helpers/backProjectPoints";
 27→import * as THREE from "three";
 28→
 29→export type { PlaneFittingResult } from "../types";
 30→
 31→/**
 32→ * 平面フィッティングサービス
 33→ * 特徴点と深度情報から平面を推定する機能を提供
 34→ */
 35→export class PlaneFittingService {
 36→  private config: PlaneEstimationConfig;
 37→  private fittingResults: PlaneFittingResult[] = [];
 38→  private fittingCount: number = 0;
 39→  private cachedIntrinsics: CameraIntrinsics | null = null;
 40→  private cachedVideoSize: { width: number; height: number } | null = null;
 41→
 42→  constructor(config?: Partial<PlaneEstimationConfig>) {
 43→    this.config = {
 44→      ...defaultConfig.plane,
 45→      ...config,
 46→    };
 47→  }
 48→
 49→  /**
 50→   * 設定を更新
 51→   */
 52→  public updateConfig(config: Partial<PlaneEstimationConfig>): void {
 53→    this.config = {
 54→      ...this.config,
 55→      ...config,
 56→    };
 57→  }
 58→
 59→  /**
 60→   * フィッティング結果をリセット
 61→   */
 62→  public reset(): void {
 63→    this.fittingResults = [];
 64→    this.fittingCount = 0;
 65→  }
 66→
 67→  /**
 68→   * カメラ内部パラメータを取得（キャッシュ付き）
 69→   */
 70→  private getIntrinsics(
 71→    videoWidth: number,
 72→    videoHeight: number
 73→  ): CameraIntrinsics {
 74→    if (
 75→      this.cachedIntrinsics &&
 76→      this.cachedVideoSize?.width === videoWidth &&
 77→      this.cachedVideoSize?.height === videoHeight
 78→    ) {
 79→      return this.cachedIntrinsics;
 80→    }
 81→
 82→    this.cachedIntrinsics = getCameraIntrinsics(
 83→      this.config.cameraIntrinsics,
 84→      videoWidth,
 85→      videoHeight
 86→    );
 87→    this.cachedVideoSize = { width: videoWidth, height: videoHeight };
 88→
 89→    return this.cachedIntrinsics;
 90→  }
 91→
 92→  /**
 93→   * 平面フィッティングを実行
 94→   */
 95→  public async performFitting(
 96→    featurePoints: Feature[],
 97→    depthMap: Float32Array | null,
 98→    mapWidth: number,
 99→    mapHeight: number,
100→    centerFeature: Feature,
101→    videoWidth?: number,
102→    videoHeight?: number
103→  ): Promise<PlaneFittingResult | null> {
104→    if (!featurePoints || featurePoints.length === 0) {
105→      console.warn("No feature points provided for plane fitting");
106→      return null;
107→    }
108→
109→    const safeMapWidth = Math.max(mapWidth || 640, 1);
110→    const safeMapHeight = Math.max(mapHeight || 480, 1);
111→
112→    const safeVideoWidth = videoWidth || safeMapWidth;
113→    const safeVideoHeight = videoHeight || safeMapHeight;
114→
115→    const points3D = sampleDepthAtFeaturePoints({
116→      featurePoints,
117→      depthMap,
118→      mapWidth: safeMapWidth,
119→      mapHeight: safeMapHeight,
120→      // Features are in original video coordinates, depth map is in scaled canvas coordinates
121→      featureWidth: safeVideoWidth,
122→      featureHeight: safeVideoHeight,
123→    });
124→
125→    const intrinsics = this.getIntrinsics(safeVideoWidth, safeVideoHeight);
126→
127→    const points3DBackProjected = backProjectPoints({
128→      points: points3D,
129→      intrinsics,
130→    });
131→
132→    // 深度フィルタリング
133→    const filteredPoints3D = filterByDepth(
134→      points3DBackProjected,
135→      this.config.depthFilterDelta
136→    );
137→
138→    // RANSACで平面フィッティング
139→    const planeModel = fitPlaneRANSAC({
140→      points: filteredPoints3D,
141→      iterations: this.config.ransacIterations,
142→      threshold: this.config.ransacThreshold,
143→    });
144→
145→    if (!planeModel.model) return null;
146→
147→    // 重み付き平面フィッティング
148→    const refinedModel = this.performWeightedFitting(
149→      planeModel,
150→      featurePoints,
151→      depthMap,
152→      safeMapWidth,
153→      safeMapHeight
154→    );
155→
156→    // 平面座標系を構築
157→    const result = this.constructPlaneCoordinates(
158→      refinedModel,
159→      planeModel.inliers,
160→      points3DBackProjected,
161→      centerFeature
162→    );
163→
164→    if (result && this.fittingCount < this.config.smoothingIterations) {
165→      this.fittingResults.push(result);
166→      this.fittingCount++;
167→    }
168→
169→    return result;
170→  }
171→
172→  /**
173→   * 平均化された結果を取得
174→   */
175→  public getAveragedResult(): PlaneFittingResult | null {
176→    if (this.fittingResults.length !== this.config.smoothingIterations) {
177→      return null;
178→    }
179→
180→    return this.calculateAverageResults();
181→  }
182→
183→  /**
184→   * フィッティングが完了したかチェック
185→   */
186→  public isComplete(): boolean {
187→    return this.fittingCount >= this.config.smoothingIterations;
188→  }
189→
190→  /**
191→   * 現在の進捗を取得
192→   */
193→  public getProgress(): { current: number; total: number } {
194→    return {
195→      current: this.fittingCount,
196→      total: this.config.smoothingIterations,
197→    };
198→  }
199→
200→  /**
201→   * 重み付き平面フィッティングを実行
202→   */
203→  private performWeightedFitting(
204→    planeModel: { model: PlaneModel | null; inliers: Point3D[] },
205→    trackedFeatures: Feature[],
206→    depthMap: Float32Array | null,
207→    mapWidth: number,
208→    mapHeight: number
209→  ): PlaneModel {
210→    const inliers = planeModel.inliers;
211→    const weights = this.calculateWeights(
212→      inliers,
213→      planeModel.model!,
214→      trackedFeatures,
215→      depthMap,
216→      mapWidth,
217→      mapHeight
218→    );
219→
220→    const { a, b, c } = weightedPlaneFit2D(inliers, weights);
221→
222→    // NaNチェックと異常値の補正
223→    const isValidNumber = (n: number) => !isNaN(n) && isFinite(n);
224→    const safeA = isValidNumber(a) ? a : 0;
225→    const safeB = isValidNumber(b) ? b : 0;
226→    const safeC = isValidNumber(c) ? c : -1;
227→
228→    return {
229→      a: safeA,
230→      b: safeB,
231→      c: -1,
232→      d: safeC,
233→    };
234→  }
235→
236→  /**
237→   * 重みを計算
238→   */
239→  private calculateWeights(
240→    inliers: Point3D[],
241→    planeModel: PlaneModel,
242→    trackedFeatures: Feature[],
243→    depthMap: Float32Array | null,
244→    mapWidth: number,
245→    mapHeight: number
246→  ): number[] {
247→    return inliers.map((pt, i) => {
248→      // 再投影誤差による重み
249→      const d = distancePointToPlane(pt, planeModel);
250→      const w_reproj = Math.exp(
251→        -((d / this.config.weights.reprojectionSigma) ** 2)
252→      );
253→
254→      // 深度勾配による重み（深度マップが利用可能な場合のみ）
255→      let w_grad = 1.0; // デフォルト値
256→
257→      if (depthMap && mapWidth > 0 && mapHeight > 0) {
258→        const x = Math.round(Math.min(Math.max(pt.x, 0), mapWidth - 1));
259→        const y = Math.round(Math.min(Math.max(pt.y, 0), mapHeight - 1));
260→
261→        const gx =
262→          x > 0 && x < mapWidth - 1
263→            ? Math.abs(
264→                depthMap[y * mapWidth + (x + 1)] -
265→                  depthMap[y * mapWidth + (x - 1)]
266→              )
267→            : 0;
268→        const gy =
269→          y > 0 && y < mapHeight - 1
270→            ? Math.abs(
271→                depthMap[(y + 1) * mapWidth + x] -
272→                  depthMap[(y - 1) * mapWidth + x]
273→              )
274→            : 0;
275→
276→        w_grad = 1 / (1 + gx + gy);
277→      }
278→
279→      // 追跡安定性による重み
280→      const trackCount = trackedFeatures[i]?.trackingCount ?? 1;
281→      const w_track = Math.min(
282→        trackCount / this.config.weights.maxTrackingFrames,
283→        1
284→      );
285→
286→      // 最終的な重み
287→      const finalWeight = Math.max(
288→        w_reproj * w_grad * w_track,
289→        this.config.weights.minWeight
290→      );
291→
292→      return isNaN(finalWeight) ? this.config.weights.minWeight : finalWeight;
293→    });
294→  }
295→
296→  /**
297→   * 平面座標系を構築
298→   */
299→  private constructPlaneCoordinates(
300→    refinedModel: PlaneModel,
301→    inliers: Point3D[],
302→    points3DBackProjected: Point3D[],
303→    centerFeature: Feature
304→  ): PlaneFittingResult | null {
305→    // 法線ベクトルを計算
306→    const n = new THREE.Vector3(
307→      refinedModel.a,
308→      refinedModel.b,
309→      refinedModel.c
310→    ).normalize();
311→
312→    if (n.lengthSq() === 0) {
313→      n.set(0, 0, 1);
314→    }
315→
316→    // 平面の基底ベクトルを計算
317→    const r = new THREE.Vector3(0, 1, 0);
318→    const u = new THREE.Vector3().crossVectors(n, r).normalize();
319→    const v = new THREE.Vector3().crossVectors(n, u).normalize();
320→
321→    // 中心点を見つける
322→    const centerPoint = points3DBackProjected.find(
323→      (p) => p.id === centerFeature.id
324→    );
325→    if (!centerPoint) return null;
326→
327→    const P0 = centerPoint;
328→
329→    // 2D投影
330→    const projectedPoints2D = projectInliersToPlane2D({
331→      inliers,
332→      P0,
333→      u,
334→      v,
335→    });
336→
337→    // 凸包を計算
338→    const hull2D = computeConvexHull2D(projectedPoints2D);
339→    const hull3D = liftHull2DTo3D({
340→      hull2D,
341→      P0,
342→      uVec: u,
343→      vVec: v,
344→    });
345→
346→    return {
347→      hull2D,
348→      hull3D,
349→      P0,
350→      uVec: u,
351→      vVec: v,
352→      normal: r,
353→    };
354→  }
355→
356→  /**
357→   * 結果を平均化
358→   */
359→  private calculateAverageResults(): PlaneFittingResult {
360→    const results = this.fittingResults;
361→
362→    // P0の平均
363→    const avgP0 = {
364→      x: results.reduce((sum, r) => sum + r.P0.x, 0) / results.length,
365→      y: results.reduce((sum, r) => sum + r.P0.y, 0) / results.length,
366→      z: results.reduce((sum, r) => sum + r.P0.z, 0) / results.length,
367→    };
368→
369→    // ベクトルの平均
370→    const avgUVec = new THREE.Vector3(
371→      results.reduce((sum, r) => sum + r.uVec.x, 0) / results.length,
372→      results.reduce((sum, r) => sum + r.uVec.y, 0) / results.length,
373→      results.reduce((sum, r) => sum + r.uVec.z, 0) / results.length
374→    ).normalize();
375→
376→    const avgVVec = new THREE.Vector3(
377→      results.reduce((sum, r) => sum + r.vVec.x, 0) / results.length,
378→      results.reduce((sum, r) => sum + r.vVec.y, 0) / results.length,
379→      results.reduce((sum, r) => sum + r.vVec.z, 0) / results.length
380→    ).normalize();
381→
382→    const avgNormal = new THREE.Vector3(
383→      results.reduce((sum, r) => sum + r.normal.x, 0) / results.length,
384→      results.reduce((sum, r) => sum + r.normal.y, 0) / results.length,
385→      results.reduce((sum, r) => sum + r.normal.z, 0) / results.length
386→    ).normalize();
387→
388→    // hull2Dの平均
389→    const baseHull2D = results[0].hull2D;
390→    const avgHull2D = baseHull2D.map((_, i) => ({
391→      u:
392→        results.reduce((sum, r) => sum + (r.hull2D[i]?.u || 0), 0) /
393→        results.length,
394→      v:
395→        results.reduce((sum, r) => sum + (r.hull2D[i]?.v || 0), 0) /
396→        results.length,
397→    }));
398→
399→    // hull3Dの平均
400→    const baseHull3D = results[0].hull3D;
401→    const avgHull3D = baseHull3D.map((_, i) => ({
402→      x:
403→        results.reduce((sum, r) => sum + (r.hull3D[i]?.x || 0), 0) /
404→        results.length,
405→      y:
406→        results.reduce((sum, r) => sum + (r.hull3D[i]?.y || 0), 0) /
407→        results.length,
408→      z:
409→        results.reduce((sum, r) => sum + (r.hull3D[i]?.z || 0), 0) /
410→        results.length,
411→    }));
412→
413→    return {
414→      hull2D: avgHull2D,
415→      hull3D: avgHull3D,
416→      P0: avgP0,
417→      uVec: avgUVec,
418→      vVec: avgVVec,
419→      normal: avgNormal,
420→    };
421→  }
422→}
