 64→  async loadModel() {
 65→    // モバイルデバイス検出
 66→    const isMobile =
 67→      /Android|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
 68→        navigator.userAgent
 69→      );
 70→    console.log("Device type:", isMobile ? "Mobile" : "Desktop");
 71→
 72→    // モバイルデバイスでは深度推定を無効化（ネットワーク制限により）
 73→    if (isMobile) {
 74→      console.warn(
 75→        "Depth estimation disabled on mobile devices due to network restrictions"
 76→      );
 77→      throw new Error(
 78→        "Depth estimation is not supported on mobile devices. The system will use fallback depth calculation."
 79→      );
 80→    }
 81→
 82→    const model_id = "onnx-community/depth-anything-v2-small";
 83→
 84→    try {
 85→      // CDN接続テスト
 86→      await this.testHuggingFaceConnection();
 87→
 88→      // WebGPU対応チェック
 89→      const checkWebGPUSupport = async () => {
 90→        if (!navigator.gpu) {
 91→          console.log("WebGPU not available: navigator.gpu not found");
 92→          return false;
 93→        }
 94→
 95→        try {
 96→          const adapter = await navigator.gpu.requestAdapter();
 97→          if (!adapter) {
 98→            console.log("WebGPU not available: no adapter found");
 99→            return false;
100→          }
101→
102→          const device = await adapter.requestDevice();
103→          if (!device) {
104→            console.log("WebGPU not available: no device found");
105→            return false;
106→          }
107→
108→          device.destroy();
109→          console.log("WebGPU available and tested successfully");
110→          return true;
111→        } catch (error) {
112→          const errorMessage =
113→            error instanceof Error ? error.message : String(error);
114→          console.log("WebGPU test failed:", errorMessage);
115→          return false;
116→        }
117→      };
118→
119→      const hasWebGPU = await checkWebGPUSupport();
120→
121→      const hasFp16 = async () => {
122→        if (!hasWebGPU) return false;
123→        try {
124→          const adapter = await navigator.gpu?.requestAdapter();
125→          return adapter?.features.has("shader-f16") ?? false;
126→        } catch {
127→          return false;
128→        }
129→      };
130→
131→      // デバイス別設定
132→      let deviceConfig: "wasm" | "webgpu";
133→      let dtypeConfig: "fp32" | "fp16";
134→
135→      if (isMobile) {
136→        // モバイル: WASMのみ、fp32固定
137→        deviceConfig = "wasm";
138→        dtypeConfig = "fp32";
139→        console.log("Mobile device: using WASM backend with fp32");
140→      } else {
141→        // デスクトップ: WebGPU優先、WASMフォールバック
142→        deviceConfig = hasWebGPU ? "webgpu" : "wasm";
143→        dtypeConfig = hasWebGPU && (await hasFp16()) ? "fp16" : "fp32";
144→        console.log(
145→          `Desktop device: using ${deviceConfig} backend with ${dtypeConfig}`
146→        );
147→      }
148→
149→      console.log("Model loading config:", {
150→        device: deviceConfig,
151→        dtype: dtypeConfig,
152→      });
153→
154→      // ネットワーク接続チェック
155→      if (!navigator.onLine) {
156→        throw new Error("No internet connection available for model download");
157→      }
158→
159→      // モバイル向けタイムアウト調整
160→      const timeoutDuration = isMobile ? 60000 : 30000; // モバイルでは60秒
161→
162→      // タイムアウト付きでモデル読み込み
163→      const modelLoadPromise = AutoModel.from_pretrained(model_id, {
164→        device: deviceConfig,
165→        dtype: dtypeConfig,
166→      });
167→
168→      const processorLoadPromise = AutoProcessor.from_pretrained(model_id);
169→
170→      const timeoutPromise = new Promise((_, reject) => {
171→        setTimeout(
172→          () => reject(new Error("Model loading timeout")),
173→          timeoutDuration
174→        );
175→      });
176→
177→      console.log(`Loading model with ${timeoutDuration / 1000}s timeout...`);
178→      [this.model, this.processor] = (await Promise.race([
179→        Promise.all([modelLoadPromise, processorLoadPromise]),
180→        timeoutPromise,
181→      ])) as [DepthModel, DepthProcessor];
182→
183→      // モバイルでは小さいサイズを使用
184→      const size = isMobile ? 256 : 504;
185→      this.processor.feature_extractor.size = { width: size, height: size };
186→
187→      console.log(
188→        `Depth estimation model loaded successfully with size: ${size}x${size}`
189→      );
190→    } catch (err) {
191→      console.error("Depth estimation initialization failed:", err);
192→      const errorMessage = err instanceof Error ? err.message : String(err);
193→
194→      // エラーの詳細分析
195→      if (errorMessage.includes("<!DOCTYPE")) {
196→        console.error("Network error: Received HTML instead of model data");
197→        throw new Error(
198→          "Model download failed: CDN returned HTML error page. This may be due to network restrictions or temporary service issues."
199→        );
200→      }
201→
202→      if (errorMessage.includes("timeout")) {
203→        console.error("Model loading timeout");
204→        throw new Error(
205→          "Model download timeout: The model files are too large or network is too slow. Please try again with a better internet connection."
206→        );
207→      }
208→
209→      if (errorMessage.includes("fetch")) {
210→        console.error("Network fetch error:", err);
211→        throw new Error(
212→          "Model download failed: Unable to download model files. Please check your internet connection and firewall settings."
213→        );
214→      }
215→
216→      if (errorMessage.includes("WebGPU")) {
217→        console.error("WebGPU error:", err);
218→        throw new Error(
219→          "WebGPU initialization failed. Your device may not support WebGPU."
220→        );
221→      }
222→
223→      if (errorMessage.includes("WASM")) {
224→        console.error("WASM backend error:", err);
225→        if (isMobile) {
226→          throw new Error(
227→            "WASM depth estimation failed on mobile device. Using fallback depth calculation."
228→          );
229→        } else {
230→          throw new Error(
231→            "WASM fallback failed. Please check browser compatibility."
232→          );
233→        }
234→      }
235→
236→      // 一般的なエラーハンドリング
237→      throw new Error(`Depth estimation setup failed: ${errorMessage}`);
238→    }
239→  }
