269→  async getDepthMap() {
270→    if (!this.model || !this.processor) {
271→      console.error("Model or processor not loaded");
272→      return;
273→    }
274→    if (this.isProcessing) return;
275→    this.isProcessing = true;
276→
277→    const currentFrame = this.context.getImageData(
278→      0,
279→      0,
280→      this.canvas.width,
281→      this.canvas.height
282→    );
283→    const image = new RawImage(
284→      currentFrame.data,
285→      this.canvas.width,
286→      this.canvas.height,
287→      4
288→    );
289→    const inputs = await this.processor(image);
290→    const { predicted_depth } = await this.model(inputs);
291→    this.depthMap = predicted_depth.data;
292→    const [, oh, ow] = predicted_depth.dims;
293→
294→    if (!this.depthMap) return;
295→
296→    let min = Infinity;
297→    let max = -Infinity;
298→    // this.depthCanvas.width = ow;
299→    // this.depthCanvas.height = oh;
300→    for (let i = 0; i < this.depthMap.length; ++i) {
301→      const v = this.depthMap[i];
302→      if (v < min) min = v;
303→      if (v > max) max = v;
304→    }
305→    const range = max - min;
306→
307→    const imageData = new Uint8ClampedArray(4 * this.depthMap.length);
308→    for (let i = 0; i < this.depthMap.length; ++i) {
309→      const offset = 4 * i;
310→      const normalizedDepth = (this.depthMap[i] - min) / range;
311→
312→      // RGBを深度値に基づいて設定（例：青から赤へのグラデーション）
313→      imageData[offset] = normalizedDepth * 255; // R
314→      imageData[offset + 1] = 0; // G
315→      imageData[offset + 2] = (1 - normalizedDepth) * 255; // B
316→      imageData[offset + 3] = 255; // Alpha（完全不透明）
317→    }
318→    const outPixelData = new ImageData(imageData, ow, oh);
319→
320→    // Reuse temporary canvas to prevent memory leak
321→    if (
322→      !this.temporaryCanvas ||
323→      this.temporaryCanvas.width !== ow ||
324→      this.temporaryCanvas.height !== oh
325→    ) {
326→      this.temporaryCanvas = document.createElement("canvas");
327→      this.temporaryCanvas.width = ow;
328→      this.temporaryCanvas.height = oh;
329→      this.temporaryContext = this.temporaryCanvas.getContext("2d");
330→    }
331→    this.temporaryContext!.putImageData(outPixelData, 0, 0);
332→    // if (this.depthContext) {
333→    //   this.depthContext.putImageData(outPixelData, 0, 0);
334→    // }
335→    this.depthContext!.clearRect(0, 0, this.canvas.width, this.canvas.height);
336→    this.depthContext!.drawImage(
337→      this.temporaryCanvas!,
338→      0,
339→      0,
340→      ow,
341→      oh,
342→      0,
343→      0,
344→      this.canvas.width,
345→      this.canvas.height
346→    );
347→
348→    this.isProcessing = false;
349→
350→    return this.depthMap;
351→  }
352→}
