  6→import * as THREE from "three";
  7→import type { CameraPose, MotionPrediction, CameraIntrinsics } from "../types/Pose";
  8→import type { Feature } from "../types/Feature";
  9→
 10→/**
 11→ * Motion Model Options
 12→ */
 13→export interface MotionModelOptions {
 14→  /** Velocity decay factor (0-1). Default: 0.95 */
 15→  velocityDecay?: number;
 16→  /** Maximum velocity magnitude (pixels/frame). Default: 50 */
 17→  maxVelocity?: number;
 18→  /** Search region scale factor. Default: 2.0 */
 19→  searchRegionScale?: number;
 20→  /** Minimum velocity magnitude to consider motion. Default: 0.1 */
 21→  minVelocityThreshold?: number;
 22→  /** Maximum prediction time horizon (ms). Default: 100 */
 23→  maxPredictionTimeMs?: number;
 24→}
 25→
 26→/**
 27→ * Motion Model
 28→ *
 29→ * Implements constant velocity motion model for camera pose prediction.
 30→ * Used to predict feature positions in the next frame for guided matching.
 31→ *
 32→ * The model tracks:
 33→ * - Linear velocity (translation rate)
 34→ * - Angular velocity (rotation rate)
 35→ *
 36→ * Predictions decay over time to handle motion changes.
 37→ */
 38→export class MotionModel {
 39→  private velocityDecay: number;
 40→  private maxVelocity: number;
 41→  private searchRegionScale: number;
 42→  private minVelocityThreshold: number;
 43→  private maxPredictionTimeMs: number;
 44→
 45→  private previousPose: CameraPose | null = null;
 46→  private linearVelocity: THREE.Vector3 = new THREE.Vector3();
 47→  private angularVelocity: THREE.Quaternion = new THREE.Quaternion();
 48→  private lastUpdateTimestamp: number = 0;
 49→  private velocityInitialized: boolean = false;
 50→
 51→  constructor(options?: MotionModelOptions) {
 52→    this.velocityDecay = options?.velocityDecay ?? 0.95;
 53→    this.maxVelocity = options?.maxVelocity ?? 50;
 54→    this.searchRegionScale = options?.searchRegionScale ?? 2.0;
 55→    this.minVelocityThreshold = options?.minVelocityThreshold ?? 0.1;
 56→    this.maxPredictionTimeMs = options?.maxPredictionTimeMs ?? 100;
 57→  }
 58→
 59→  /**
 60→   * Update motion model with new camera pose
 61→   *
 62→   * @param currentPose Current camera pose
 63→   */
 64→  public update(currentPose: CameraPose): void {
 65→    if (this.previousPose && currentPose.timestamp > this.previousPose.timestamp) {
 66→      const deltaTime = currentPose.timestamp - this.previousPose.timestamp;
 67→
 68→      if (deltaTime > 0) {
 69→        // Compute linear velocity
 70→        const newLinearVelocity = new THREE.Vector3()
 71→          .subVectors(currentPose.translation, this.previousPose.translation)
 72→          .divideScalar(deltaTime);
 73→
 74→        // Clamp velocity magnitude
 75→        const velocityMagnitude = newLinearVelocity.length();
 76→        if (velocityMagnitude > this.maxVelocity) {
 77→          newLinearVelocity.normalize().multiplyScalar(this.maxVelocity);
 78→        }
 79→
 80→        // Smooth velocity update with decay
 81→        if (this.velocityInitialized) {
 82→          this.linearVelocity.lerp(newLinearVelocity, 1 - this.velocityDecay);
 83→        } else {
 84→          this.linearVelocity.copy(newLinearVelocity);
 85→          this.velocityInitialized = true;
 86→        }
 87→
 88→        // Compute angular velocity as quaternion difference
 89→        const previousInverse = this.previousPose.quaternion.clone().invert();
 90→        const deltaRotation = currentPose.quaternion.clone().multiply(previousInverse);
 91→
 92→        // Smooth angular velocity
 93→        if (this.velocityInitialized) {
 94→          this.angularVelocity.slerp(deltaRotation, 1 - this.velocityDecay);
 95→        } else {
 96→          this.angularVelocity.copy(deltaRotation);
 97→        }
 98→      }
 99→    }
100→
101→    this.previousPose = {
102→      rotation: currentPose.rotation.clone(),
103→      translation: currentPose.translation.clone(),
104→      quaternion: currentPose.quaternion.clone(),
105→      timestamp: currentPose.timestamp,
106→      confidence: currentPose.confidence,
107→    };
108→    this.lastUpdateTimestamp = currentPose.timestamp;
109→  }
110→
111→  /**
112→   * Predict camera pose at a future timestamp
113→   *
114→   * @param timestamp Target timestamp for prediction
115→   * @returns Predicted pose
116→   */
117→  public predictPose(timestamp: number): CameraPose | null {
118→    if (!this.previousPose || !this.velocityInitialized) {
119→      return this.previousPose;
120→    }
121→
122→    const deltaTime = Math.min(
123→      timestamp - this.lastUpdateTimestamp,
124→      this.maxPredictionTimeMs
125→    );
126→
127→    if (deltaTime <= 0) {
128→      return this.previousPose;
129→    }
130→
131→    // Apply velocity decay for longer predictions
132→    const decayFactor = Math.pow(this.velocityDecay, deltaTime / 16.67); // Assuming 60fps base
133→
134→    // Predict translation
135→    const predictedTranslation = this.previousPose.translation
136→      .clone()
137→      .add(this.linearVelocity.clone().multiplyScalar(deltaTime * decayFactor));
138→
139→    // Predict rotation using SLERP from identity to angular velocity
140→    const predictedQuaternion = this.previousPose.quaternion.clone();
141→    const scaledAngularVelocity = new THREE.Quaternion().slerpQuaternions(
142→      new THREE.Quaternion(),
143→      this.angularVelocity,
144→      deltaTime * decayFactor
145→    );
146→    predictedQuaternion.multiply(scaledAngularVelocity);
147→
148→    // Convert quaternion to rotation matrix
149→    const predictedRotation = new THREE.Matrix3();
150→    const rotationMatrix4 = new THREE.Matrix4().makeRotationFromQuaternion(
151→      predictedQuaternion
152→    );
153→    predictedRotation.setFromMatrix4(rotationMatrix4);
154→
155→    return {
156→      rotation: predictedRotation,
157→      translation: predictedTranslation,
158→      quaternion: predictedQuaternion,
159→      timestamp,
160→      confidence: this.previousPose.confidence * decayFactor,
161→    };
162→  }
163→
164→  /**
165→   * Predict feature position in next frame
166→   *
167→   * @param feature Feature to predict position for
168→   * @param intrinsics Camera intrinsic parameters
169→   * @param deltaTimeMs Time delta for prediction (ms)
170→   * @returns Motion prediction with search region
171→   */
172→  public predictFeaturePosition(
173→    feature: Feature,
174→    intrinsics: CameraIntrinsics,
175→    deltaTimeMs: number = 16.67
176→  ): MotionPrediction {
177→    // Default prediction: same position with standard search region
178→    const defaultSearchRadius = 20 * this.searchRegionScale;
179→    const defaultPrediction: MotionPrediction = {
180→      predictedPosition: { x: feature.x, y: feature.y },
181→      searchRegion: {
182→        minX: Math.max(0, feature.x - defaultSearchRadius),
183→        minY: Math.max(0, feature.y - defaultSearchRadius),
184→        maxX: feature.x + defaultSearchRadius,
185→        maxY: feature.y + defaultSearchRadius,
186→      },
187→      confidence: 0.5,
188→    };
189→
190→    if (!this.velocityInitialized || !this.previousPose) {
191→      return defaultPrediction;
192→    }
193→
194→    // Apply velocity decay
195→    const decayFactor = Math.pow(this.velocityDecay, deltaTimeMs / 16.67);
196→    const scaledVelocity = this.linearVelocity.clone().multiplyScalar(decayFactor);
197→
198→    // Skip if velocity is too small
199→    if (scaledVelocity.length() < this.minVelocityThreshold) {
200→      return defaultPrediction;
201→    }
202→
203→    // Convert image point to normalized coordinates
204→    const normalizedX = (feature.x - intrinsics.cx) / intrinsics.fx;
205→    const normalizedY = (feature.y - intrinsics.cy) / intrinsics.fy;
206→
207→    // Create 3D ray direction (assuming point is at unit depth)
208→    const rayDirection = new THREE.Vector3(normalizedX, normalizedY, 1).normalize();
209→
210→    // Apply predicted rotation
211→    const scaledAngularVelocity = new THREE.Quaternion().slerpQuaternions(
212→      new THREE.Quaternion(),
213→      this.angularVelocity,
214→      deltaTimeMs * decayFactor
215→    );
216→    const rotatedDirection = rayDirection.clone().applyQuaternion(scaledAngularVelocity);
217→
218→    // Project back to image coordinates
219→    const predictedX = rotatedDirection.x / rotatedDirection.z * intrinsics.fx + intrinsics.cx;
220→    const predictedY = rotatedDirection.y / rotatedDirection.z * intrinsics.fy + intrinsics.cy;
221→
222→    // Add translation effect (approximation for nearby points)
223→    const translationEffect = scaledVelocity.clone().multiplyScalar(deltaTimeMs);
224→    const finalX = predictedX + translationEffect.x;
225→    const finalY = predictedY + translationEffect.y;
226→
227→    // Compute search region based on velocity magnitude
228→    const velocityMagnitude = scaledVelocity.length();
229→    const searchRadius = Math.max(10, velocityMagnitude * deltaTimeMs) * this.searchRegionScale;
230→
231→    // Clamp to image bounds if known
232→    const clampedMinX = intrinsics.width
233→      ? Math.max(0, Math.min(intrinsics.width, finalX - searchRadius))
234→      : finalX - searchRadius;
235→    const clampedMinY = intrinsics.height
236→      ? Math.max(0, Math.min(intrinsics.height, finalY - searchRadius))
237→      : finalY - searchRadius;
238→    const clampedMaxX = intrinsics.width
239→      ? Math.max(0, Math.min(intrinsics.width, finalX + searchRadius))
240→      : finalX + searchRadius;
241→    const clampedMaxY = intrinsics.height
242→      ? Math.max(0, Math.min(intrinsics.height, finalY + searchRadius))
243→      : finalY + searchRadius;
244→
245→    // Confidence based on velocity stability and time horizon
246→    const timeConfidence = Math.exp(-deltaTimeMs / this.maxPredictionTimeMs);
247→    const velocityConfidence = Math.min(1, velocityMagnitude / this.maxVelocity);
248→
249→    return {
250→      predictedPosition: { x: finalX, y: finalY },
251→      searchRegion: {
252→        minX: clampedMinX,
253→        minY: clampedMinY,
254→        maxX: clampedMaxX,
255→        maxY: clampedMaxY,
256→      },
257→      confidence: timeConfidence * (0.5 + 0.5 * velocityConfidence),
258→    };
259→  }
260→
261→  /**
262→   * Get predicted search regions for multiple features
263→   *
264→   * @param features Features to predict
265→   * @param intrinsics Camera intrinsic parameters
266→   * @param deltaTimeMs Time delta for prediction
267→   * @returns Map of feature ID to motion prediction
268→   */
269→  public getPredictedSearchRegions(
270→    features: Feature[],
271→    intrinsics: CameraIntrinsics,
272→    deltaTimeMs: number = 16.67
273→  ): Map<string, MotionPrediction> {
274→    const predictions = new Map<string, MotionPrediction>();
275→
276→    for (const feature of features) {
277→      if (feature.id) {
278→        const prediction = this.predictFeaturePosition(feature, intrinsics, deltaTimeMs);
279→        predictions.set(feature.id, prediction);
280→      }
281→    }
282→
283→    return predictions;
284→  }
285→
286→  /**
287→   * Get current linear velocity
288→   */
289→  public getLinearVelocity(): THREE.Vector3 {
290→    return this.linearVelocity.clone();
291→  }
292→
293→  /**
294→   * Get current angular velocity (as quaternion)
295→   */
296→  public getAngularVelocity(): THREE.Quaternion {
297→    return this.angularVelocity.clone();
298→  }
299→
300→  /**
301→   * Get velocity magnitude
302→   */
303→  public getVelocityMagnitude(): number {
304→    return this.linearVelocity.length();
305→  }
306→
307→  /**
308→   * Check if motion model is initialized with velocity data
309→   */
310→  public isInitialized(): boolean {
311→    return this.velocityInitialized;
312→  }
313→
314→  /**
315→   * Check if camera is moving based on velocity threshold
316→   */
317→  public isMoving(): boolean {
318→    return this.linearVelocity.length() > this.minVelocityThreshold;
319→  }
320→
321→  /**
322→   * Update options
323→   */
324→  public updateOptions(options: Partial<MotionModelOptions>): void {
325→    if (options.velocityDecay !== undefined) {
326→      this.velocityDecay = options.velocityDecay;
327→    }
328→    if (options.maxVelocity !== undefined) {
329→      this.maxVelocity = options.maxVelocity;
330→    }
331→    if (options.searchRegionScale !== undefined) {
332→      this.searchRegionScale = options.searchRegionScale;
333→    }
334→    if (options.minVelocityThreshold !== undefined) {
335→      this.minVelocityThreshold = options.minVelocityThreshold;
336→    }
337→    if (options.maxPredictionTimeMs !== undefined) {
338→      this.maxPredictionTimeMs = options.maxPredictionTimeMs;
339→    }
340→  }
341→
342→  /**
343→   * Reset motion model state
344→   */
345→  public reset(): void {
346→    this.previousPose = null;
347→    this.linearVelocity.set(0, 0, 0);
348→    this.angularVelocity.identity();
349→    this.lastUpdateTimestamp = 0;
350→    this.velocityInitialized = false;
351→  }
352→
353→  /**
354→   * Dispose resources
355→   */
356→  public dispose(): void {
357→    this.reset();
358→  }
359→}
