  6→import * as THREE from "three";
  7→
  8→/**
  9→ * 相補フィルタの設定オプション
 10→ */
 11→export interface ComplementaryFilterOptions {
 12→  /** IMU重み（0-1、高いほどIMUを信頼）デフォルト: 0.98 */
 13→  alpha?: number;
 14→  /** 最小視覚信頼度（これ以下では視覚を無視）デフォルト: 0.3 */
 15→  minVisualConfidence?: number;
 16→  /** スムージング係数（0-1、高いほど滑らか）デフォルト: 0.1 */
 17→  smoothingFactor?: number;
 18→}
 19→
 20→/**
 21→ * 相補フィルタ
 22→ *
 23→ * IMU（高周波・ドリフトあり）と視覚（低周波・安定）を組み合わせて
 24→ * 安定した姿勢推定を実現する
 25→ *
 26→ * 融合式: output = alpha * imu + (1 - alpha) * visual
 27→ * - alpha が高い（0.98）: IMUの高速応答を維持しつつ、視覚でドリフト補正
 28→ * - alpha が低い（0.5）: 視覚をより信頼（ただし遅延が増える）
 29→ */
 30→export class ComplementaryFilter {
 31→  private alpha: number;
 32→  private baseAlpha: number;
 33→  private minVisualConfidence: number;
 34→  private smoothingFactor: number;
 35→
 36→  private previousOutput: THREE.Quaternion | null = null;
 37→  private lastVisualTimestamp: number = 0;
 38→
 39→  // Reusable objects to prevent GC pressure
 40→  private readonly reusableFusedQuaternion: THREE.Quaternion =
 41→    new THREE.Quaternion();
 42→  private readonly reusableSmoothedQuaternion: THREE.Quaternion =
 43→    new THREE.Quaternion();
 44→
 45→  constructor(options?: ComplementaryFilterOptions) {
 46→    this.alpha = options?.alpha ?? 0.98;
 47→    this.baseAlpha = this.alpha;
 48→    this.minVisualConfidence = options?.minVisualConfidence ?? 0.3;
 49→    this.smoothingFactor = options?.smoothingFactor ?? 0.1;
 50→  }
 51→
 52→  /**
 53→   * IMU姿勢と視覚姿勢を融合
 54→   *
 55→   * @param imuOrientation IMUからの姿勢（クォータニオン）
 56→   * @param visualOrientation 視覚からの姿勢（null可）
 57→   * @param visualConfidence 視覚の信頼度（0-1）
 58→   * @returns 融合された姿勢
 59→   * Note: Returns reusable quaternion - caller should copy if needed
 60→   */
 61→  public fuse(
 62→    imuOrientation: THREE.Quaternion,
 63→    visualOrientation: THREE.Quaternion | null,
 64→    visualConfidence: number
 65→  ): THREE.Quaternion {
 66→    // 視覚情報がない、または信頼度が低い場合はIMUのみ使用
 67→    if (!visualOrientation || visualConfidence < this.minVisualConfidence) {
 68→      return this.applySmoothing(imuOrientation);
 69→    }
 70→
 71→    // 視覚情報のタイムスタンプを記録
 72→    this.lastVisualTimestamp = Date.now();
 73→
 74→    // 信頼度に基づいてalphaを動的調整
 75→    this.updateAlpha(visualConfidence);
 76→
 77→    // クォータニオンのSLERP（球面線形補間）で融合 - reuse quaternion
 78→    this.reusableFusedQuaternion.slerpQuaternions(
 79→      visualOrientation,
 80→      imuOrientation,
 81→      this.alpha
 82→    );
 83→
 84→    return this.applySmoothing(this.reusableFusedQuaternion);
 85→  }
 86→
 87→  /**
 88→   * 視覚信頼度に基づいてalphaを動的調整
 89→   *
 90→   * 高信頼度: alphaを下げて視覚を重視
 91→   * 低信頼度: alphaを上げてIMUを重視
 92→   */
 93→  public updateAlpha(visualConfidence: number): void {
 94→    // 信頼度が高いほどalphaを下げる（視覚を重視）
 95→    // 例: confidence=1.0 -> alpha=0.90, confidence=0.5 -> alpha=0.95
 96→    const adjustmentRange = 0.1; // baseAlphaからの調整幅
 97→    const adjustment = adjustmentRange * (1 - visualConfidence);
 98→    this.alpha = Math.max(
 99→      0.5,
100→      Math.min(0.99, this.baseAlpha - adjustmentRange + adjustment)
101→    );
102→  }
103→
104→  /**
105→   * スムージングを適用
106→   * 急激な姿勢変化を滑らかにする
107→   * Note: Returns reusable quaternion - caller should copy if needed
108→   */
109→  private applySmoothing(orientation: THREE.Quaternion): THREE.Quaternion {
110→    if (!this.previousOutput) {
111→      this.previousOutput = new THREE.Quaternion().copy(orientation);
112→      return orientation;
113→    }
114→
115→    // SLERPでスムージング - reuse quaternion
116→    this.reusableSmoothedQuaternion.slerpQuaternions(
117→      this.previousOutput,
118→      orientation,
119→      1 - this.smoothingFactor
120→    );
121→
122→    this.previousOutput.copy(this.reusableSmoothedQuaternion);
123→    return this.reusableSmoothedQuaternion;
124→  }
125→
126→  /**
127→   * ドリフト補正用：視覚姿勢で強制リセット
128→   *
129→   * @param visualOrientation 基準となる視覚姿勢
130→   */
131→  public resetToVisual(visualOrientation: THREE.Quaternion): void {
132→    if (!this.previousOutput) {
133→      this.previousOutput = new THREE.Quaternion();
134→    }
135→    this.previousOutput.copy(visualOrientation);
136→    this.lastVisualTimestamp = Date.now();
137→  }
138→
139→  /**
140→   * 最後の視覚更新からの経過時間を取得
141→   */
142→  public getTimeSinceLastVisualUpdate(): number {
143→    if (this.lastVisualTimestamp === 0) {
144→      return Infinity;
145→    }
146→    return Date.now() - this.lastVisualTimestamp;
147→  }
148→
149→  /**
150→   * 視覚情報が古くなっているか判定
151→   *
152→   * @param thresholdMs 閾値（ミリ秒）デフォルト: 1000ms
153→   */
154→  public isVisualStale(thresholdMs: number = 1000): boolean {
155→    return this.getTimeSinceLastVisualUpdate() > thresholdMs;
156→  }
157→
158→  /**
159→   * 現在のalpha値を取得
160→   */
161→  public getAlpha(): number {
162→    return this.alpha;
163→  }
164→
165→  /**
166→   * 設定をリセット
167→   */
168→  public reset(): void {
169→    this.alpha = this.baseAlpha;
170→    this.previousOutput = null;
171→    this.lastVisualTimestamp = 0;
172→  }
173→
174→  /**
175→   * リソース解放
176→   */
177→  public dispose(): void {
178→    this.reset();
179→  }
180→}
