  6→import * as THREE from "three";
  7→import type {
  8→  IMUBiases,
  9→  IMUMeasurement,
 10→  IMUNoiseParameters,
 11→  PreintegrationResult,
 12→} from "../types/Pose";
 13→
 14→/**
 15→ * IMU Preintegration Options
 16→ */
 17→export interface IMUPreintegrationOptions {
 18→  /** Accelerometer noise density (m/s²/√Hz). Default: 0.01 */
 19→  accelerometerNoiseDensity?: number;
 20→  /** Gyroscope noise density (rad/s/√Hz). Default: 0.001 */
 21→  gyroscopeNoiseDensity?: number;
 22→  /** Accelerometer random walk (m/s³/√Hz). Default: 0.0001 */
 23→  accelerometerRandomWalk?: number;
 24→  /** Gyroscope random walk (rad/s²/√Hz). Default: 0.00001 */
 25→  gyroscopeRandomWalk?: number;
 26→  /** Gravity magnitude (m/s²). Default: 9.80665 */
 27→  gravityMagnitude?: number;
 28→}
 29→
 30→/**
 31→ * IMU Preintegration
 32→ *
 33→ * Integrates IMU measurements between two keyframes without knowing
 34→ * the absolute pose. This allows efficient re-linearization when
 35→ * biases are updated.
 36→ *
 37→ * Based on the preintegration theory from:
 38→ * "On-Manifold Preintegration for Real-Time Visual-Inertial Odometry"
 39→ * by Forster et al.
 40→ *
 41→ * The preintegration computes:
 42→ * - Δp: Position change in body frame
 43→ * - Δv: Velocity change in body frame
 44→ * - Δq: Rotation change as quaternion
 45→ * - Covariance propagation for uncertainty estimation
 46→ */
 47→export class IMUPreintegration {
 48→  private noiseParams: IMUNoiseParameters;
 49→  private gravityMagnitude: number;
 50→
 51→  // Preintegrated measurements
 52→  private deltaPosition: THREE.Vector3 = new THREE.Vector3();
 53→  private deltaVelocity: THREE.Vector3 = new THREE.Vector3();
 54→  private deltaRotation: THREE.Quaternion = new THREE.Quaternion();
 55→
 56→  // Covariance matrix (9x9: position, velocity, rotation)
 57→  private covariance: number[] = new Array(81).fill(0);
 58→
 59→  // Jacobians for bias correction
 60→  private jacobianPositionBiasAccel: THREE.Matrix3 = new THREE.Matrix3();
 61→  private jacobianPositionBiasGyro: THREE.Matrix3 = new THREE.Matrix3();
 62→  private jacobianVelocityBiasAccel: THREE.Matrix3 = new THREE.Matrix3();
 63→  private jacobianVelocityBiasGyro: THREE.Matrix3 = new THREE.Matrix3();
 64→  private jacobianRotationBiasGyro: THREE.Matrix3 = new THREE.Matrix3();
 65→
 66→  // Current biases
 67→  private biases: IMUBiases;
 68→
 69→  // Integration state
 70→  private integrationTime: number = 0;
 71→  private measurementCount: number = 0;
 72→  private lastTimestamp: number = 0;
 73→
 74→  constructor(
 75→    initialBiases?: IMUBiases,
 76→    options?: IMUPreintegrationOptions
 77→  ) {
 78→    this.noiseParams = {
 79→      accelerometerNoiseDensity: options?.accelerometerNoiseDensity ?? 0.01,
 80→      gyroscopeNoiseDensity: options?.gyroscopeNoiseDensity ?? 0.001,
 81→      accelerometerRandomWalk: options?.accelerometerRandomWalk ?? 0.0001,
 82→      gyroscopeRandomWalk: options?.gyroscopeRandomWalk ?? 0.00001,
 83→    };
 84→
 85→    this.gravityMagnitude = options?.gravityMagnitude ?? 9.80665;
 86→
 87→    this.biases = initialBiases ?? {
 88→      accelerometerBias: new THREE.Vector3(),
 89→      gyroscopeBias: new THREE.Vector3(),
 90→    };
 91→
 92→    this.initializeJacobians();
 93→  }
 94→
 95→  /**
 96→   * Initialize Jacobian matrices to identity/zero
 97→   */
 98→  private initializeJacobians(): void {
 99→    this.jacobianPositionBiasAccel.identity().multiplyScalar(0);
100→    this.jacobianPositionBiasGyro.identity().multiplyScalar(0);
101→    this.jacobianVelocityBiasAccel.identity().multiplyScalar(0);
102→    this.jacobianVelocityBiasGyro.identity().multiplyScalar(0);
103→    this.jacobianRotationBiasGyro.identity().multiplyScalar(0);
104→  }
105→
106→  /**
107→   * Integrate a single IMU measurement
108→   *
109→   * @param measurement IMU measurement data
110→   */
111→  public integrate(measurement: IMUMeasurement): void {
112→    if (this.measurementCount === 0) {
113→      this.lastTimestamp = measurement.timestamp;
114→      this.measurementCount = 1;
115→      return;
116→    }
117→
118→    // Calculate delta time in seconds
119→    const deltaTime = (measurement.timestamp - this.lastTimestamp) / 1000;
120→    if (deltaTime <= 0 || deltaTime > 0.5) {
121→      // Skip invalid or too large time gaps
122→      this.lastTimestamp = measurement.timestamp;
123→      return;
124→    }
125→
126→    // Remove biases from measurements
127→    const acceleration = measurement.acceleration
128→      .clone()
129→      .sub(this.biases.accelerometerBias);
130→    const angularVelocity = measurement.angularVelocity
131→      .clone()
132→      .sub(this.biases.gyroscopeBias);
133→
134→    // Integrate rotation (using mid-point integration)
135→    const halfDeltaTheta = angularVelocity.clone().multiplyScalar(deltaTime / 2);
136→    const deltaQuat = this.expMap(halfDeltaTheta);
137→
138→    // Update rotation
139→    const previousRotation = this.deltaRotation.clone();
140→    this.deltaRotation.multiply(deltaQuat);
141→    this.deltaRotation.multiply(deltaQuat);
142→    this.deltaRotation.normalize();
143→
144→    // Rotate acceleration to body frame at start of interval
145→    const rotatedAccel = acceleration.clone().applyQuaternion(previousRotation);
146→
147→    // Update velocity (using mid-point)
148→    const previousVelocity = this.deltaVelocity.clone();
149→    this.deltaVelocity.add(rotatedAccel.clone().multiplyScalar(deltaTime));
150→
151→    // Update position
152→    this.deltaPosition.add(previousVelocity.clone().multiplyScalar(deltaTime));
153→    this.deltaPosition.add(
154→      rotatedAccel.clone().multiplyScalar(0.5 * deltaTime * deltaTime)
155→    );
156→
157→    // Update Jacobians for bias correction
158→    this.updateJacobians(deltaTime, rotatedAccel, angularVelocity);
159→
160→    // Propagate covariance
161→    this.propagateCovariance(deltaTime, rotatedAccel, angularVelocity);
162→
163→    this.integrationTime += deltaTime;
164→    this.measurementCount++;
165→    this.lastTimestamp = measurement.timestamp;
166→  }
167→
168→  /**
169→   * Exponential map: converts rotation vector to quaternion
170→   */
171→  private expMap(rotationVector: THREE.Vector3): THREE.Quaternion {
172→    const angle = rotationVector.length();
173→    if (angle < 1e-10) {
174→      return new THREE.Quaternion(
175→        rotationVector.x / 2,
176→        rotationVector.y / 2,
177→        rotationVector.z / 2,
178→        1
179→      ).normalize();
180→    }
181→
182→    const axis = rotationVector.clone().normalize();
183→    const halfAngle = angle / 2;
184→    const sinHalfAngle = Math.sin(halfAngle);
185→
186→    return new THREE.Quaternion(
187→      axis.x * sinHalfAngle,
188→      axis.y * sinHalfAngle,
189→      axis.z * sinHalfAngle,
190→      Math.cos(halfAngle)
191→    );
192→  }
193→
194→  /**
195→   * Update Jacobians for bias correction
196→   */
197→  private updateJacobians(
198→    deltaTime: number,
199→    _rotatedAccel: THREE.Vector3,
200→    _angularVelocity: THREE.Vector3
201→  ): void {
202→    // Simplified Jacobian updates
203→    // In full implementation, these would involve the rotation matrix derivatives
204→
205→    const dt2 = deltaTime * deltaTime / 2;
206→
207→    // Position w.r.t. accelerometer bias: -R * dt²/2
208→    // Simplified: accumulate diagonal terms
209→    const rotMatrix = new THREE.Matrix4().makeRotationFromQuaternion(
210→      this.deltaRotation
211→    );
212→    const rot3 = new THREE.Matrix3().setFromMatrix4(rotMatrix);
213→
214→    // Accumulate Jacobians (simplified version)
215→    for (let i = 0; i < 3; i++) {
216→      const idx = i * 3 + i;
217→      this.jacobianPositionBiasAccel.elements[idx] -= dt2;
218→      this.jacobianVelocityBiasAccel.elements[idx] -= deltaTime;
219→    }
220→
221→    // Rotation w.r.t. gyroscope bias
222→    for (let i = 0; i < 9; i++) {
223→      this.jacobianRotationBiasGyro.elements[i] -= rot3.elements[i] * deltaTime;
224→    }
225→  }
226→
227→  /**
228→   * Propagate covariance matrix
229→   */
230→  private propagateCovariance(
231→    deltaTime: number,
232→    _rotatedAccel: THREE.Vector3,
233→    _angularVelocity: THREE.Vector3
234→  ): void {
235→    // Simplified covariance propagation
236→    // Full implementation would use state transition matrix
237→
238→    const accelNoise =
239→      this.noiseParams.accelerometerNoiseDensity *
240→      this.noiseParams.accelerometerNoiseDensity *
241→      deltaTime;
242→    const gyroNoise =
243→      this.noiseParams.gyroscopeNoiseDensity *
244→      this.noiseParams.gyroscopeNoiseDensity *
245→      deltaTime;
246→
247→    // Add noise to diagonal elements
248→    // Position covariance (indices 0-2)
249→    for (let i = 0; i < 3; i++) {
250→      const idx = i * 9 + i;
251→      this.covariance[idx] += accelNoise * deltaTime * deltaTime;
252→    }
253→
254→    // Velocity covariance (indices 3-5)
255→    for (let i = 0; i < 3; i++) {
256→      const idx = (i + 3) * 9 + (i + 3);
257→      this.covariance[idx] += accelNoise;
258→    }
259→
260→    // Rotation covariance (indices 6-8)
261→    for (let i = 0; i < 3; i++) {
262→      const idx = (i + 6) * 9 + (i + 6);
263→      this.covariance[idx] += gyroNoise;
264→    }
265→  }
266→
267→  /**
268→   * Get the preintegration result
269→   */
270→  public getPreintegration(): PreintegrationResult {
271→    return {
272→      deltaPosition: this.deltaPosition.clone(),
273→      deltaVelocity: this.deltaVelocity.clone(),
274→      deltaRotation: this.deltaRotation.clone(),
275→      covariance: [...this.covariance],
276→      integrationTime: this.integrationTime,
277→      measurementCount: this.measurementCount,
278→    };
279→  }
280→
281→  /**
282→   * Correct preintegration for updated biases
283→   *
284→   * Uses first-order approximation to avoid re-integration
285→   */
286→  public correctByBias(newBiases: IMUBiases): PreintegrationResult {
287→    const deltaBiasAccel = newBiases.accelerometerBias
288→      .clone()
289→      .sub(this.biases.accelerometerBias);
290→    const deltaBiasGyro = newBiases.gyroscopeBias
291→      .clone()
292→      .sub(this.biases.gyroscopeBias);
293→
294→    // Correct position
295→    const correctedPosition = this.deltaPosition.clone();
296→    correctedPosition.add(
297→      this.applyMatrix3ToVector(
298→        this.jacobianPositionBiasAccel,
299→        deltaBiasAccel
300→      )
301→    );
302→    correctedPosition.add(
303→      this.applyMatrix3ToVector(
304→        this.jacobianPositionBiasGyro,
305→        deltaBiasGyro
306→      )
307→    );
308→
309→    // Correct velocity
310→    const correctedVelocity = this.deltaVelocity.clone();
311→    correctedVelocity.add(
312→      this.applyMatrix3ToVector(
313→        this.jacobianVelocityBiasAccel,
314→        deltaBiasAccel
315→      )
316→    );
317→    correctedVelocity.add(
318→      this.applyMatrix3ToVector(
319→        this.jacobianVelocityBiasGyro,
320→        deltaBiasGyro
321→      )
322→    );
323→
324→    // Correct rotation (first-order approximation)
325→    const deltaTheta = this.applyMatrix3ToVector(
326→      this.jacobianRotationBiasGyro,
327→      deltaBiasGyro
328→    );
329→    const correctedRotation = this.deltaRotation.clone();
330→    const correctionQuat = this.expMap(deltaTheta);
331→    correctedRotation.multiply(correctionQuat);
332→    correctedRotation.normalize();
333→
334→    return {
335→      deltaPosition: correctedPosition,
336→      deltaVelocity: correctedVelocity,
337→      deltaRotation: correctedRotation,
338→      covariance: [...this.covariance],
339→      integrationTime: this.integrationTime,
340→      measurementCount: this.measurementCount,
341→    };
342→  }
343→
344→  /**
345→   * Apply Matrix3 to Vector3
346→   */
347→  private applyMatrix3ToVector(
348→    matrix: THREE.Matrix3,
349→    vector: THREE.Vector3
350→  ): THREE.Vector3 {
351→    const e = matrix.elements;
352→    return new THREE.Vector3(
353→      e[0] * vector.x + e[3] * vector.y + e[6] * vector.z,
354→      e[1] * vector.x + e[4] * vector.y + e[7] * vector.z,
355→      e[2] * vector.x + e[5] * vector.y + e[8] * vector.z
356→    );
357→  }
358→
359→  /**
360→   * Update biases
361→   */
362→  public updateBiases(newBiases: IMUBiases): void {
363→    this.biases = {
364→      accelerometerBias: newBiases.accelerometerBias.clone(),
365→      gyroscopeBias: newBiases.gyroscopeBias.clone(),
366→    };
367→  }
368→
369→  /**
370→   * Get current biases
371→   */
372→  public getBiases(): IMUBiases {
373→    return {
374→      accelerometerBias: this.biases.accelerometerBias.clone(),
375→      gyroscopeBias: this.biases.gyroscopeBias.clone(),
376→    };
377→  }
378→
379→  /**
380→   * Get gravity magnitude
381→   */
382→  public getGravityMagnitude(): number {
383→    return this.gravityMagnitude;
384→  }
385→
386→  /**
387→   * Get noise parameters
388→   */
389→  public getNoiseParameters(): IMUNoiseParameters {
390→    return { ...this.noiseParams };
391→  }
392→
393→  /**
394→   * Get integration time
395→   */
396→  public getIntegrationTime(): number {
397→    return this.integrationTime;
398→  }
399→
400→  /**
401→   * Get measurement count
402→   */
403→  public getMeasurementCount(): number {
404→    return this.measurementCount;
405→  }
406→
407→  /**
408→   * Check if preintegration has enough data
409→   */
410→  public hasEnoughData(minMeasurements: number = 5): boolean {
411→    return this.measurementCount >= minMeasurements;
412→  }
413→
414→  /**
415→   * Get the covariance matrix diagonal (uncertainty in each dimension)
416→   */
417→  public getCovarianceDiagonal(): {
418→    position: THREE.Vector3;
419→    velocity: THREE.Vector3;
420→    rotation: THREE.Vector3;
421→  } {
422→    return {
423→      position: new THREE.Vector3(
424→        Math.sqrt(Math.max(0, this.covariance[0])),
425→        Math.sqrt(Math.max(0, this.covariance[10])),
426→        Math.sqrt(Math.max(0, this.covariance[20]))
427→      ),
428→      velocity: new THREE.Vector3(
429→        Math.sqrt(Math.max(0, this.covariance[30])),
430→        Math.sqrt(Math.max(0, this.covariance[40])),
431→        Math.sqrt(Math.max(0, this.covariance[50]))
432→      ),
433→      rotation: new THREE.Vector3(
434→        Math.sqrt(Math.max(0, this.covariance[60])),
435→        Math.sqrt(Math.max(0, this.covariance[70])),
436→        Math.sqrt(Math.max(0, this.covariance[80]))
437→      ),
438→    };
439→  }
440→
441→  /**
442→   * Reset preintegration
443→   */
444→  public reset(newBiases?: IMUBiases): void {
445→    this.deltaPosition.set(0, 0, 0);
446→    this.deltaVelocity.set(0, 0, 0);
447→    this.deltaRotation.set(0, 0, 0, 1);
448→    this.covariance.fill(0);
449→    this.integrationTime = 0;
450→    this.measurementCount = 0;
451→    this.lastTimestamp = 0;
452→
453→    this.initializeJacobians();
454→
455→    if (newBiases) {
456→      this.biases = {
457→        accelerometerBias: newBiases.accelerometerBias.clone(),
458→        gyroscopeBias: newBiases.gyroscopeBias.clone(),
459→      };
460→    }
461→  }
462→
463→  /**
464→   * Dispose resources
465→   */
466→  public dispose(): void {
467→    this.reset();
468→  }
469→}
