  9→/**
 10→ * 空間的平滑化：指定された座標周辺の深度値の平均を計算
 11→ * @param {Float32Array} depthMap - 深度マップ
 12→ * @param {number} centerX - 中心のX座標
 13→ * @param {number} centerY - 中心のY座標
 14→ * @param {number} mapWidth - 深度マップの幅
 15→ * @param {number} mapHeight - 深度マップの高さ
 16→ * @param {number} radius - 平滑化半径（デフォルト: 5, ((radius*2)+1)二乗px）
 17→ * @returns {number} 平滑化された深度値
 18→ */
 19→function getSpatiallySmoothedDepth(
 20→  depthMap: Float32Array<ArrayBufferLike>,
 21→  centerX: number,
 22→  centerY: number,
 23→  mapWidth: number,
 24→  mapHeight: number,
 25→  radius: number = 5
 26→): number {
 27→  let depthSum = 0;
 28→  let validCount = 0;
 29→
 30→  // 指定された半径内の全ピクセルをチェック
 31→  for (let dy = -radius; dy <= radius; dy++) {
 32→    for (let dx = -radius; dx <= radius; dx++) {
 33→      const x = centerX + dx;
 34→      const y = centerY + dy;
 35→
 36→      // 境界チェック
 37→      if (x >= 0 && x < mapWidth && y >= 0 && y < mapHeight) {
 38→        const depthIndex = y * mapWidth + x;
 39→        const depth = depthMap[depthIndex];
 40→
 41→        // 有効な深度値のみ累積
 42→        if (depth && depth > 0) {
 43→          depthSum += depth;
 44→          validCount++;
 45→        }
 46→      }
 47→    }
 48→  }
 49→
 50→  // 有効な深度値がある場合は平均を返す、ない場合は0を返す
 51→  return validCount > 0 ? depthSum / validCount : 0;
 52→}
 53→
 54→/**
 55→ * @param {Array<{ x: number, y: number }>} featurePoints  - 画像上の特徴点リスト（ピクセル座標、元の解像度）
 56→ * @param {Float32Array<ArrayBufferLike>} depthMap         - depth-estimation の出力深度マップ（一次元配列、行優先）
 57→ * @param {number} mapWidth                                - depthMap の横幅（ピクセル数）
 58→ * @param {number} mapHeight                               - depthMap の縦幅（ピクセル数）
 59→ * @param {number} featureWidth                            - 特徴点座標系の幅（省略時はmapWidth）
 60→ * @param {number} featureHeight                           - 特徴点座標系の高さ（省略時はmapHeight）
 61→ * @returns {Array<{ x: number, y: number, z: number, id: string }>}   - 各特徴点に対応する 3D 点群
 62→ */
 63→function sampleDepthAtFeaturePoints({
 64→  featurePoints,
 65→  depthMap,
 66→  mapWidth,
 67→  mapHeight,
 68→  featureWidth,
 69→  featureHeight,
 70→}: {
 71→  featurePoints: Feature[];
 72→  depthMap: Float32Array<ArrayBufferLike> | null;
 73→  mapWidth: number;
 74→  mapHeight: number;
 75→  featureWidth?: number;
 76→  featureHeight?: number;
 77→}): Array<{ x: number; y: number; z: number; id: string }> {
 78→  // Use provided feature dimensions or fall back to map dimensions
 79→  const srcWidth = featureWidth || mapWidth;
 80→  const srcHeight = featureHeight || mapHeight;
 81→  const points3D = [];
 82→
 83→  // 深度マップが利用できない場合のフォールバック
 84→  if (!depthMap) {
 85→    console.warn("Depth map not available, using fallback depth estimation");
 86→    for (const point of featurePoints) {
 87→      // 画面中央からの距離に基づく簡易深度推定
 88→      const centerX = srcWidth / 2;
 89→      const centerY = srcHeight / 2;
 90→      const distanceFromCenter = Math.sqrt(
 91→        Math.pow(point.x - centerX, 2) + Math.pow(point.y - centerY, 2)
 92→      );
 93→
 94→      // 距離に基づく簡易深度値の改善版
 95→      // より現実的な深度分布を作成（中央が近く、周辺が遠い）
 96→      const normalizedDistance =
 97→        distanceFromCenter / Math.max(centerX, centerY);
 98→      const fallbackDepth = 1.5 + Math.pow(normalizedDistance, 1.5) * 1.5; // 1.5-3.0の範囲
 99→
100→      points3D.push({
101→        x: point.x,
102→        y: point.y,
103→        z: fallbackDepth,
104→        id: point.id,
105→      });
106→    }
107→    return points3D;
108→  }
109→
110→  for (const point of featurePoints) {
111→    // 特徴点の座標を深度マップのサイズに合わせてスケーリング
112→    // srcWidth/Height: 特徴点座標系のサイズ（元の解像度）
113→    // mapWidth/Height: 深度マップのサイズ（スケール後の解像度）
114→    const scaledX = Math.floor((point.x * mapWidth) / srcWidth);
115→    const scaledY = Math.floor((point.y * mapHeight) / srcHeight);
116→
117→    // 深度マップの範囲内かチェック
118→    if (
119→      scaledX >= 0 &&
120→      scaledX < mapWidth &&
121→      scaledY >= 0 &&
122→      scaledY < mapHeight
123→    ) {
124→      // 空間的平滑化：周辺領域の平均深度を取得
125→      const smoothedDepth = getSpatiallySmoothedDepth(
126→        depthMap,
127→        scaledX,
128→        scaledY,
129→        mapWidth,
130→        mapHeight
131→      );
132→
133→      // 有効な深度値の場合のみ追加
134→      if (smoothedDepth && smoothedDepth > 0) {
135→        points3D.push({
136→          x: point.x,
137→          y: point.y,
138→          z: smoothedDepth,
139→          id: point.id,
140→        });
141→      }
142→    }
143→  }
144→
145→  return points3D;
146→}
147→
148→export default sampleDepthAtFeaturePoints;
