32→/**
33→ * Pose Estimator
34→ *
35→ * Estimates relative camera pose from 2D-2D point correspondences using
36→ * Essential Matrix computation with RANSAC and pose recovery.
37→ *
38→ * Pipeline:
39→ * 1. Normalize points using camera intrinsics
40→ * 2. Find Essential Matrix with RANSAC (5-point algorithm)
41→ * 3. Recover rotation and translation from Essential Matrix
42→ * 4. Select correct pose using cheirality check
43→ */
44→export class PoseEstimator {
45→  private cv: typeof cv;
46→  private intrinsics: CameraIntrinsics;
47→  private ransacProbability: number;
48→  private ransacThreshold: number;
49→  private minInliers: number;
50→  private maxIterations: number;
51→  private use5Point: boolean;
52→  private cameraMatrix: cv.Mat | null = null;
53→
54→  constructor(
55→    cvInstance: typeof cv,
56→    intrinsics: CameraIntrinsics,
57→    options?: PoseEstimatorOptions
58→  ) {
