648→  private async processPlaneDetection(): Promise<void> {
649→    // 既に平面が検出されている場合はスキップ
650→    if (this.stateManager.isPlaneDetected()) {
651→      return;
652→    }
653→
654→    this.stateManager.setState(SPALAMState.FITTING_PLANE);
655→
656→    const processInterval = setInterval(async () => {
657→      // フレーム処理
658→      const frameResult = await this.frameProcessor.processFrame();
659→      if (!frameResult || !frameResult.centerFeature) {
660→        return;
661→      }
662→
663→      // 深度マップが利用できない場合の警告（モバイル端末など）
664→      if (!frameResult.depthMap) {
665→        // フォールバック深度計算を使用
666→      }
667→
668→      // 平面フィッティングを実行
669→      await this.planeFittingService.performFitting(
670→        frameResult.features,
671→        frameResult.depthMap,
672→        this.frameProcessor.getCanvasWidth(),
673→        this.frameProcessor.getCanvasHeight(),
674→        frameResult.centerFeature,
675→        this.video?.videoWidth,
676→        this.video?.videoHeight
677→      );
678→
679→      // フィッティングが完了したかチェック
680→      if (this.planeFittingService.isComplete()) {
681→        clearInterval(processInterval);
682→
683→        // 平均化された結果を取得
684→        const avgResult = this.planeFittingService.getAveragedResult();
685→        if (avgResult) {
686→          this.createPlaneFromResult(avgResult);
687→          this.stateManager.setPlaneDetected(true, avgResult);
688→
689→          // 平面検出完了後は深度推定を無効化（CPU/メモリ節約）
690→          this.frameProcessor.setDepthEstimationEnabled(false);
691→
692→          // 平面検出イベントを発火
693→          const planeData: PlaneData = {
694→            position: new THREE.Vector3().copy(avgResult.P0),
695→            normal: new THREE.Vector3().copy(avgResult.normal),
696→            hull2D: avgResult.hull2D,
697→            hull3D: avgResult.hull3D,
698→            confidence: 1.0, // TODO: 実際の信頼度を計算
699→            size: {
700→              width:
701→                Math.max(...avgResult.hull2D.map((p) => p.u)) -
702→                Math.min(...avgResult.hull2D.map((p) => p.u)),
703→              height:
704→                Math.max(...avgResult.hull2D.map((p) => p.v)) -
705→                Math.min(...avgResult.hull2D.map((p) => p.v)),
706→            },
707→            detectedAt: Date.now(),
708→          };
709→          this.emit("plane:detected", planeData);
710→        }
711→      }
712→    }, 100); // 100msごとに処理
713→  }
