715→  /**
716→   * 平面を結果から作成
717→   */
718→  private createPlaneFromResult(result: PlaneFittingResult): void {
719→    const { hull2D, hull3D, P0, uVec, vVec, normal } = result;
720→
721→    // 中心点の計算
722→    const center = new THREE.Vector3();
723→    hull3D.forEach((p) => center.add(new THREE.Vector3(p.x, p.y, p.z)));
724→    center.divideScalar(hull3D.length);
725→
726→    // バウンディングボックスの計算
727→    const us = hull2D.map((p) => p.u),
728→      vs = hull2D.map((p) => p.v);
729→    const minU = Math.min(...us),
730→      maxU = Math.max(...us);
731→    const minV = Math.min(...vs),
732→      maxV = Math.max(...vs);
733→    const planeWidth = maxU - minU;
734→    const planeHeight = maxV - minV;
735→
736→    // ジオメトリの生成
737→    const scene = this.arRenderer!.getScene();
738→
739→    // 既存の平面グループがあれば削除
740→    const existingGroup = this.stateManager.getPlaneGroup();
741→    if (existingGroup) {
742→      scene.remove(existingGroup);
743→      existingGroup.traverse((child) => {
744→        if (child instanceof THREE.Mesh) {
745→          child.geometry.dispose();
746→          if (Array.isArray(child.material)) {
747→            child.material.forEach((mat) => mat.dispose());
748→          } else {
749→            child.material.dispose();
750→          }
751→        }
752→      });
753→    }
754→
755→    const group = new THREE.Group();
756→    const { planeMesh } = this.createPlaneGeometries(
757→      hull2D,
758→      planeWidth,
759→      planeHeight
760→    );
761→    group.add(planeMesh);
762→
763→    // 6面異なる色の立方体を追加（平面サイズの7割）
764→    const cubeSize = Math.min(planeWidth, planeHeight) * 0.7;
765→    const cubeMaterials = [
766→      new THREE.MeshBasicMaterial({
767→        color: 0xff0000,
768→        transparent: true,
769→        opacity: 0.8,
770→      }), // right: red
771→      new THREE.MeshBasicMaterial({
772→        color: 0x00ff00,
773→        transparent: true,
774→        opacity: 0.8,
775→      }), // left: green
776→      new THREE.MeshBasicMaterial({
777→        color: 0x0000ff,
778→        transparent: true,
779→        opacity: 0.8,
780→      }), // top: blue
781→      new THREE.MeshBasicMaterial({
782→        color: 0xffff00,
783→        transparent: true,
784→        opacity: 0.8,
785→      }), // bottom: yellow
786→      new THREE.MeshBasicMaterial({
787→        color: 0xff00ff,
788→        transparent: true,
789→        opacity: 0.8,
790→      }), // front: magenta
791→      new THREE.MeshBasicMaterial({
792→        color: 0x00ffff,
793→        transparent: true,
794→        opacity: 0.8,
795→      }), // back: cyan
796→    ];
797→    const cubeGeometry = new THREE.BoxGeometry(cubeSize, cubeSize, cubeSize);
798→    const cubeMesh = new THREE.Mesh(cubeGeometry, cubeMaterials);
799→    cubeMesh.position.set(0, 0, cubeSize / 2);
800→    group.add(cubeMesh);
801→
802→    scene.add(group);
803→
804→    // 位置と回転の調整
805→    this.adjustMeshTransform(group, P0, uVec, vVec, normal);
806→
807→    // 画面サイズに対して60%の大きさになるように初期スケールを計算
808→    const initialScale = this.computeScreenBasedInitialScale(P0.z, cubeSize);
809→    group.scale.set(initialScale, initialScale, initialScale);
810→    this.initialPlaneScale = initialScale;
811→
812→    // 状態マネージャーに保存
813→    this.stateManager.setPlaneGroup(group);
814→    this.arRenderer?.setCameraPosition(0, 0, 0);
815→
816→    // Phase 2.5: トラッキング品質改善機能を初期化
817→    this.initializePhase25Tracking(result);
